function AdvancedRoutineBuilderWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [view,setView]=useState<"Routine workspace"|"AM / PM plans"|"Compatibility"|"Budget & cart"|"Templates"|"Outcomes & quality">("Routine workspace");
  const [status,setStatus]=useState("All status");
  const [risk,setRisk]=useState("All risk");
  const [query,setQuery]=useState("");
  const [focused,setFocused]=useState<RoutinePlan|null>(null);
  const [notice,setNotice]=useState("");
  const [controlsOpen,setControlsOpen]=useState(false);
  const [maxUniqueProducts,setMaxUniqueProducts]=useState("4");
  const [requireCompatibility,setRequireCompatibility]=useState(true);
  const [requireStock,setRequireStock]=useState(true);
  const [requirePrice,setRequirePrice]=useState(true);
  const [requireConsent,setRequireConsent]=useState(true);
  const [noAutoSubstitution,setNoAutoSubstitution]=useState(true);
  const [controlReason,setControlReason]=useState("");
  const [controlConfirmed,setControlConfirmed]=useState(false);
  const [versionOpen,setVersionOpen]=useState(false);
  const [versionCustomer,setVersionCustomer]=useState("");
  const [versionGoal,setVersionGoal]=useState("");
  const [versionBudget,setVersionBudget]=useState("2000");
  const [versionComplexity,setVersionComplexity]=useState("Simple");
  const [versionAm,setVersionAm]=useState("");
  const [versionPm,setVersionPm]=useState("");
  const [versionIntro,setVersionIntro]=useState("Patch test first. Add one new step at a time and evaluate tolerance before expansion.");
  const [versionSource,setVersionSource]=useState("Beauty Passport");
  const [versionConsent,setVersionConsent]=useState(false);
  const [versionConfirmed,setVersionConfirmed]=useState(false);
  const [reviewOpen,setReviewOpen]=useState(false);
  const [reviewDecision,setReviewDecision]=useState("Approve routine version");
  const [reviewOwner,setReviewOwner]=useState("Nusrat");
  const [reviewNote,setReviewNote]=useState("");
  const [reviewCompatibility,setReviewCompatibility]=useState(false);
  const [reviewStock,setReviewStock]=useState(false);
  const [reviewPrice,setReviewPrice]=useState(false);
  const [reviewConsent,setReviewConsent]=useState(false);
  const [reviewConfirmed,setReviewConfirmed]=useState(false);
  const [cartOpen,setCartOpen]=useState(false);
  const [cartExpiry,setCartExpiry]=useState("24 hours");
  const [cartChannel,setCartChannel]=useState("Customer portal link");
  const [cartPrice,setCartPrice]=useState(false);
  const [cartStock,setCartStock]=useState(false);
  const [cartEditable,setCartEditable]=useState(true);
  const [cartNoDiscount,setCartNoDiscount]=useState(true);
  const [cartConsent,setCartConsent]=useState(false);
  const [cartConfirmed,setCartConfirmed]=useState(false);
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const openControls=()=>{setControlReason("");setControlConfirmed(false);setControlsOpen(true)};
  const openVersion=()=>{setVersionCustomer("");setVersionGoal("");setVersionBudget("2000");setVersionComplexity("Simple");setVersionAm("");setVersionPm("");setVersionIntro("Patch test first. Add one new step at a time and evaluate tolerance before expansion.");setVersionSource("Beauty Passport");setVersionConsent(false);setVersionConfirmed(false);setVersionOpen(true)};
  const openReview=()=>{setReviewDecision(focused?.status==="Blocked"||focused?.conflicts.length?"Block routine":"Approve routine version");setReviewOwner(focused?.owner||"Nusrat");setReviewNote("");setReviewCompatibility(false);setReviewStock(false);setReviewPrice(false);setReviewConsent(false);setReviewConfirmed(false);setReviewOpen(true)};
  const openCart=()=>{if(!focused||focused.status==="Blocked"||focused.conflicts.length||focused.consent!=="Active")return;setCartExpiry("24 hours");setCartChannel("Customer portal link");setCartPrice(false);setCartStock(false);setCartEditable(true);setCartNoDiscount(true);setCartConsent(false);setCartConfirmed(false);setCartOpen(true)};
  const statusTone=(value:RoutinePlanStatus)=>value==="Approved"||value==="Cart ready"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Blocked"?"bg-rose-100 text-rose-800 ring-rose-300":value==="Review required"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-[#edf3f4] text-[#3b646d] ring-[#cbdcda]";
  const riskTone=(value:RoutinePlanRisk)=>value==="Clear"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Watch"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-rose-100 text-rose-800 ring-rose-300";
  const uniqueProducts=(item:RoutinePlan)=>Array.from(new Set(item.steps.map(step=>step.sku))).length;
  const visible=routinePlans.filter(item=>(status==="All status"||item.status===status)&&(risk==="All risk"||item.risk===risk)&&(item.id+" "+item.passportId+" "+item.customer+" "+item.contact+" "+item.goal+" "+item.steps.map(step=>step.product).join(" ")).toLowerCase().includes(query.toLowerCase()));
  const compatibilityRows=[["COMP-084","RT-3036","Vitamin C active · pregnancy context","Hard hold","Qualified review required","No cart"],["COMP-081","RT-3014","Tea tree allergy · reaction evidence incomplete","Hard hold","Correct passport evidence","No substitution"],["COMP-078","RT-3042","Niacinamide daily use · prior dryness","Frequency watch","Every other morning","Review day 14"],["COMP-075","RT-3039","Salicylic serum + physical scrub","Avoid combination","Pause scrub","Alternate nights"],["COMP-071","RT-3031","Kojic Facewash unavailable","Stock hold","Wait or approved alternative","No auto-swap"],["COMP-067","RT-3019","Fragrance sensitivity","Preference rule","Fragrance-light leave-on","Monitor"]];
  const templates=[["TPL-01","Barrier-first simple routine","Dry / sensitive","3 unique products","Cleanse · moisturize · protect","৳2,200–3,000","Approved baseline"],["TPL-02","Oil-control beginner","Oily / combination","3 unique products","Cleanse · one support · protect","৳1,800–2,600","Human review"],["TPL-03","Tone-support minimal","Normal / combination","3 unique products","Cleanse · one tone step · protect","৳1,900–2,800","No whitening claim"],["TPL-04","Acne-support gradual","Oily / acne-prone","3 unique products","Cleanse · alternate-night active · protect","৳2,000–3,000","Safety gates"],["TPL-05","Budget two-step start","Any self-reported type","2 unique products","Cleanse · protect","৳1,200–1,800","Expansion after follow-up"],["TPL-06","Service-recovery reset","Irritated / uncertain","0 commerce actives","Stop new actives · clarify","No cart","Professional guidance if red flag"]];
  const qualityRows=[["Ingredient rule coverage","91%","Fresh 2h","12 mapping gaps"],["Live stock freshness","98%","Fresh 4m","Healthy"],["Published price match","100%","Fresh 6m","Protected"],["Routine outcome coverage","43%","Fresh 1d","Early dataset"],["Customer consent coverage","94%","Fresh 18m","5 unresolved"],["Auto-created orders","0","Never enabled","Human-controlled"]];
  const tabs=["Routine workspace","AM / PM plans","Compatibility","Budget & cart","Templates","Outcomes & quality"] as const;
  return <div className="space-y-5">
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Personalized commerce · human reviewed</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Advanced Routine Builder</h1><p className="mt-1.5 max-w-3xl text-[12.5px] leading-5 text-[#66736d]">Design the smallest compatible AM/PM routine that fits the customer’s goals, tolerance, budget, stock reality and consent.</p></div><div className="flex flex-wrap gap-2"><button onClick={openControls} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="settings" size={13}/>Routine controls</button><button onClick={openVersion} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="plus" size={13}/>New routine version</button></div></section>

    <section className="rounded-2xl border border-[#cfdedb] bg-[linear-gradient(135deg,#edf3f4_0%,#f9fbfa_65%,#fff_100%)] p-5"><div className="grid gap-5 xl:grid-cols-[minmax(0,1.35fr)_minmax(330px,.65fr)]"><div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-rose-100 px-2.5 py-1 text-[7px] font-bold text-rose-800 ring-1 ring-rose-200">3 blocked / held</span><span className="rounded-full bg-amber-50 px-2.5 py-1 text-[7px] font-bold text-amber-700 ring-1 ring-amber-200">2 need review</span><span className="rounded-full bg-emerald-100 px-2.5 py-1 text-[7px] font-bold text-emerald-800 ring-1 ring-emerald-200">2 cart eligible</span></div><h2 className="mt-4 text-[19px] font-bold tracking-[-.025em] text-[#29423f]">Resolve consent, compatibility and stock holds before turning any routine into a customer-facing cart draft.</h2><p className="mt-2 max-w-3xl text-[9px] leading-5 text-[#627873]">The best routine is not the largest basket. Current attention: one pregnancy-context hold, one allergy-evidence conflict and one out-of-stock routine.</p><div className="mt-4 flex flex-wrap gap-2">{[["Active versions","128"],["Within budget","87%"],["Average unique products","2.8"]].map(item=><div key={item[0]} className="rounded-xl bg-white px-3 py-2 ring-1 ring-[#dfe7e4]"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="ml-2 text-[7px] text-[#405b58]">{item[1]}</b></div>)}</div></div><aside className="rounded-2xl border border-white/80 bg-white/90 p-4 shadow-sm"><div className="flex items-center justify-between"><div><span className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Routine readiness</span><b className="mt-1 block text-[24px] text-[#304d4d]">81<span className="text-[12px] text-[#82928c]">/100</span></b></div><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#edf3f4] text-[#3b646d]"><Icon name="check" size={18}/></span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-[#e8ecea]"><div className="h-full w-[81%] rounded-full bg-[#5f8585]"/></div><div className="mt-4 grid grid-cols-3 gap-2 text-center">{[["Compatibility","91%"],["Stock","98%"],["Outcomes","43%"]].map(item=><div key={item[0]} className="rounded-xl bg-[#fafbfa] p-2.5"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1 block text-[8px] text-[#405049]">{item[1]}</b></div>)}</div></aside></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[["Active routines","128","17 updated 7D","Versioned","text-[#3b646d]"],["Review queue","11","4 high priority","Human decision","text-orange-700"],["Compatibility holds","6","No cart allowed","Protected","text-rose-700"],["Cart-ready","54","42% of active","Price + stock valid","text-purple-700"],["Within budget","87%","+4 pts","Current pricing","text-emerald-700"],["Auto-orders","0","Never enabled","Customer chooses","text-emerald-700"]].map(([label,value,change,meta,tone])=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between gap-2"><span className="text-[6.5px] font-bold uppercase tracking-[.1em] text-[#89948f]">{label}</span><span className="text-[6px] font-bold text-[#6d7b74]">{change}</span></div><b className={"mt-3 block text-[18px] tracking-[-.03em] "+tone}>{value}</b><p className="mt-2 text-[6.5px] leading-3.5 text-[#929d97]">{meta}</p></article>)}</section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{tabs.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d]")}>{item}<span className="ml-2 rounded-full bg-[#f1f4f2] px-1.5 py-0.5 text-[6.5px]">{item==="Routine workspace"?8:item==="AM / PM plans"?6:item==="Compatibility"?6:item==="Budget & cart"?8:item==="Templates"?6:6}</span></button>)}</div></div>
    {view==="Routine workspace"&&<><div className="flex flex-col gap-2 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:flex-row sm:p-5"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search routine, passport, customer, goal or product..." className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><select value={status} onChange={event=>setStatus(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f]"><option>All status</option><option>Draft</option><option>Review required</option><option>Approved</option><option>Cart ready</option><option>Blocked</option></select><select value={risk} onChange={event=>setRisk(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f]"><option>All risk</option><option>Clear</option><option>Watch</option><option>Conflict</option><option>Stock hold</option></select></div><div className="overflow-x-auto"><table className="w-full min-w-[1550px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Routine / customer</th><th className="px-4 py-3.5">Goal / profile</th><th className="px-4 py-3.5">Status / risk</th><th className="px-4 py-3.5">Routine design</th><th className="px-4 py-3.5">Budget</th><th className="px-4 py-3.5">Compatibility / stock</th><th className="px-4 py-3.5">Outcome / owner</th><th className="px-4 py-3.5"></th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{visible.map(item=><tr key={item.id} className="text-[8px] text-[#5f6e67] hover:bg-[#fbfcfb]"><td className="px-5 py-4"><b className="block text-[#405049]">{item.customer}</b><span className="mt-1 block font-mono text-[6.5px] text-[#929d97]">{item.id} · {item.version} · {item.passportId}</span><span className="mt-1 block text-[6px] text-[#929d97]">{item.contact} · {item.updated}</span></td><td className="px-4 py-4"><b className="block text-[#405049]">{item.goal}</b><span className="mt-1 block text-[6px] text-[#929d97]">{item.skinType}</span></td><td className="px-4 py-4"><div className="flex gap-1.5"><span className={"rounded-full px-2 py-1 text-[6px] font-bold ring-1 ring-inset "+statusTone(item.status)}>{item.status}</span><span className={"rounded-full px-2 py-1 text-[6px] font-bold ring-1 ring-inset "+riskTone(item.risk)}>{item.risk}</span></div><span className="mt-1 block text-[6px] text-[#929d97]">Consent: {item.consent}</span></td><td className="px-4 py-4"><b className="block text-[#52615a]">{uniqueProducts(item)} unique products</b><span className="mt-1 block text-[6px] text-[#929d97]">{item.steps.length} AM/PM placements · {item.complexity}</span></td><td className="px-4 py-4"><b className={item.total<=item.budget?"text-emerald-700":"text-rose-700"}>৳{item.total.toLocaleString()}</b><span className="mt-1 block text-[6px] text-[#929d97]">Budget ৳{item.budget.toLocaleString()} · {item.budget?item.total<=item.budget?"within budget":"over by ৳"+(item.total-item.budget).toLocaleString():"not set"}</span></td><td className="px-4 py-4"><b className={item.conflicts.length?"text-rose-700":"text-[#405049]"}>{item.conflicts.length?item.conflicts.length+" hold(s)":"No hard conflict"}</b><span className="mt-1 block text-[6px] text-[#929d97]">{item.steps.filter(step=>step.stock===0||step.state==="Low stock").length} stock watch · {item.cartState}</span></td><td className="px-4 py-4"><b className="block text-[#52615a]">{item.outcome}</b><span className="mt-1 block text-[6px] text-[#929d97]">{item.owner} · {item.adherence}% adherence</span></td><td className="px-4 py-4"><button onClick={()=>setFocused(item)} className="h-8 rounded-lg border border-[#cfdedb] px-3 text-[7px] font-bold text-[#3b646d]">Review</button></td></tr>)}</tbody></table></div></>}
    {view==="AM / PM plans"&&<div className="grid gap-3 p-4 sm:p-5 lg:grid-cols-2">{routinePlans.filter(item=>item.steps.length>0).slice(0,6).map(item=><article key={item.id} className="rounded-2xl border border-[#e2e8e5] p-4"><div className="flex items-start justify-between gap-3"><div><div className="flex gap-1.5"><span className={"rounded-full px-2 py-1 text-[6px] font-bold ring-1 ring-inset "+statusTone(item.status)}>{item.status}</span><span className={"rounded-full px-2 py-1 text-[6px] font-bold ring-1 ring-inset "+riskTone(item.risk)}>{item.risk}</span></div><h3 className="mt-2 text-[10px] font-bold text-[#405049]">{item.customer} · {item.goal}</h3><p className="mt-1 text-[6.5px] text-[#929d97]">{item.id} · {item.version} · {item.complexity}</p></div><button onClick={()=>setFocused(item)} className="rounded-xl border border-[#cfdedb] px-3 py-2 text-[7px] font-bold text-[#3b646d]">Open</button></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{(["AM","PM"] as const).map(period=><div key={period} className="rounded-xl bg-[#fafbfa] p-3"><span className="text-[6px] font-bold text-[#929d97]">{period}</span><div className="mt-2 space-y-2">{item.steps.filter(step=>step.period===period).map(step=><div key={period+step.order+step.sku} className="flex gap-2 text-[7px] leading-4 text-[#52615a]"><b className="text-[#3b646d]">{step.order}.</b><span>{step.product}<small className="block text-[6px] text-[#929d97]">{step.frequency} · {step.introduction}</small></span></div>)}</div></div>)}</div></article>)}</div>}
    {view==="Compatibility"&&<div className="overflow-x-auto"><table className="w-full min-w-[1100px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Check / routine</th><th className="px-4 py-3.5">Signal</th><th className="px-4 py-3.5">Severity</th><th className="px-4 py-3.5">Required treatment</th><th className="px-4 py-3.5">Commerce boundary</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{compatibilityRows.map(item=><tr key={item[0]} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4"><b className="font-mono text-[#405049]">{item[0]}</b><span className="ml-3 font-bold">{item[1]}</span></td><td className="px-4 py-4 font-bold">{item[2]}</td><td className="px-4 py-4"><span className={"rounded-full px-2 py-1 text-[6px] font-bold "+(item[3]==="Hard hold"?"bg-rose-100 text-rose-800":"bg-amber-50 text-amber-700")}>{item[3]}</span></td><td className="px-4 py-4">{item[4]}</td><td className="px-4 py-4 font-bold text-[#3b646d]">{item[5]}</td></tr>)}</tbody></table></div>}
    {view==="Budget & cart"&&<div className="overflow-x-auto"><table className="w-full min-w-[1200px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Routine</th><th className="px-4 py-3.5">Unique products</th><th className="px-4 py-3.5">Budget</th><th className="px-4 py-3.5">Current total</th><th className="px-4 py-3.5">Variance</th><th className="px-4 py-3.5">Stock readiness</th><th className="px-4 py-3.5">Cart state</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{routinePlans.map(item=><tr key={item.id} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4"><b className="text-[#405049]">{item.customer}</b><span className="ml-2 font-mono text-[6.5px] text-[#929d97]">{item.id}</span></td><td className="px-4 py-4">{uniqueProducts(item)} · {item.complexity}</td><td className="px-4 py-4">৳{item.budget.toLocaleString()}</td><td className="px-4 py-4 font-bold">৳{item.total.toLocaleString()}</td><td className={"px-4 py-4 font-bold "+(item.budget&&item.total>item.budget?"text-rose-700":"text-emerald-700")}>{item.budget?item.total<=item.budget?"৳"+(item.budget-item.total).toLocaleString()+" available":"৳"+(item.total-item.budget).toLocaleString()+" over":"Not set"}</td><td className="px-4 py-4">{item.steps.some(step=>step.stock===0)?"Out of stock":item.steps.some(step=>step.state==="Low stock")?"Low-stock watch":"Ready"}</td><td className="px-4 py-4 font-bold text-[#3b646d]">{item.cartState}</td></tr>)}</tbody></table></div>}
    {view==="Templates"&&<div className="grid gap-3 p-4 sm:p-5 lg:grid-cols-2">{templates.map(item=><article key={item[0]} className="rounded-2xl border border-[#e2e8e5] p-4"><div className="flex items-start justify-between gap-3"><div><span className="font-mono text-[6.5px] font-bold text-[#3b646d]">{item[0]}</span><h3 className="mt-1.5 text-[10px] font-bold text-[#405049]">{item[1]}</h3><p className="mt-1.5 text-[7px] text-[#87928d]">{item[2]} · {item[3]}</p></div><span className="rounded-xl bg-[#edf3f4] px-3 py-2 text-[7px] font-bold text-[#3b646d]">{item[5]}</span></div><div className="mt-4 grid grid-cols-2 gap-2 rounded-xl bg-[#fafbfa] p-3 text-[7px]"><div><span className="text-[#929d97]">Structure</span><b className="mt-1 block text-[#52615a]">{item[4]}</b></div><div><span className="text-[#929d97]">Boundary</span><b className="mt-1 block text-[#52615a]">{item[6]}</b></div></div></article>)}</div>}
    {view==="Outcomes & quality"&&<div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1.15fr)_minmax(340px,.85fr)]"><div className="divide-y divide-[#edf0ee] rounded-xl border border-[#e2e8e5]">{qualityRows.map(item=><div key={item[0]} className="grid grid-cols-[minmax(0,1fr)_65px_90px_130px] items-center gap-3 p-4 text-[7px]"><b className="text-[8px] text-[#405049]">{item[0]}</b><b className="text-[#3b646d]">{item[1]}</b><span className="text-[#65736c]">{item[2]}</span><span className="text-right font-bold text-[#87928d]">{item[3]}</span></div>)}</div><aside className="space-y-3"><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[9px] text-[#405b58]">Outcome before expansion</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">Add steps only after the customer reports tolerance and the current routine is understandable, affordable and usable.</p></div><div className="rounded-xl border border-rose-200 bg-rose-50/60 p-4"><b className="text-[9px] text-rose-800">Cart is not an order</b><p className="mt-2 text-[7px] leading-4 text-rose-800">A cart draft uses current published price and stock. The customer still chooses whether to open, edit and place an order.</p></div><button onClick={()=>onNavigate("Inventory")} className="h-10 w-full rounded-xl border border-[#bfd0cc] bg-white text-[8px] font-bold text-[#3b646d]">Review routine stock</button></aside></div>}</section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Minimum effective routine</p><b className="mt-1.5 block text-[10px] text-[#405049]">Start smaller, expand from outcomes</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">One clear purpose per step improves adherence and reduces unnecessary active stacking.</p></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Budget is a hard input</p><b className="mt-1.5 block text-[10px] text-[#405049]">Simplify before inventing a discount</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">The builder uses published prices and approved offers only; substitution always needs review.</p></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5e7875]">Implementation truth</p><b className="mt-1.5 block text-[10px] text-[#304d4d]">Production needs ingredient, inventory and cart-service backend work</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">Routine versions, compatibility rules, schedules, stock/price snapshots, approved substitutions, share links and outcome events require backend development.</p></article></section>

    {focused&&<div className="fixed inset-0 z-[80] bg-[#17231f]/25 backdrop-blur-[1px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-2xl overflow-y-auto bg-white shadow-[-24px_0_70px_rgba(18,37,31,.16)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><div className="flex flex-wrap items-center gap-2"><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+statusTone(focused.status)}>{focused.status}</span><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+riskTone(focused.risk)}>{focused.risk}</span><span className="text-[6.5px] font-bold text-[#65736c]">{focused.consent} consent</span></div><h2 className="mt-2 text-[17px] font-bold text-[#23322b]">{focused.customer} · {focused.goal}</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused.id} · {focused.version} · {focused.passportId} · {focused.updated}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid grid-cols-4 gap-2">{[["Budget","৳"+focused.budget.toLocaleString()],["Current total","৳"+focused.total.toLocaleString()],["Unique products",String(uniqueProducts(focused))],["Adherence",focused.adherence+"%"]].map(item=><div key={item[0]} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1 block truncate text-[8px] text-[#405049]">{item[1]}</b></div>)}</div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Routine context</b><div className="mt-3 grid grid-cols-3 gap-2 border-t border-[#d6e2df] pt-3">{[["Profile",focused.skinType],["Complexity",focused.complexity],["Source",focused.source]].map(item=><div key={item[0]}><span className="text-[6px] text-[#82928c]">{item[0]}</span><b className="mt-1 block text-[7px] text-[#405b58]">{item[1]}</b></div>)}</div></div><div className="grid gap-3 sm:grid-cols-2">{(["AM","PM"] as const).map(period=><div key={period} className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">{period} steps</b><div className="mt-3 space-y-3">{focused.steps.filter(step=>step.period===period).map(step=><div key={period+step.order+step.sku} className="flex gap-3"><span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#edf3f4] text-[6px] font-bold text-[#3b646d]">{step.order}</span><div className="min-w-0"><b className="block text-[7px] text-[#52615a]">{step.product}</b><span className="mt-1 block text-[6px] leading-3.5 text-[#929d97]">{step.role} · {step.frequency} · {step.introduction}</span><span className={"mt-1 block text-[6px] font-bold "+(step.stock===0||step.state==="Conflict"?"text-rose-700":step.state==="Low stock"?"text-amber-700":"text-emerald-700")}>{step.state} · {step.stock} stock · ৳{step.price.toLocaleString()}</span></div></div>)}</div></div>)}</div>{focused.conflicts.length>0&&<div className="rounded-xl border border-rose-200 bg-rose-50/60 p-4"><b className="text-[8px] text-rose-800">Hard holds</b><div className="mt-3 space-y-2">{focused.conflicts.map(item=><div key={item} className="flex gap-2 text-[7px] leading-4 text-rose-800"><Icon name="alert" size={10} className="mt-0.5 shrink-0"/>{item}</div>)}</div></div>}<div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-800">Warnings and boundaries</b><div className="mt-3 space-y-2">{focused.warnings.map(item=><div key={item} className="flex gap-2 text-[7px] leading-4 text-amber-800"><Icon name="alert" size={10} className="mt-0.5 shrink-0"/>{item}</div>)}</div></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Human notes</b><div className="mt-3 space-y-2">{focused.notes.map(item=><div key={item} className="flex gap-2 text-[7px] leading-4 text-[#65736c]"><Icon name="check" size={10} className="mt-0.5 shrink-0 text-emerald-700"/>{item}</div>)}</div></div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><div className="flex items-center justify-between gap-3"><div><b className="text-[8px] text-[#405b58]">Cart readiness</b><p className="mt-1.5 text-[7px] leading-4 text-[#647b77]">{focused.cartState}. A cart draft uses current published price and remains editable by the customer.</p></div><b className="text-[10px] text-[#3b646d]">৳{focused.total.toLocaleString()}</b></div></div></div><footer className="sticky bottom-0 grid grid-cols-3 gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur"><button onClick={openReview} className="h-10 rounded-xl border border-[#dce4e0] text-[8px] font-bold text-[#596962]">Review version</button><button disabled={focused.status==="Blocked"||focused.conflicts.length>0||focused.consent!=="Active"} onClick={openCart} className="h-10 rounded-xl border border-[#bfd0cc] bg-[#edf3f4] text-[8px] font-bold text-[#3b646d] disabled:opacity-40">Create cart draft</button><button onClick={()=>onNavigate("Skin Profile / Beauty Passport")} className="h-10 rounded-xl bg-[#3b646d] text-[8px] font-bold text-white">Open passport</button></footer></aside></div>}
    {controlsOpen&&<RoutineBuilderControlsModal maxUniqueProducts={maxUniqueProducts} setMaxUniqueProducts={setMaxUniqueProducts} requireCompatibility={requireCompatibility} setRequireCompatibility={setRequireCompatibility} requireStock={requireStock} setRequireStock={setRequireStock} requirePrice={requirePrice} setRequirePrice={setRequirePrice} requireConsent={requireConsent} setRequireConsent={setRequireConsent} noAutoSubstitution={noAutoSubstitution} setNoAutoSubstitution={setNoAutoSubstitution} reason={controlReason} setReason={setControlReason} confirmed={controlConfirmed} setConfirmed={setControlConfirmed} onClose={()=>setControlsOpen(false)} onSave={()=>{setControlsOpen(false);showNotice("Routine-rule proposal saved for governed evaluation—live versions unchanged.")}}/>}
    {versionOpen&&<RoutineVersionModal customer={versionCustomer} setCustomer={setVersionCustomer} goal={versionGoal} setGoal={setVersionGoal} budget={versionBudget} setBudget={setVersionBudget} complexity={versionComplexity} setComplexity={setVersionComplexity} am={versionAm} setAm={setVersionAm} pm={versionPm} setPm={setVersionPm} intro={versionIntro} setIntro={setVersionIntro} source={versionSource} setSource={setVersionSource} consent={versionConsent} setConsent={setVersionConsent} confirmed={versionConfirmed} setConfirmed={setVersionConfirmed} onClose={()=>setVersionOpen(false)} onSave={()=>{setVersionOpen(false);showNotice("New routine version saved as an internal draft for compatibility and price review.")}}/>}
    {reviewOpen&&<RoutineReviewModal focused={focused} decision={reviewDecision} setDecision={setReviewDecision} owner={reviewOwner} setOwner={setReviewOwner} note={reviewNote} setNote={setReviewNote} compatibility={reviewCompatibility} setCompatibility={setReviewCompatibility} stock={reviewStock} setStock={setReviewStock} price={reviewPrice} setPrice={setReviewPrice} consent={reviewConsent} setConsent={setReviewConsent} confirmed={reviewConfirmed} setConfirmed={setReviewConfirmed} onClose={()=>setReviewOpen(false)} onSave={()=>{setReviewOpen(false);showNotice(`${reviewDecision} recorded for ${focused?.customer||"routine"}; nothing was shared or ordered.`)}}/>}
    {cartOpen&&focused&&<RoutineCartDraftModal focused={focused} expiry={cartExpiry} setExpiry={setCartExpiry} channel={cartChannel} setChannel={setCartChannel} price={cartPrice} setPrice={setCartPrice} stock={cartStock} setStock={setCartStock} editable={cartEditable} setEditable={setCartEditable} noDiscount={cartNoDiscount} setNoDiscount={setCartNoDiscount} consent={cartConsent} setConsent={setCartConsent} confirmed={cartConfirmed} setConfirmed={setCartConfirmed} onClose={()=>setCartOpen(false)} onSave={()=>{setCartOpen(false);showNotice(`Editable cart draft prepared for ${focused.customer}; no order or message was created.`)}}/>}
    {notice&&<div className="fixed bottom-5 right-5 z-[130] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

function RoutineBuilderControlsModal({maxUniqueProducts,setMaxUniqueProducts,requireCompatibility,setRequireCompatibility,requireStock,setRequireStock,requirePrice,setRequirePrice,requireConsent,setRequireConsent,noAutoSubstitution,setNoAutoSubstitution,reason,setReason,confirmed,setConfirmed,onClose,onSave}:{maxUniqueProducts:string;setMaxUniqueProducts:(value:string)=>void;requireCompatibility:boolean;setRequireCompatibility:(value:boolean)=>void;requireStock:boolean;setRequireStock:(value:boolean)=>void;requirePrice:boolean;setRequirePrice:(value:boolean)=>void;requireConsent:boolean;setRequireConsent:(value:boolean)=>void;noAutoSubstitution:boolean;setNoAutoSubstitution:(value:boolean)=>void;reason:string;setReason:(value:string)=>void;confirmed:boolean;setConfirmed:(value:boolean)=>void;onClose:()=>void;onSave:()=>void}) {
  return <div className="fixed inset-0 z-[110] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)onClose()}}><section className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.22)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Versioned operating rules</p><h2 className="mt-1 text-[18px] font-bold text-[#23322b]">Routine Builder controls</h2><p className="mt-1.5 text-[8px] leading-4 text-[#7b8781]">Propose routine and cart-readiness rules. Existing customer routines remain unchanged.</p></div><button onClick={onClose} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><label className="block max-w-xs text-[7px] font-bold text-[#65736c]">Maximum unique products per routine<input type="number" min="2" max="6" value={maxUniqueProducts} onChange={event=>setMaxUniqueProducts(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/><span className="mt-1.5 block font-normal leading-4 text-[#929d97]">Start with the smallest useful routine; expansion follows tolerance outcomes.</span></label><div className="grid gap-3 sm:grid-cols-2">{[["Compatibility review required",requireCompatibility,setRequireCompatibility,"Hard conflicts block approval and cart."],["Live stock check required",requireStock,setRequireStock,"Unavailable items cannot enter a cart draft."],["Published price check required",requirePrice,setRequirePrice,"No invented price or hidden discount."],["Active customer consent required",requireConsent,setRequireConsent,"Unknown or withdrawn consent blocks sharing."],["No automatic substitution",noAutoSubstitution,setNoAutoSubstitution,"Every swap needs human and customer review."]].map(([label,value,setter,detail])=><label key={label as string} className="flex items-start gap-3 rounded-xl border border-[#e2e8e5] p-4"><input type="checkbox" checked={value as boolean} onChange={event=>(setter as (value:boolean)=>void)(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span><b className="block text-[8px] text-[#405049]">{label as string}</b><span className="mt-1 block text-[7px] leading-4 text-[#87928d]">{detail as string}</span></span></label>)}</div><div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-900">Permanent boundaries</b><div className="mt-2 grid gap-2 sm:grid-cols-2">{["No diagnosis or treatment claim","No cart when safety hold exists","No auto-discount or offer invention","No auto-order or stock reservation","Customer can edit or abandon cart","Every routine and rule change is auditable"].map(item=><span key={item} className="flex gap-2 text-[7px] leading-4 text-amber-800"><Icon name="check" size={10} className="mt-0.5 shrink-0"/>{item}</span>)}</div></div><label className="block text-[7px] font-bold text-[#65736c]">Reason for control proposal<textarea value={reason} onChange={event=>setReason(event.target.value)} rows={3} placeholder="Explain the expected safety, clarity or commercial benefit..." className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><label className="flex items-start gap-3 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>I confirm this saves a proposal for authorized evaluation; it does not change a live routine, cart, price or order.</span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={onClose} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#65736c]">Cancel</button><button disabled={!reason.trim()||!confirmed||!requireCompatibility||!requireStock||!requirePrice||!requireConsent||!noAutoSubstitution||Number(maxUniqueProducts)<2||Number(maxUniqueProducts)>6} onClick={onSave} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Save proposal</button></footer></section></div>;
}

function RoutineVersionModal({customer,setCustomer,goal,setGoal,budget,setBudget,complexity,setComplexity,am,setAm,pm,setPm,intro,setIntro,source,setSource,consent,setConsent,confirmed,setConfirmed,onClose,onSave}:{customer:string;setCustomer:(value:string)=>void;goal:string;setGoal:(value:string)=>void;budget:string;setBudget:(value:string)=>void;complexity:string;setComplexity:(value:string)=>void;am:string;setAm:(value:string)=>void;pm:string;setPm:(value:string)=>void;intro:string;setIntro:(value:string)=>void;source:string;setSource:(value:string)=>void;consent:boolean;setConsent:(value:boolean)=>void;confirmed:boolean;setConfirmed:(value:boolean)=>void;onClose:()=>void;onSave:()=>void}) {
  return <div className="fixed inset-0 z-[120] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)onClose()}}><section className="max-h-[94vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.22)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Internal draft only</p><h2 className="mt-1 text-[18px] font-bold text-[#23322b]">Create new routine version</h2><p className="mt-1.5 text-[8px] leading-4 text-[#7b8781]">Start from a verified customer/passport, one primary goal and an explicit budget.</p></div><button onClick={onClose} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label className="text-[7px] font-bold text-[#65736c] lg:col-span-2">Customer / passport<input value={customer} onChange={event=>setCustomer(event.target.value)} placeholder="Customer ID, passport ID or verified phone" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><label className="text-[7px] font-bold text-[#65736c]">Budget (৳)<input type="number" min="500" value={budget} onChange={event=>setBudget(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><label className="text-[7px] font-bold text-[#65736c]">Complexity<select value={complexity} onChange={event=>setComplexity(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold"><option>Simple</option><option>Standard</option><option>Advanced</option></select></label></div><div className="grid gap-3 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Primary goal<input value={goal} onChange={event=>setGoal(event.target.value)} placeholder="One clear customer goal" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><label className="text-[7px] font-bold text-[#65736c]">Evidence source<select value={source} onChange={event=>setSource(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold"><option>Beauty Passport</option><option>AI Skin Test result</option><option>Customer-requested update</option><option>Human consultation review</option></select></label></div><div className="grid gap-3 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Proposed AM steps<textarea value={am} onChange={event=>setAm(event.target.value)} rows={3} placeholder="Product → frequency → purpose" className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label><label className="text-[7px] font-bold text-[#65736c]">Proposed PM steps<textarea value={pm} onChange={event=>setPm(event.target.value)} rows={3} placeholder="Product → frequency → purpose" className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label></div><label className="block text-[7px] font-bold text-[#65736c]">Introduction and tolerance plan<textarea value={intro} onChange={event=>setIntro(event.target.value)} rows={3} className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8px] text-[#405b58]">Next automated checks</b><p className="mt-1.5 text-[7px] leading-4 text-[#647b77]">After saving this draft, production must map exact SKUs, ingredients, published price and stock; run compatibility and budget checks; then route to human review.</p></div><label className="flex items-start gap-3 rounded-xl border border-[#e2e8e5] p-4 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={consent} onChange={event=>setConsent(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>Active consent and the customer’s current goal/budget were verified.</span></label><label className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-[7px] leading-4 text-amber-800"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>I confirm this is an internal draft only; it cannot be shared, converted to cart or treated as approved advice before review.</span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={onClose} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#65736c]">Cancel</button><button disabled={customer.trim().length<6||goal.trim().length<4||Number(budget)<500||!am.trim()||!pm.trim()||intro.trim().length<12||!consent||!confirmed} onClick={onSave} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Save version draft</button></footer></section></div>;
}

function RoutineReviewModal({focused,decision,setDecision,owner,setOwner,note,setNote,compatibility,setCompatibility,stock,setStock,price,setPrice,consent,setConsent,confirmed,setConfirmed,onClose,onSave}:{focused:RoutinePlan|null;decision:string;setDecision:(value:string)=>void;owner:string;setOwner:(value:string)=>void;note:string;setNote:(value:string)=>void;compatibility:boolean;setCompatibility:(value:boolean)=>void;stock:boolean;setStock:(value:boolean)=>void;price:boolean;setPrice:(value:boolean)=>void;consent:boolean;setConsent:(value:boolean)=>void;confirmed:boolean;setConfirmed:(value:boolean)=>void;onClose:()=>void;onSave:()=>void}) {
  return <div className="fixed inset-0 z-[120] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)onClose()}}><section className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.22)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Human routine decision</p><h2 className="mt-1 text-[18px] font-bold text-[#23322b]">Review routine version</h2><p className="mt-1.5 text-[8px] text-[#7b8781]">{focused?.customer||"Selected routine"} · {focused?.id} · {focused?.version}</p></div><button onClick={onClose} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5">{focused&&<div className="grid gap-3 sm:grid-cols-4">{[["Budget","৳"+focused.budget.toLocaleString()],["Total","৳"+focused.total.toLocaleString()],["Conflicts",String(focused.conflicts.length)],["Consent",focused.consent]].map(item=><div key={item[0]} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1 block text-[8px] text-[#405049]">{item[1]}</b></div>)}</div>}<div className="grid gap-3 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Decision<select value={decision} onChange={event=>setDecision(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold"><option>Approve routine version</option><option>Return for changes</option><option>Block routine</option><option>Archive draft</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Owner<select value={owner} onChange={event=>setOwner(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold"><option>Nusrat</option><option>Customer Care</option><option>Owner</option><option>Content</option></select></label></div><label className="block text-[7px] font-bold text-[#65736c]">Decision note<textarea value={note} onChange={event=>setNote(event.target.value)} rows={3} placeholder="Record evidence, changes, warnings and the next action..." className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><div className="grid gap-2 sm:grid-cols-2">{[["Compatibility checked",compatibility,setCompatibility],["Live stock checked",stock,setStock],["Published price checked",price,setPrice],["Consent and sharing purpose checked",consent,setConsent]].map(([label,value,setter])=><label key={label as string} className="flex items-start gap-3 rounded-xl border border-[#e2e8e5] p-3 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={value as boolean} onChange={event=>(setter as (value:boolean)=>void)(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>{label as string}</span></label>)}</div>{focused&&focused.conflicts.length>0&&<div className="rounded-xl border border-rose-200 bg-rose-50/60 p-4"><b className="text-[8px] text-rose-800">Unresolved hard holds</b><p className="mt-2 text-[7px] leading-4 text-rose-700">{focused.conflicts.join(" · ")}</p></div>}<label className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-[7px] leading-4 text-amber-800"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>I confirm this records a human decision only; approval does not send the routine, create a cart, reserve stock or place an order.</span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={onClose} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#65736c]">Cancel</button><button disabled={!focused||note.trim().length<8||!compatibility||!stock||!price||!consent||!confirmed||(decision==="Approve routine version"&&(focused.conflicts.length>0||focused.consent!=="Active"))} onClick={onSave} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Record review</button></footer></section></div>;
}

function RoutineCartDraftModal({focused,expiry,setExpiry,channel,setChannel,price,setPrice,stock,setStock,editable,setEditable,noDiscount,setNoDiscount,consent,setConsent,confirmed,setConfirmed,onClose,onSave}:{focused:RoutinePlan;expiry:string;setExpiry:(value:string)=>void;channel:string;setChannel:(value:string)=>void;price:boolean;setPrice:(value:boolean)=>void;stock:boolean;setStock:(value:boolean)=>void;editable:boolean;setEditable:(value:boolean)=>void;noDiscount:boolean;setNoDiscount:(value:boolean)=>void;consent:boolean;setConsent:(value:boolean)=>void;confirmed:boolean;setConfirmed:(value:boolean)=>void;onClose:()=>void;onSave:()=>void}) {
  const products=Array.from(new Map(focused.steps.map(step=>[step.sku,step])).values());
  return <div className="fixed inset-0 z-[120] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)onClose()}}><section className="max-h-[94vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.22)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Editable customer choice</p><h2 className="mt-1 text-[18px] font-bold text-[#23322b]">Create one-click routine cart draft</h2><p className="mt-1.5 text-[8px] text-[#7b8781]">{focused.customer} · {focused.id} · current total ৳{focused.total.toLocaleString()}</p></div><button onClick={onClose} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="divide-y divide-[#edf0ee] rounded-xl border border-[#e2e8e5]">{products.map(step=><div key={step.sku} className="grid grid-cols-[minmax(0,1fr)_70px_80px] items-center gap-3 p-3 text-[7px]"><div><b className="text-[8px] text-[#405049]">{step.product}</b><span className="mt-1 block font-mono text-[6px] text-[#929d97]">{step.sku}</span></div><span className={step.stock>0?"text-emerald-700":"text-rose-700"}>{step.stock} stock</span><b className="text-right text-[#405049]">৳{step.price.toLocaleString()}</b></div>)}</div><div className="grid gap-3 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Draft link expiry<select value={expiry} onChange={event=>setExpiry(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold"><option>24 hours</option><option>48 hours</option><option>7 days</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Delivery surface<select value={channel} onChange={event=>setChannel(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold"><option>Customer portal link</option><option>Copy link for Messenger</option><option>Copy link for WhatsApp</option><option>Email draft</option></select></label></div><div className="grid gap-2 sm:grid-cols-2">{[["Published price snapshot verified",price,setPrice],["Current stock verified",stock,setStock],["Customer may edit or remove items",editable,setEditable],["No unapproved discount added",noDiscount,setNoDiscount],["Consent permits this cart purpose",consent,setConsent]].map(([label,value,setter])=><label key={label as string} className="flex items-start gap-3 rounded-xl border border-[#e2e8e5] p-3 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={value as boolean} onChange={event=>(setter as (value:boolean)=>void)(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>{label as string}</span></label>)}</div><div className="rounded-xl border border-rose-200 bg-rose-50/60 p-4"><b className="text-[8px] text-rose-800">No order, reservation or automatic send</b><p className="mt-1.5 text-[7px] leading-4 text-rose-700">This prepares an internal cart-link draft only. Stock remains unreserved, the customer must choose to open it, and a human must approve any outbound message.</p></div><label className="flex items-start gap-3 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>I confirm this cannot place an order, reserve stock, create a discount or contact the customer automatically.</span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={onClose} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#65736c]">Cancel</button><button disabled={focused.status==="Blocked"||focused.conflicts.length>0||focused.consent!=="Active"||products.some(step=>step.stock<=0)||!price||!stock||!editable||!noDiscount||!consent||!confirmed} onClick={onSave} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Prepare cart draft</button></footer></section></div>;
}

