function CompatibilityOutcomeBadge({children}:{children:string}){
  const tone:Record<string,string>={Compatible:"bg-emerald-50 text-emerald-700 ring-emerald-200","Use with care":"bg-amber-50 text-amber-700 ring-amber-200","Separate schedule":"bg-violet-50 text-violet-700 ring-violet-200","Do not combine":"bg-rose-50 text-rose-700 ring-rose-200","Insufficient data":"bg-slate-100 text-slate-700 ring-slate-200",Draft:"bg-slate-100 text-slate-600 ring-slate-200","Review required":"bg-amber-50 text-amber-700 ring-amber-200",Approved:"bg-emerald-50 text-emerald-700 ring-emerald-200",Shared:"bg-sky-50 text-sky-700 ring-sky-200",Blocked:"bg-rose-50 text-rose-700 ring-rose-200"};
  return <span className={`inline-flex whitespace-nowrap rounded-full px-2.5 py-1 text-[7px] font-bold ring-1 ring-inset ${tone[children]||"bg-[#edf3f4] text-[#3b646d] ring-[#cbdcdf]"}`}>{children}</span>;
}

