  const [routine,setRoutine]=useState("RT-3042 · v3 · Approved");
  const [candidate,setCandidate]=useState("Salicylic Acid Serum");
  const [context,setContext]=useState("Add to current routine");
  const [lastChecked,setLastChecked]=useState("Rule snapshot · 22 Aug 2026 · 19:12");
  const [search,setSearch]=useState("");
