function SuppliersWorkspace({ onNavigate }: { onNavigate:(page:string)=>void }) {
  const [tab, setTab] = useState<"All"|"Active"|"Payable due"|"Review">("All");
  const [query, setQuery] = useState("");
  const [typeFilter, setTypeFilter] = useState("All types");
  const [selected, setSelected] = useState<SupplierRecord>(supplierRecords[0]);
  const [notice, setNotice] = useState("");
  const [addOpen, setAddOpen] = useState(false);
  const [noteOpen, setNoteOpen] = useState(false);
  const [payableOpen, setPayableOpen] = useState(false);
  const [supplierNote, setSupplierNote] = useState("");
  const [newSupplier, setNewSupplier] = useState({name:"",contact:"",phone:"",email:"",location:"",type:"Distributor",terms:"Cash"});
  const money = (value:number) => `৳${value.toLocaleString("en-BD")}`;
  const showNotice = (message:string) => {setNotice(message);window.setTimeout(()=>setNotice(""),2800)};
  const filtered = supplierRecords.filter(supplier=>(tab==="All"||tab==="Active"&&supplier.status==="Active"||tab==="Review"&&supplier.status==="Review"||tab==="Payable due"&&supplier.outstanding>0)&&(typeFilter==="All types"||supplier.type===typeFilter)&&`${supplier.name} ${supplier.contact} ${supplier.phone} ${supplier.brands.join(" ")}`.toLowerCase().includes(query.toLowerCase()));
  const tabs = [{name:"All" as const,count:24},{name:"Active" as const,count:19},{name:"Payable due" as const,count:7},{name:"Review" as const,count:3}];
  const kpis = [
    {label:"Total suppliers",value:"24",note:"19 currently active",icon:"inventory" as IconName,tone:"brand"},
    {label:"Open purchase orders",value:"8",note:"1,420 units incoming",icon:"orders" as IconName,tone:"brand"},
    {label:"Supplier payables",value:"৳2.84L",note:"7 balances due",icon:"finance" as IconName,tone:"warn"},
    {label:"On-time delivery",value:"92%",note:"Weighted 90-day rate",icon:"check" as IconName,tone:"good"},
  ];

  return <div className="space-y-5">
    <section className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><div className="flex items-center gap-2 text-[10.5px] font-bold uppercase tracking-[.16em] text-[#3b646d]"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/>Supplier operations</div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Suppliers</h1><p className="mt-1.5 max-w-2xl text-[12.5px] leading-5 text-[#66736d]">Keep supplier contacts, purchasing activity, payables and delivery reliability clear without turning this page into a full analytics dashboard.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>showNotice("Supplier export prepared with current filters.")} className="inline-flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[10.5px] font-bold text-[#53645d]"><Icon name="download" size={14}/>Export</button><button onClick={()=>onNavigate("Purchase Stock Entry")} className="inline-flex h-10 items-center gap-2 rounded-xl border border-[#d3dfdb] bg-white px-3.5 text-[10.5px] font-bold text-[#456965]"><Icon name="orders" size={14}/>New purchase</button><button onClick={()=>setAddOpen(true)} className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[10.5px] font-bold text-white"><Icon name="plus" size={14}/>Add supplier</button></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{kpis.map(item=><article key={item.label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4 shadow-[0_1px_2px_rgba(25,50,45,.03)]"><div className="flex items-start justify-between"><div><p className="text-[9.5px] font-bold uppercase tracking-[.08em] text-[#74817b]">{item.label}</p><p className="mt-2 text-[23px] font-bold tracking-[-.035em] text-[#17231f]">{item.value}</p></div><span className={`flex h-8 w-8 items-center justify-center rounded-xl ${item.tone==="good"?"bg-emerald-50 text-emerald-700":item.tone==="warn"?"bg-amber-50 text-amber-700":"bg-[#edf3f4] text-[#3b646d]"}`}><Icon name={item.icon} size={15}/></span></div><p className="mt-3 border-t border-[#eff2f0] pt-2.5 text-[9.5px] font-semibold text-[#77847e]">{item.note}</p></article>)}</section>

    <section className="overflow-hidden rounded-2xl border border-[#e1e7e4] bg-white shadow-[0_1px_2px_rgba(25,50,45,.03)]"><div className="flex overflow-x-auto border-b border-[#e8ecea] bg-[#fafbfa] px-2 sm:px-4">{tabs.map(item=><button key={item.name} onClick={()=>setTab(item.name)} className={`relative min-w-fit px-4 py-4 text-[10.5px] font-bold transition ${tab===item.name?"text-[#315a5f]":"text-[#76827c]"}`}>{item.name}<span className={`ml-2 rounded-full px-2 py-0.5 text-[8.5px] ${tab===item.name?"bg-[#dfeaec] text-[#315a5f]":"bg-[#edf0ee] text-[#7b8781]"}`}>{item.count}</span>{tab===item.name&&<span className="absolute inset-x-3 bottom-0 h-0.5 rounded-full bg-[#3b646d]"/>}</button>)}</div><div className="flex flex-col gap-3 border-b border-[#edf0ee] p-4 lg:flex-row lg:items-center"><div className="flex h-10 min-w-0 flex-1 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3 lg:max-w-[380px]"><Icon name="search" size={15} className="text-[#8b9691]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search supplier, contact, phone or brand" className="min-w-0 flex-1 bg-transparent text-[10.5px] outline-none placeholder:text-[#9da6a2]"/></div><div className="flex flex-wrap gap-2 lg:ml-auto"><select value={typeFilter} onChange={event=>setTypeFilter(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[10px] font-semibold text-[#5d6b65] outline-none"><option>All types</option><option>Authorized distributor</option><option>Importer</option><option>Distributor</option><option>Local wholesaler</option><option>Packaging supplier</option></select><button onClick={()=>{setTab("All");setQuery("");setTypeFilter("All types")}} className="inline-flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3 text-[10px] font-bold text-[#5d6b65]"><Icon name="refresh" size={13}/>Reset</button></div></div>

      <div className="grid xl:grid-cols-[minmax(0,1fr)_330px]"><div className="min-w-0 overflow-x-auto"><table className="w-full min-w-[1120px] text-left"><thead className="bg-[#fafbfa] text-[8.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Supplier</th><th className="px-3 py-3.5">Supply scope</th><th className="px-3 py-3.5">Open PO</th><th className="px-3 py-3.5">90D purchases</th><th className="px-3 py-3.5">Payable</th><th className="px-3 py-3.5">Lead time</th><th className="px-3 py-3.5">On-time</th><th className="px-3 py-3.5">Status</th><th className="px-5 py-3.5 text-right">Action</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{filtered.map(supplier=><tr key={supplier.id} onClick={()=>setSelected(supplier)} className={`cursor-pointer text-[10px] text-[#5a6861] transition hover:bg-[#f9fbfa] ${selected.id===supplier.id?"bg-[#f7faf9]":""}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-[#e7efed] text-[9px] font-black text-[#3b646d]">{supplier.name.split(" ").map(part=>part[0]).slice(0,2).join("")}</span><span><b className="block text-[10.5px] text-[#293730]">{supplier.name}</b><span className="mt-0.5 block text-[8.5px] text-[#8e9994]">{supplier.contact} · {supplier.location}</span></span></div></td><td className="max-w-[200px] px-3 py-4"><b className="block truncate text-[#4a5952]">{supplier.supplies}</b><span className="mt-1 block truncate text-[8.5px] text-[#929d97]">{supplier.brands.join(" · ")}</span></td><td className="px-3 py-4"><b className="block text-[11px] text-[#35443d]">{supplier.openPO}</b><span className="mt-1 block text-[8.5px] text-[#929d97]">{supplier.incomingUnits} units</span></td><td className="px-3 py-4 font-bold text-[#405048]">{money(supplier.purchases90d)}</td><td className="px-3 py-4"><b className={supplier.outstanding>0?"text-amber-700":"text-emerald-700"}>{money(supplier.outstanding)}</b><span className="mt-1 block text-[8.5px] text-[#929d97]">{supplier.terms}</span></td><td className="px-3 py-4 font-semibold text-[#4d5c55]">{supplier.leadTime} days</td><td className="px-3 py-4"><b className={supplier.onTime<85?"text-amber-700":"text-[#405048]"}>{supplier.onTime}%</b></td><td className="px-3 py-4"><Status>{supplier.status}</Status></td><td className="px-5 py-4 text-right"><button onClick={event=>{event.stopPropagation();setSelected(supplier)}} className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-[#dfe5e2] bg-white text-[#64736c]"><Icon name="chevron" size={12}/></button></td></tr>)}</tbody></table>{filtered.length===0&&<div className="flex min-h-[260px] flex-col items-center justify-center text-center"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#edf3f4] text-[#3b646d]"><Icon name="search" size={18}/></span><b className="mt-3 text-[11px] text-[#35443d]">No suppliers match these filters</b><span className="mt-1 text-[9px] text-[#8d9893]">Try another search or reset the current view.</span></div>}</div>

        <aside className="border-t border-[#e8ecea] bg-[#fbfcfb] p-5 xl:border-l xl:border-t-0"><div className="flex items-start justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-[#84908a]">Supplier snapshot</p><h3 className="mt-1.5 text-[15px] font-bold leading-5 text-[#26352f]">{selected.name}</h3><span className="mt-1 block text-[8.5px] text-[#84908a]">{selected.id} · {selected.type}</span></div><Status>{selected.status}</Status></div><div className="mt-4 flex flex-wrap gap-1.5">{selected.brands.map(brand=><span key={brand} className="rounded-full bg-white px-2.5 py-1 text-[8px] font-bold text-[#61716a] ring-1 ring-[#e1e7e4]">{brand}</span>)}</div><div className="mt-5 grid grid-cols-3 divide-x divide-[#e1e7e4] rounded-xl border border-[#e1e7e4] bg-white py-4 text-center"><div><b className="block text-[12px] text-[#304038]">{selected.openPO}</b><span className="mt-1 block text-[7.5px] text-[#919b96]">Open PO</span></div><div><b className="block text-[12px] text-[#304038]">{selected.onTime}%</b><span className="mt-1 block text-[7.5px] text-[#919b96]">On-time</span></div><div><b className="block text-[12px] text-[#304038]">{selected.quality}%</b><span className="mt-1 block text-[7.5px] text-[#919b96]">Quality</span></div></div><dl className="mt-4 space-y-3 text-[9px]"><div className="flex items-center justify-between gap-4"><dt className="text-[#87928d]">Contact</dt><dd className="text-right font-bold text-[#4b5a53]">{selected.contact}</dd></div><div className="flex items-center justify-between gap-4"><dt className="text-[#87928d]">Phone</dt><dd className="text-right font-bold text-[#4b5a53]">{selected.phone}</dd></div><div className="flex items-center justify-between gap-4"><dt className="text-[#87928d]">Last purchase</dt><dd className="text-right font-bold text-[#4b5a53]">{selected.lastPurchase}</dd></div><div className="flex items-center justify-between gap-4"><dt className="text-[#87928d]">Payment terms</dt><dd className="text-right font-bold text-[#4b5a53]">{selected.terms}</dd></div><div className="flex items-center justify-between gap-4"><dt className="text-[#87928d]">Outstanding</dt><dd className={`text-right font-bold ${selected.outstanding>0?"text-amber-700":"text-emerald-700"}`}>{money(selected.outstanding)}</dd></div></dl><div className="mt-5 grid grid-cols-2 gap-2"><button onClick={()=>showNotice(`Call action opened for ${selected.phone}.`)} className="inline-flex h-9 items-center justify-center gap-2 rounded-xl border border-[#d8e1de] bg-white text-[9px] font-bold text-[#52665f]"><Icon name="phone" size={12}/>Call</button><button onClick={()=>showNotice(`Email draft opened for ${selected.email}; nothing was sent.`)} className="inline-flex h-9 items-center justify-center gap-2 rounded-xl border border-[#d8e1de] bg-white text-[9px] font-bold text-[#52665f]"><Icon name="message" size={12}/>Email</button></div><button onClick={()=>onNavigate("Purchase Stock Entry")} className="mt-2 flex h-10 w-full items-center justify-center gap-2 rounded-xl bg-[#3b646d] text-[10px] font-bold text-white">Create purchase entry<Icon name="arrow" size={13}/></button>{selected.outstanding>0&&<button onClick={()=>setPayableOpen(true)} className="mt-2 flex h-9 w-full items-center justify-center gap-2 rounded-xl border border-amber-200 bg-amber-50 text-[9px] font-bold text-amber-800"><Icon name="finance" size={12}/>Review payable</button>}<button onClick={()=>setNoteOpen(true)} className="mt-2 flex h-9 w-full items-center justify-center gap-2 rounded-xl text-[9px] font-bold text-[#58716b]"><Icon name="edit" size={12}/>Add internal note</button><div className="mt-4 rounded-xl bg-[#edf3f4] p-4"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#607872]">Operational note</p><p className="mt-1.5 text-[8.5px] leading-4 text-[#647872]">{selected.notes}</p></div></aside>
      </div>
    </section>

    <section className="grid gap-4 lg:grid-cols-3">{[["Purchase concentration","Top supplier · 30%","K-Beauty Distribution BD","Watch over-dependence"],["Payables control","৳2.84L outstanding","7 supplier balances","Finance owns settlement"],["Functionality boundary","Supplier records exist","Performance is derived","Forecasting needs backend"]].map(([title,value,note,meta],index)=><article key={title} className={`rounded-2xl border p-5 ${index===2?"border-[#d2dfdb] bg-[#edf3f4]":"border-[#e2e8e5] bg-white"}`}><div className="flex items-center justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[.13em] text-[#84908a]">{index===0?"Supply risk":index===1?"Financial control":"Data boundary"}</p><h3 className="mt-1 text-[13px] font-bold text-[#2b3933]">{title}</h3></div><Icon name={index===1?"finance":index===2?"alert":"reports"} size={16} className="text-[#3b646d]"/></div><b className="mt-4 block text-[13px] text-[#3f4f47]">{value}</b><p className="mt-1.5 text-[9px] font-semibold text-[#68756f]">{note}</p><p className="mt-3 border-t border-[#e1e7e4] pt-3 text-[8.5px] text-[#89948f]">{meta}</p></article>)}</section>

    {addOpen&&<div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#17231f]/40 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setAddOpen(false)}}><div className="w-full max-w-[660px] overflow-hidden rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-[#3b646d]">Supplier master</p><h2 className="mt-1.5 text-[19px] font-bold text-[#23322b]">Add supplier</h2><p className="mt-1 text-[10px] text-[#84908a]">Create the supplier record first; purchases remain a separate workflow.</p></div><button onClick={()=>setAddOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={15}/></button></div><div className="grid gap-4 p-5 sm:grid-cols-2">{[["Supplier name","name"],["Contact person","contact"],["Mobile number","phone"],["Email address","email"],["Location","location"]].map(([label,key])=><label key={key} className="text-[8.5px] font-bold uppercase tracking-[.1em] text-[#77847e]">{label}<input autoFocus={key==="name"} value={newSupplier[key as keyof typeof newSupplier]} onChange={event=>setNewSupplier(current=>({...current,[key]:event.target.value}))} className="mt-2 h-11 w-full rounded-xl border border-[#dce4e0] px-3 text-[10px] font-semibold normal-case tracking-normal text-[#4d5d55] outline-none"/></label>)}<label className="text-[8.5px] font-bold uppercase tracking-[.1em] text-[#77847e]">Supplier type<select value={newSupplier.type} onChange={event=>setNewSupplier(current=>({...current,type:event.target.value}))} className="mt-2 h-11 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[10px] font-semibold normal-case tracking-normal text-[#4d5d55] outline-none"><option>Distributor</option><option>Authorized distributor</option><option>Importer</option><option>Local wholesaler</option><option>Packaging supplier</option></select></label><label className="text-[8.5px] font-bold uppercase tracking-[.1em] text-[#77847e]">Payment terms<select value={newSupplier.terms} onChange={event=>setNewSupplier(current=>({...current,terms:event.target.value}))} className="mt-2 h-11 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[10px] font-semibold normal-case tracking-normal text-[#4d5d55] outline-none"><option>Cash</option><option>Advance</option><option>7 days</option><option>15 days</option><option>30 days</option></select></label></div><div className="mx-5 mb-5 flex gap-3 rounded-xl bg-[#edf3f4] p-4 text-[8.5px] leading-4 text-[#5b7069]"><Icon name="check" size={14} className="mt-0.5 shrink-0"/>Bank details and opening balances should be added only through authorized finance controls.</div><div className="flex flex-col gap-2 border-t border-[#e8ecea] bg-[#fafbfa] p-5 sm:flex-row sm:justify-end"><button onClick={()=>setAddOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-4 text-[10px] font-bold text-[#66756e]">Cancel</button><button onClick={()=>{if(!newSupplier.name.trim()||!newSupplier.contact.trim()||!newSupplier.phone.trim()){showNotice("Supplier name, contact and mobile number are required.");return}const normalized=newSupplier.phone.replace(/\s/g,"");if(supplierRecords.some(supplier=>supplier.phone.replace(/\s/g,"")===normalized)){showNotice("A supplier with this mobile number already exists.");return}setAddOpen(false);setNewSupplier({name:"",contact:"",phone:"",email:"",location:"",type:"Distributor",terms:"Cash"});showNotice("Supplier record validated; connect save to the existing supplier API.")}} className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[10px] font-bold text-white"><Icon name="plus" size={14}/>Save supplier</button></div></div></div>}

    {noteOpen&&<div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#17231f]/40 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setNoteOpen(false)}}><div className="w-full max-w-[500px] overflow-hidden rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-[#3b646d]">Internal supplier note</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Note for {selected.name}</h2></div><button onClick={()=>setNoteOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={15}/></button></div><div className="p-5"><textarea autoFocus value={supplierNote} onChange={event=>setSupplierNote(event.target.value)} placeholder="Add purchase, quality or communication context..." className="min-h-28 w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[10px] font-medium text-[#4d5d55] outline-none"/><div className="mt-3 flex gap-3 rounded-xl bg-[#edf3f4] p-4 text-[8.5px] leading-4 text-[#5b7069]"><Icon name="settings" size={14} className="mt-0.5 shrink-0"/>Use notes for operational context. Payment adjustments must stay inside Finance Reconciliation.</div></div><div className="flex flex-col gap-2 border-t border-[#e8ecea] bg-[#fafbfa] p-5 sm:flex-row sm:justify-end"><button onClick={()=>setNoteOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-4 text-[10px] font-bold text-[#66756e]">Cancel</button><button onClick={()=>{if(!supplierNote.trim()){showNotice("Write a note before saving.");return}setNoteOpen(false);setSupplierNote("");showNotice(`Internal note added to ${selected.name}.`)}} className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[10px] font-bold text-white"><Icon name="check" size={14}/>Save note</button></div></div></div>}

    {payableOpen&&<div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#17231f]/40 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setPayableOpen(false)}}><div className="w-full max-w-[580px] overflow-hidden rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-[#3b646d]">Read-only balance review</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Payable to {selected.name}</h2><p className="mt-1 text-[10px] text-[#84908a]">Review supplier context before opening the finance workflow.</p></div><button onClick={()=>setPayableOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={15}/></button></div><div className="space-y-4 p-5"><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Outstanding",money(selected.outstanding)],["Terms",selected.terms],["Open PO",String(selected.openPO)],["Last purchase",selected.lastPurchase]].map(([label,value])=><div key={label} className="rounded-xl border border-[#e2e8e5] bg-[#fafbfa] p-3"><span className="block text-[8px] font-bold uppercase tracking-[.09em] text-[#909b95]">{label}</span><b className={`mt-1.5 block text-[10px] ${label==="Outstanding"?"text-amber-700":"text-[#3f4f47]"}`}>{value}</b></div>)}</div><div className="divide-y divide-[#edf0ee] rounded-xl border border-[#e2e8e5]">{[["Purchase invoices",money(selected.purchases90d),"90-day recorded purchases"],["Posted supplier payments",money(Math.max(0,selected.purchases90d-selected.outstanding)),"Existing finance entries"],["Current payable",money(selected.outstanding),"Requires finance reconciliation"]].map(([label,value,note])=><div key={label} className="flex items-center gap-4 p-4"><div className="min-w-0 flex-1"><b className="block text-[9.5px] text-[#44534c]">{label}</b><span className="mt-1 block text-[8px] text-[#929d97]">{note}</span></div><b className="text-[10px] text-[#35443d]">{value}</b></div>)}</div><div className="flex gap-3 rounded-xl border border-amber-100 bg-amber-50/65 p-4 text-[8.5px] leading-4 text-amber-800"><Icon name="alert" size={14} className="mt-0.5 shrink-0"/>No payment can be posted from this supplier page. Authorized users must record and reconcile settlement in Finance.</div></div><div className="flex flex-col gap-2 border-t border-[#e8ecea] bg-[#fafbfa] p-5 sm:flex-row sm:justify-end"><button onClick={()=>setPayableOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-4 text-[10px] font-bold text-[#66756e]">Close</button><button onClick={()=>{setPayableOpen(false);onNavigate("Finance Reconciliation")}} className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[10px] font-bold text-white"><Icon name="finance" size={14}/>Open finance reconciliation</button></div></div></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[90] flex max-w-sm items-start gap-3 rounded-xl bg-[#223c3f] px-4 py-3 text-[10.5px] font-semibold leading-5 text-white shadow-[0_20px_55px_rgba(24,45,39,.24)]"><span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-white/15"><Icon name="check" size={11}/></span>{notice}</div>}
  </div>;
}

function LegacySupplierAnalyticsWorkspace({ onNavigate }: { onNavigate:(page:string)=>void }) {
  const [timeframe, setTimeframe] = useState<"90D"|"6M"|"12M">("6M");
  const [metric, setMetric] = useState<"Spend"|"Units">("Spend");
  const [notice, setNotice] = useState("");
  const [methodologyOpen, setMethodologyOpen] = useState(false);
  const [reportOpen, setReportOpen] = useState(false);
  const [reportFormat, setReportFormat] = useState("PDF summary");
  const [detailOpen, setDetailOpen] = useState(false);
  const [selectedSupplier, setSelectedSupplier] = useState<SupplierRecord>(supplierRecords[0]);
  const money = (value:number) => `৳${value.toLocaleString("en-BD")}`;
  const showNotice = (message:string) => {setNotice(message);window.setTimeout(()=>setNotice(""),2800)};
  const charts = {
    "90D":{labels:["Jun","Jul","Aug"],spend:[215,238,246],units:[910,1040,1120]},
    "6M":{labels:["Mar","Apr","May","Jun","Jul","Aug"],spend:[134,182,166,215,238,246],units:[610,790,720,910,1040,1120]},
    "12M":{labels:["Sep","Oct","Nov","Dec","Jan","Feb","Mar","Apr","May","Jun","Jul","Aug"],spend:[108,122,140,176,128,151,134,182,166,215,238,246],units:[510,560,640,830,590,680,610,790,720,910,1040,1120]},
  };
  const series = metric==="Spend"?charts[timeframe].spend:charts[timeframe].units;
  const maxSeries = Math.max(...series);
  const totalSpend = supplierRecords.reduce((sum,supplier)=>sum+supplier.purchases90d,0);
  const performance = supplierRecords.map(supplier=>({
    ...supplier,
    score:Math.round(supplier.onTime*.45+supplier.quality*.4+Math.max(0,100-supplier.leadTime*3)*.15),
    share:Math.round((supplier.purchases90d/totalSpend)*100),
  })).sort((a,b)=>b.score-a.score);
  const selectedPerformance = performance.find(supplier=>supplier.id===selectedSupplier.id) || performance[0];
  const kpis = [
    {label:"Purchase spend",value:"৳13.8L",note:"+8.6% vs previous period",icon:"finance" as IconName,tone:"brand"},
    {label:"On-time delivery",value:"92%",note:"+3.2 pts improvement",icon:"check" as IconName,tone:"good"},
    {label:"Average lead time",value:"7.2 days",note:"0.8 day faster",icon:"history" as IconName,tone:"good"},
    {label:"Top supplier exposure",value:"30%",note:"Concentration watch",icon:"alert" as IconName,tone:"warn"},
  ];

  return <div className="space-y-5">
    <section className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><div className="flex items-center gap-2 text-[10.5px] font-bold uppercase tracking-[.16em] text-[#3b646d]"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/>Supplier intelligence</div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Supplier Analytics</h1><p className="mt-1.5 max-w-2xl text-[12.5px] leading-5 text-[#66736d]">Compare supplier cost, reliability and exposure so purchasing decisions are based on evidence—not assumptions.</p></div><div className="flex flex-wrap gap-2"><div className="flex rounded-xl border border-[#dce4e0] bg-white p-1">{(["90D","6M","12M"] as const).map(item=><button key={item} onClick={()=>setTimeframe(item)} className={`h-8 rounded-lg px-3 text-[9px] font-bold ${timeframe===item?"bg-[#edf3f4] text-[#3b646d]":"text-[#7b8781]"}`}>{item}</button>)}</div><button onClick={()=>onNavigate("Suppliers")} className="inline-flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[10px] font-bold text-[#53645d]"><Icon name="inventory" size={14}/>Supplier list</button><button onClick={()=>setReportOpen(true)} className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[10px] font-bold text-white"><Icon name="download" size={14}/>Export report</button></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{kpis.map(item=><article key={item.label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4 shadow-[0_1px_2px_rgba(25,50,45,.03)]"><div className="flex items-start justify-between"><div><p className="text-[9.5px] font-bold uppercase tracking-[.08em] text-[#74817b]">{item.label}</p><p className="mt-2 text-[22px] font-bold tracking-[-.035em] text-[#17231f]">{item.value}</p></div><span className={`flex h-8 w-8 items-center justify-center rounded-xl ${item.tone==="good"?"bg-emerald-50 text-emerald-700":item.tone==="warn"?"bg-amber-50 text-amber-700":"bg-[#edf3f4] text-[#3b646d]"}`}><Icon name={item.icon} size={15}/></span></div><p className="mt-3 border-t border-[#eff2f0] pt-2.5 text-[9.5px] font-semibold text-[#77847e]">{item.note}</p></article>)}</section>

    <section className="grid gap-5 xl:grid-cols-[minmax(0,1.45fr)_minmax(320px,.55fr)]"><article className="rounded-2xl border border-[#e1e7e4] bg-white p-5 shadow-[0_1px_2px_rgba(25,50,45,.03)] sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[.14em] text-[#84908a]">Purchase trend · {timeframe}</p><h2 className="mt-1 text-[15px] font-bold text-[#2b3933]">Spend and received units</h2><p className="mt-1 text-[9px] text-[#8b9691]">Use purchase records to see whether stock investment is rising efficiently.</p></div><div className="flex w-fit rounded-lg bg-[#f1f4f2] p-1">{(["Spend","Units"] as const).map(item=><button key={item} onClick={()=>setMetric(item)} className={`rounded-md px-3 py-1.5 text-[8.5px] font-bold ${metric===item?"bg-white text-[#3b646d] shadow-sm":"text-[#7f8b85]"}`}>{item}</button>)}</div></div><div className="mt-6 flex h-[230px] items-end gap-2 border-b border-[#dfe5e2] px-1 sm:gap-3">{series.map((value,index)=><div key={`${charts[timeframe].labels[index]}-${metric}`} className="group flex h-full min-w-0 flex-1 flex-col items-center justify-end"><span className="mb-2 text-[7.5px] font-bold text-[#84908a] opacity-0 transition group-hover:opacity-100">{metric==="Spend"?`৳${value}k`:value}</span><div className="w-full max-w-12 rounded-t-lg bg-[#6f9294] transition-all hover:bg-[#3b646d]" style={{height:`${Math.max(10,(value/maxSeries)*82)}%`}}/><span className="mt-2 -mb-5 text-[7.5px] font-semibold text-[#8b9691]">{charts[timeframe].labels[index]}</span></div>)}</div><div className="mt-8 grid gap-3 sm:grid-cols-3">{[["Current run-rate","৳2.46L / month","+3.4%"],["Units received","1,120 / month","+7.7%"],["Cost per unit","৳220","-4.0%"]].map(([label,value,delta])=><div key={label} className="rounded-xl bg-[#fafbfa] p-3 ring-1 ring-[#e8ecea]"><span className="text-[8px] font-semibold text-[#8b9691]">{label}</span><div className="mt-1 flex items-end justify-between gap-2"><b className="text-[10.5px] text-[#3f4f47]">{value}</b><span className={`text-[8px] font-bold ${delta.startsWith("-")?"text-emerald-700":"text-[#3b646d]"}`}>{delta}</span></div></div>)}</div></article>

      <article className="overflow-hidden rounded-2xl border border-[#e1e7e4] bg-white shadow-[0_1px_2px_rgba(25,50,45,.03)]"><div className="border-b border-[#edf0ee] p-5"><p className="text-[9px] font-bold uppercase tracking-[.14em] text-[#84908a]">Decision queue</p><h2 className="mt-1 text-[15px] font-bold text-[#2b3933]">Needs attention</h2></div><div className="divide-y divide-[#edf0ee]">{[["alert","Dermaluxe lead time increased","11 days · 2 late POs","High"],["reports","Top supplier holds 30% of spend","Diversification review","Medium"],["inventory","3 products may breach lead time","Reorder dependency","High"],["finance","৳2.84L supplier payable","7 supplier balances","Medium"]].map(([icon,title,note,level])=><button key={title} onClick={()=>showNotice(`${title} insight opened.`)} className="flex w-full items-center gap-3 p-4 text-left hover:bg-[#f9fbfa]"><span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-xl ${level==="High"?"bg-rose-50 text-rose-700":"bg-amber-50 text-amber-700"}`}><Icon name={icon as IconName} size={14}/></span><span className="min-w-0 flex-1"><b className="block truncate text-[9.5px] text-[#3d4c45]">{title}</b><span className="mt-1 block text-[8px] text-[#929d97]">{note}</span></span><Icon name="chevron" size={12} className="text-[#a1aaa6]"/></button>)}</div><div className="bg-[#fafbfa] p-4"><button onClick={()=>setMethodologyOpen(true)} className="flex w-full items-center justify-center gap-2 text-[9px] font-bold text-[#58716b]"><Icon name="reports" size={12}/>How scores are calculated</button></div></article></section>

    <section className="grid gap-5 xl:grid-cols-[minmax(0,1.35fr)_minmax(320px,.65fr)]"><article className="overflow-hidden rounded-2xl border border-[#e1e7e4] bg-white shadow-[0_1px_2px_rgba(25,50,45,.03)]"><div className="flex flex-col gap-3 border-b border-[#edf0ee] p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[.14em] text-[#84908a]">Comparative performance</p><h2 className="mt-1 text-[15px] font-bold text-[#2b3933]">Supplier scorecard</h2></div><span className="text-[8.5px] font-semibold text-[#8b9691]">Delivery 45% · Quality 40% · Lead time 15%</span></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead className="bg-[#fafbfa] text-[8.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Rank / supplier</th><th className="px-3 py-3.5">Score</th><th className="px-3 py-3.5">Spend share</th><th className="px-3 py-3.5">On-time</th><th className="px-3 py-3.5">Quality</th><th className="px-3 py-3.5">Lead time</th><th className="px-5 py-3.5">Signal</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{performance.map((supplier,index)=><tr key={supplier.id} onClick={()=>{setSelectedSupplier(supplier);setDetailOpen(true)}} className="cursor-pointer text-[9.5px] text-[#5a6861] hover:bg-[#f9fbfa]"><td className="px-5 py-4"><div className="flex items-center gap-3"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[#edf3f4] text-[8.5px] font-black text-[#3b646d]">{index+1}</span><span><b className="block text-[10px] text-[#35443d]">{supplier.name}</b><span className="mt-0.5 block text-[8px] text-[#929d97]">{supplier.type}</span></span></div></td><td className="px-3 py-4"><b className="text-[11px] text-[#35443d]">{supplier.score}</b><span className="text-[8px] text-[#929d97]"> /100</span></td><td className="px-3 py-4"><div className="w-24"><div className="flex justify-between text-[8px]"><span>{supplier.share}%</span><span>{money(supplier.purchases90d)}</span></div><div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[#e7ece9]"><span className="block h-full rounded-full bg-[#6f9294]" style={{width:`${Math.min(100,supplier.share*3)}%`}}/></div></div></td><td className="px-3 py-4 font-bold text-[#405048]">{supplier.onTime}%</td><td className="px-3 py-4 font-bold text-[#405048]">{supplier.quality}%</td><td className="px-3 py-4">{supplier.leadTime} days</td><td className="px-5 py-4"><span className={`inline-flex rounded-full px-2.5 py-1 text-[8px] font-bold ring-1 ring-inset ${supplier.score>=90?"bg-emerald-50 text-emerald-700 ring-emerald-200":supplier.score>=82?"bg-amber-50 text-amber-700 ring-amber-200":"bg-rose-50 text-rose-700 ring-rose-200"}`}>{supplier.score>=90?"Strong":supplier.score>=82?"Watch":"Review"}</span></td></tr>)}</tbody></table></div></article>

      <article className="rounded-2xl border border-[#e1e7e4] bg-white p-5 shadow-[0_1px_2px_rgba(25,50,45,.03)]"><p className="text-[9px] font-bold uppercase tracking-[.14em] text-[#84908a]">Supply concentration</p><h2 className="mt-1 text-[15px] font-bold text-[#2b3933]">Purchase exposure</h2><div className="mt-5 flex items-center gap-5"><div className="relative h-28 w-28 shrink-0 rounded-full" style={{background:"conic-gradient(#3b646d 0 30%,#76979a 30% 53%,#a8bdbc 53% 71%,#d5dfdb 71% 100%)"}}><span className="absolute inset-[18px] flex flex-col items-center justify-center rounded-full bg-white"><b className="text-[16px] text-[#31433b]">30%</b><span className="text-[7.5px] text-[#8a9590]">Top share</span></span></div><div className="min-w-0 flex-1 space-y-3">{[["K-Beauty Distribution","30%","#3b646d"],["Careline Imports","23%","#76979a"],["Dermaluxe Trading","18%","#a8bdbc"],["Others","29%","#d5dfdb"]].map(([name,value,color])=><div key={name} className="flex items-center gap-2 text-[8.5px]"><span className="h-2 w-2 rounded-full" style={{backgroundColor:color}}/><span className="min-w-0 flex-1 truncate text-[#65736c]">{name}</span><b className="text-[#3f4f47]">{value}</b></div>)}</div></div><div className="mt-5 rounded-xl border border-amber-100 bg-amber-50/65 p-4"><div className="flex gap-3"><Icon name="alert" size={14} className="mt-0.5 shrink-0 text-amber-700"/><div><b className="text-[9.5px] text-amber-800">Concentration is manageable</b><p className="mt-1 text-[8px] leading-4 text-amber-700">Create an alternate-source plan before any supplier exceeds 40% of spend.</p></div></div></div></article></section>

    <section className="grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(320px,.75fr)]"><article className="overflow-hidden rounded-2xl border border-[#e1e7e4] bg-white"><div className="border-b border-[#edf0ee] p-5"><p className="text-[9px] font-bold uppercase tracking-[.14em] text-[#84908a]">Procurement dependency</p><h2 className="mt-1 text-[15px] font-bold text-[#2b3933]">Reorder readiness</h2><p className="mt-1 text-[8.5px] text-[#8b9691]">Operational suggestions only—approval remains with the purchasing user.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="bg-[#fafbfa] text-[8.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3">Product</th><th className="px-3 py-3">Supplier</th><th className="px-3 py-3">Stock cover</th><th className="px-3 py-3">Lead time</th><th className="px-5 py-3">Signal</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{[["Niacinamide Serum","K-Beauty Distribution BD","6 days","5 days","Reorder soon"],["Acne Control Facewash","Dermaluxe Trading","9 days","11 days","At risk"],["Kojic Facewash","Careline Imports","14 days","8 days","Plan"],["Packaging boxes","PackCraft Bangladesh","18 days","9 days","Monitor"]].map(([product,supplier,cover,lead,signal])=><tr key={product} className="text-[9.5px] text-[#596861]"><td className="px-5 py-4 font-bold text-[#3f4f47]">{product}</td><td className="px-3 py-4">{supplier}</td><td className="px-3 py-4 font-semibold">{cover}</td><td className="px-3 py-4">{lead}</td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-[8px] font-bold ${signal==="At risk"?"bg-rose-50 text-rose-700":signal==="Reorder soon"?"bg-amber-50 text-amber-700":"bg-[#edf3f4] text-[#3b646d]"}`}>{signal}</span></td></tr>)}</tbody></table></div></article><article className="rounded-2xl border border-[#d4e0dc] bg-[#edf3f4] p-5"><div className="flex items-start justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[.14em] text-[#607872]">Functionality boundary</p><h2 className="mt-1 text-[15px] font-bold text-[#345557]">What is calculated</h2></div><Icon name="alert" size={16} className="text-[#3b646d]"/></div><div className="mt-4 space-y-3">{[["Existing","Purchases, receipts, supplier records"],["Derived","Spend share, lead time, scorecard"],["Backend required","Forecasting and automated reorder"],["Approval required","Purchase creation and payment"]].map(([label,value])=><div key={label} className="rounded-xl bg-white/70 p-3 ring-1 ring-[#d8e3df]"><b className="block text-[8.5px] text-[#476965]">{label}</b><span className="mt-1 block text-[8px] leading-4 text-[#6b7d76]">{value}</span></div>)}</div><button onClick={()=>setMethodologyOpen(true)} className="mt-4 inline-flex h-9 items-center gap-2 rounded-xl bg-white px-3 text-[9px] font-bold text-[#456965] ring-1 ring-[#d1ddda]"><Icon name="reports" size={12}/>View methodology</button></article></section>

    {methodologyOpen&&<div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#17231f]/40 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setMethodologyOpen(false)}}><div className="w-full max-w-[680px] overflow-hidden rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-[#3b646d]">Transparent methodology</p><h2 className="mt-1.5 text-[19px] font-bold text-[#23322b]">How supplier intelligence is calculated</h2><p className="mt-1 text-[10px] text-[#84908a]">Every signal should be explainable from existing business records.</p></div><button onClick={()=>setMethodologyOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={15}/></button></div><div className="grid gap-3 p-5 sm:grid-cols-2">{[["Delivery reliability · 45%","Promised receipt date compared with actual stock receipt date.","orders" as IconName],["Quality acceptance · 40%","Accepted units compared with received units and logged quality issues.","check" as IconName],["Lead-time efficiency · 15%","Days between confirmed purchase and completed goods receipt.","history" as IconName],["Spend concentration","Supplier purchase value divided by total purchase value for the selected period.","reports" as IconName],["Reorder readiness","Stock-cover days compared with supplier lead time and a safety buffer.","inventory" as IconName],["Payable exposure","Recorded supplier invoices minus authorized posted payments.","finance" as IconName]].map(([title,detail,icon])=><article key={title as string} className="rounded-xl border border-[#e2e8e5] p-4"><span className="flex h-8 w-8 items-center justify-center rounded-xl bg-[#edf3f4] text-[#3b646d]"><Icon name={icon as IconName} size={14}/></span><b className="mt-3 block text-[9.5px] text-[#3f4f47]">{title}</b><p className="mt-1.5 text-[8.5px] leading-4 text-[#7d8983]">{detail}</p></article>)}</div><div className="mx-5 mb-5 flex gap-3 rounded-xl border border-amber-100 bg-amber-50/65 p-4 text-[8.5px] leading-4 text-amber-800"><Icon name="alert" size={14} className="mt-0.5 shrink-0"/>Scores support human decisions. They never block a supplier, create a purchase order or post a payment automatically.</div><div className="border-t border-[#e8ecea] bg-[#fafbfa] p-5 text-right"><button onClick={()=>setMethodologyOpen(false)} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[10px] font-bold text-white">Understood</button></div></div></div>}

    {detailOpen&&<div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#17231f]/40 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setDetailOpen(false)}}><div className="w-full max-w-[620px] overflow-hidden rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-[#3b646d]">Supplier performance drill-down</p><h2 className="mt-1.5 text-[19px] font-bold text-[#23322b]">{selectedPerformance.name}</h2><p className="mt-1 text-[10px] text-[#84908a]">{selectedPerformance.type} · {selectedPerformance.supplies}</p></div><button onClick={()=>setDetailOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={15}/></button></div><div className="space-y-4 p-5"><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Score",`${selectedPerformance.score}/100`],["Spend share",`${selectedPerformance.share}%`],["On-time",`${selectedPerformance.onTime}%`],["Lead time",`${selectedPerformance.leadTime} days`]].map(([label,value])=><div key={label} className="rounded-xl border border-[#e2e8e5] bg-[#fafbfa] p-3"><span className="block text-[8px] font-bold uppercase tracking-[.09em] text-[#909b95]">{label}</span><b className="mt-1.5 block text-[11px] text-[#3f4f47]">{value}</b></div>)}</div><div className="grid gap-3 sm:grid-cols-2"><article className="rounded-xl border border-[#e2e8e5] p-4"><p className="text-[8.5px] font-bold uppercase tracking-[.11em] text-[#84908a]">Commercial position</p><dl className="mt-3 space-y-3 text-[9px]"><div className="flex justify-between"><dt className="text-[#87928d]">90D purchases</dt><dd className="font-bold text-[#46564e]">{money(selectedPerformance.purchases90d)}</dd></div><div className="flex justify-between"><dt className="text-[#87928d]">Outstanding</dt><dd className={selectedPerformance.outstanding>0?"font-bold text-amber-700":"font-bold text-emerald-700"}>{money(selectedPerformance.outstanding)}</dd></div><div className="flex justify-between"><dt className="text-[#87928d]">Open PO</dt><dd className="font-bold text-[#46564e]">{selectedPerformance.openPO}</dd></div><div className="flex justify-between"><dt className="text-[#87928d]">Terms</dt><dd className="font-bold text-[#46564e]">{selectedPerformance.terms}</dd></div></dl></article><article className="rounded-xl border border-[#e2e8e5] p-4"><p className="text-[8.5px] font-bold uppercase tracking-[.11em] text-[#84908a]">Decision signals</p><div className="mt-3 space-y-2">{[[selectedPerformance.onTime>=90,"Delivery reliability",`${selectedPerformance.onTime}% on-time`],[selectedPerformance.quality>=95,"Quality acceptance",`${selectedPerformance.quality}% accepted`],[selectedPerformance.share<=30,"Concentration",`${selectedPerformance.share}% spend share`]].map(([good,label,value])=><div key={label as string} className="flex items-center gap-3 rounded-lg bg-[#fafbfa] p-2.5"><span className={`flex h-6 w-6 items-center justify-center rounded-full ${good?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700"}`}><Icon name={good?"check":"alert"} size={11}/></span><span className="flex-1 text-[8.5px] font-semibold text-[#5d6b65]">{label}</span><b className="text-[8.5px] text-[#405048]">{value}</b></div>)}</div></article></div><div className="flex gap-3 rounded-xl bg-[#edf3f4] p-4 text-[8.5px] leading-4 text-[#5b7069]"><Icon name="reports" size={14} className="mt-0.5 shrink-0"/>This drill-down summarizes recorded performance. Supplier status changes still require manual review in the Suppliers module.</div></div><div className="flex flex-col gap-2 border-t border-[#e8ecea] bg-[#fafbfa] p-5 sm:flex-row sm:justify-end"><button onClick={()=>setDetailOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-4 text-[10px] font-bold text-[#66756e]">Close</button><button onClick={()=>{setDetailOpen(false);onNavigate("Suppliers")}} className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[10px] font-bold text-white"><Icon name="inventory" size={14}/>Open supplier list</button></div></div></div>}

    {reportOpen&&<div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#17231f]/40 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setReportOpen(false)}}><div className="w-full max-w-[520px] overflow-hidden rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[9px] font-bold uppercase tracking-[.15em] text-[#3b646d]">Supplier analytics export</p><h2 className="mt-1.5 text-[19px] font-bold text-[#23322b]">Prepare {timeframe} report</h2><p className="mt-1 text-[10px] text-[#84908a]">Export the current analytical view without changing supplier records.</p></div><button onClick={()=>setReportOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={15}/></button></div><div className="space-y-4 p-5"><label className="block text-[8.5px] font-bold uppercase tracking-[.1em] text-[#77847e]">Report format<select value={reportFormat} onChange={event=>setReportFormat(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[10px] font-semibold normal-case tracking-normal text-[#4d5d55] outline-none"><option>PDF summary</option><option>CSV scorecard</option><option>Excel analysis</option></select></label><div><p className="text-[8.5px] font-bold uppercase tracking-[.1em] text-[#77847e]">Included sections</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{["KPI summary","Purchase trend","Supplier scorecard","Concentration","Decision queue","Reorder readiness"].map(item=><label key={item} className="flex items-center gap-2 rounded-xl border border-[#e2e8e5] p-3 text-[9px] font-semibold text-[#5e6d66]"><input type="checkbox" defaultChecked className="accent-[#3b646d]"/>{item}</label>)}</div></div><div className="flex gap-3 rounded-xl bg-[#edf3f4] p-4 text-[8.5px] leading-4 text-[#5b7069]"><Icon name="download" size={14} className="mt-0.5 shrink-0"/>Report values remain representative until the existing purchasing and stock-receipt data sources are connected.</div></div><div className="flex flex-col gap-2 border-t border-[#e8ecea] bg-[#fafbfa] p-5 sm:flex-row sm:justify-end"><button onClick={()=>setReportOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-4 text-[10px] font-bold text-[#66756e]">Cancel</button><button onClick={()=>{setReportOpen(false);showNotice(`${reportFormat} prepared for the ${timeframe} supplier view.`)}} className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[10px] font-bold text-white"><Icon name="download" size={14}/>Prepare export</button></div></div></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[90] flex max-w-sm items-start gap-3 rounded-xl bg-[#223c3f] px-4 py-3 text-[10.5px] font-semibold leading-5 text-white shadow-[0_20px_55px_rgba(24,45,39,.24)]"><span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-white/15"><Icon name="check" size={11}/></span>{notice}</div>}
  </div>;
}

type FinanceSettlement = {
  id:string; partner:string; period:string; orders:number; gross:number; courierFee:number; adjustments:number; expected:number; received:number; variance:number; status:"Matched"|"Mismatch"|"Pending"; reference:string;
};

