type BrandView="All brands"|"Live"|"Featured"|"Verification review"|"Needs content";

function BrandsWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [brands,setBrands]=useState(initialBrands);
  const [view,setView]=useState<BrandView>("All brands");
  const [query,setQuery]=useState("");
  const [status,setStatus]=useState("All statuses");
  const [country,setCountry]=useState("All countries");
  const [verification,setVerification]=useState("All verification");
  const [sort,setSort]=useState("Display order");
  const [selectedIds,setSelectedIds]=useState<string[]>([]);
  const [focused,setFocused]=useState<BrandRecord|null>(null);
  const [editorOpen,setEditorOpen]=useState(false);
  const [editorMode,setEditorMode]=useState<"Create"|"Edit">("Create");
  const [draft,setDraft]=useState<BrandRecord>(initialBrands[0]);
  const [impactOpen,setImpactOpen]=useState(false);
  const [pendingAction,setPendingAction]=useState<"Publish"|"Hide"|"Archive"|"Merge">("Publish");
  const [actionIds,setActionIds]=useState<string[]>([]);
  const [actionReason,setActionReason]=useState("");
  const [actionConfirmed,setActionConfirmed]=useState(false);
  const [destinationId,setDestinationId]=useState("");
  const [redirectPath,setRedirectPath]=useState("");
  const [notice,setNotice]=useState("");

  const views:BrandView[]=["All brands","Live","Featured","Verification review","Needs content"];
  const showNotice=(message:string)=>{
    if(message==="Brand editor opens from the final safe control layer."&&focused){setEditorMode("Edit");setDraft(focused);setRedirectPath("");setEditorOpen(true);setFocused(null);return}
    setNotice(message);setTimeout(()=>setNotice(""),2600);
  };
  const contentScore=(brand:BrandRecord)=>Math.round(([brand.tagline,brand.description,brand.website,brand.logo,brand.hero,brand.seoTitle,brand.seoDescription].filter(Boolean).length/7)*100);
  const statusTone=(value:BrandStatus)=>value==="Live"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Draft"?"bg-slate-100 text-slate-600 ring-slate-200":value==="Hidden"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-rose-50 text-rose-700 ring-rose-200";
  const verificationTone=(value:BrandVerification)=>value==="Source verified"?"bg-emerald-50 text-emerald-700":value==="Documents pending"?"bg-amber-50 text-amber-700":"bg-rose-50 text-rose-700";
  const openEditor=(mode:"Create"|"Edit",brand?:BrandRecord)=>{
    setEditorMode(mode);setDraft(brand||{id:"BR-NEW",name:"",slug:"",country:"South Korea",products:0,liveProducts:0,activeSuppliers:0,verification:"Not verified",documentRef:"",status:"Draft",featured:false,order:brands.filter(item=>item.status!=="Archived").length+1,tagline:"",description:"",website:"",logo:"",hero:"",seoTitle:"",seoDescription:"",sourceNote:"",updated:"Not saved"});setRedirectPath("");setEditorOpen(true);setFocused(null);
  };
  const openImpact=(action:"Publish"|"Hide"|"Archive"|"Merge",ids=selectedIds)=>{setPendingAction(action);setActionIds(ids);setActionReason("");setActionConfirmed(false);setDestinationId("");setImpactOpen(true);setFocused(null)};
  const viewCounts:Record<BrandView,number>={"All brands":brands.filter(item=>item.status!=="Archived").length,"Live":brands.filter(item=>item.status==="Live").length,"Featured":brands.filter(item=>item.featured&&item.status!=="Archived").length,"Verification review":brands.filter(item=>item.verification!=="Source verified"&&item.status!=="Archived").length,"Needs content":brands.filter(item=>contentScore(item)<85&&item.status!=="Archived").length};
  const countries=["All countries",...Array.from(new Set(brands.map(item=>item.country)))];
  let filtered=brands.filter(brand=>{
    const matchesQuery=(brand.name+" "+brand.slug+" "+brand.country+" "+brand.documentRef).toLowerCase().includes(query.toLowerCase());
    const matchesStatus=status==="All statuses"||brand.status===status;
    const matchesCountry=country==="All countries"||brand.country===country;
    const matchesVerification=verification==="All verification"||brand.verification===verification;
    const matchesView=view==="All brands"||(view==="Live"&&brand.status==="Live")||(view==="Featured"&&brand.featured)||(view==="Verification review"&&brand.verification!=="Source verified")||(view==="Needs content"&&contentScore(brand)<85);
    return matchesQuery&&matchesStatus&&matchesCountry&&matchesVerification&&matchesView;
  });
  filtered=[...filtered].sort((a,b)=>sort==="Name A–Z"?a.name.localeCompare(b.name):sort==="Most products"?b.products-a.products:sort==="Content health"?contentScore(a)-contentScore(b):sort==="Supplier dependency"?a.activeSuppliers-b.activeSuppliers:a.order-b.order);
  const allVisibleSelected=filtered.length>0&&filtered.every(item=>selectedIds.includes(item.id));
  const moveBrand=(id:string,direction:-1|1)=>{setBrands(current=>{const active=current.filter(item=>item.status!=="Archived").sort((a,b)=>a.order-b.order);const index=active.findIndex(item=>item.id===id);const swap=active[index+direction];const target=active[index];if(!target||!swap)return current;return current.map(item=>item.id===target.id?{...item,order:swap.order,updated:"Just now"}:item.id===swap.id?{...item,order:target.order,updated:"Just now"}:item)});showNotice("Brand display order updated in this concept.")};
  const originalBrand=brands.find(item=>item.id===draft.id);
  const slugChanged=editorMode==="Edit"&&Boolean(originalBrand)&&originalBrand?.slug!==draft.slug;
  const slugUnique=!brands.some(item=>item.id!==draft.id&&item.slug===draft.slug);
  const verificationReady=draft.verification!=="Source verified"||Boolean(draft.documentRef.trim()&&draft.sourceNote.trim());
  const editorValid=Boolean(draft.name.trim()&&draft.slug.trim()&&draft.country.trim()&&slugUnique&&verificationReady&&(!slugChanged||redirectPath.trim()));
  const saveBrandDraft=()=>{
    if(!editorValid){showNotice("Complete identity, unique slug, required evidence and redirect details.");return}
    const normalized:BrandRecord={...draft,status:editorMode==="Create"?"Draft":draft.status,updated:"Draft changes"};
    setBrands(current=>editorMode==="Create"?[...current,{...normalized,id:"BR-"+String(current.length+1).padStart(3,"0")}]:current.map(item=>item.id===draft.id?normalized:item));
    setEditorOpen(false);setRedirectPath("");showNotice(editorMode==="Create"?"Brand draft created. Add products and evidence before publishing.":"Brand draft saved with evidence and redirect metadata.");
  };
  const impactTargets=brands.filter(item=>actionIds.includes(item.id));
  const publishBlockers=pendingAction==="Publish"?impactTargets.filter(item=>item.products===0||contentScore(item)<85||item.verification!=="Source verified"||item.activeSuppliers===0):[];
  const destinationRequired=(pendingAction==="Archive"||pendingAction==="Merge")&&impactTargets.some(item=>item.products>0||item.status==="Live");
  const validDestination=Boolean(destinationId&&!actionIds.includes(destinationId)&&brands.some(item=>item.id===destinationId&&item.status!=="Archived"));
  const impactBlocked=publishBlockers.length>0||(destinationRequired&&!validDestination);
  const applyBrandImpact=()=>{
    if(impactBlocked||!actionConfirmed||(pendingAction!=="Publish"&&!actionReason.trim()))return;
    const movedProducts=impactTargets.reduce((sum,item)=>sum+item.products,0);
    const movedLive=impactTargets.reduce((sum,item)=>sum+item.liveProducts,0);
    const nextStatus:BrandStatus=pendingAction==="Publish"?"Live":pendingAction==="Hide"?"Hidden":"Archived";
    setBrands(current=>current.map(item=>destinationRequired&&item.id===destinationId?{...item,products:item.products+movedProducts,liveProducts:item.liveProducts+movedLive,updated:"Just now"}:actionIds.includes(item.id)?{...item,status:nextStatus,featured:pendingAction==="Publish"?item.featured:false,products:destinationRequired?0:item.products,liveProducts:destinationRequired?0:item.liveProducts,updated:"Just now"}:item));
    setSelectedIds([]);setImpactOpen(false);setActionIds([]);setActionReason("");setActionConfirmed(false);setDestinationId("");showNotice(pendingAction==="Merge"?"Duplicate brand records merged into the canonical destination.":actionIds.length+" brand"+(actionIds.length===1?"":"s")+" moved to "+nextStatus.toLowerCase()+".");
  };

  return <div className="space-y-5">
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Catalog identity</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Brands</h1><p className="mt-1.5 max-w-2xl text-[12.5px] leading-5 text-[#66736d]">Manage brand pages, product coverage and supply-source evidence without overstating official authorization.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>showNotice("Brand export prepared with source and content filters.")} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="download" size={13}/>Export</button><button onClick={()=>openEditor("Create")} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="plus" size={13}/>Add brand</button></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Live brands",String(viewCounts.Live),"Customer-visible","store"],["Mapped products",String(brands.reduce((sum,item)=>sum+item.products,0)),"Single brand per product","products"],["Source verified",String(brands.filter(item=>item.verification==="Source verified").length),"Evidence reviewed","check"],["Needs review",String(viewCounts["Verification review"]),"Source evidence","alert"]].map(([label,value,note,icon],index)=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-start justify-between"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#edf3f4] text-[#3b646d]"><Icon name={icon as IconName} size={15}/></span><span className={"rounded-full px-2 py-1 text-[7px] font-bold "+(index<3?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700")}>{index<3?"Healthy":"Review"}</span></div><b className="mt-4 block text-[22px] tracking-[-.03em] text-[#23322b]">{value}</b><span className="mt-1 block text-[9px] font-bold text-[#65736c]">{label}</span><small className="mt-1 block text-[7.5px] text-[#929d97]">{note}</small></article>)}</section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Supply-source coverage</p><b className="mt-1 block text-[12px] text-[#33423b]">7 of 10 brands verified</b></div><span className="text-[16px] font-bold text-[#3b646d]">70%</span></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[#edf1ef]"><div className="h-full w-[70%] rounded-full bg-[#5f8585]"/></div><p className="mt-3 text-[7.5px] leading-4 text-[#87928d]">Evidence confirms procurement traceability—not official brand authorization.</p></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Supplier dependency</p><b className="mt-1 block text-[12px] text-[#33423b]">5 brands have one source</b></div><span className="rounded-full bg-amber-50 px-2 py-1 text-[7px] font-bold text-amber-700">Watch</span></div><p className="mt-3 text-[7.5px] leading-4 text-[#87928d]">Purchasing and supplier analytics own commercial risk details.</p><button onClick={()=>onNavigate("Supplier Analytics")} className="mt-3 text-[7.5px] font-bold text-[#3b646d]">Open supplier analytics →</button></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><div className="flex items-center justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5d7775]">Catalog rule</p><b className="mt-1 block text-[12px] text-[#304d4d]">One canonical brand record</b></div><Icon name="check" size={15} className="text-[#3b646d]"/></div><p className="mt-3 text-[7.5px] leading-4 text-[#647b77]">Duplicate spellings are merged so product filters, SEO and reports remain reliable.</p></article></section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{views.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold transition "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d] hover:text-[#53645d]")}>{item}<span className={"ml-2 rounded-full px-1.5 py-0.5 text-[7px] "+(view===item?"bg-[#edf3f4]":"bg-[#f2f4f3]")}>{viewCounts[item]}</span></button>)}</div></div><div className="space-y-3 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:p-5"><div className="flex flex-col gap-2 xl:flex-row"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search brand, slug, country or source reference..." className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><select value={status} onChange={event=>setStatus(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All statuses</option><option>Live</option><option>Draft</option><option>Hidden</option><option>Archived</option></select><select value={country} onChange={event=>setCountry(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none">{countries.map(item=><option key={item}>{item}</option>)}</select><select value={verification} onChange={event=>setVerification(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All verification</option><option>Source verified</option><option>Documents pending</option><option>Not verified</option></select><select value={sort} onChange={event=>setSort(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>Display order</option><option>Name A–Z</option><option>Most products</option><option>Content health</option><option>Supplier dependency</option></select></div></div>

      {selectedIds.length>0&&<div className="flex flex-col gap-3 border-b border-[#d8e4e0] bg-[#edf3f4] px-4 py-3 sm:flex-row sm:items-center sm:px-5"><div className="flex min-w-0 flex-1 items-center gap-2"><span className="flex h-7 min-w-7 items-center justify-center rounded-lg bg-[#3b646d] px-2 text-[8px] font-bold text-white">{selectedIds.length}</span><b className="text-[8.5px] text-[#405b58]">brands selected</b></div><div className="flex flex-wrap gap-2"><button onClick={()=>openImpact("Publish")} className="h-8 rounded-lg border border-[#c7d8d3] bg-white px-3 text-[8px] font-bold text-[#416764]">Publish</button><button onClick={()=>openImpact("Hide")} className="h-8 rounded-lg border border-amber-200 bg-white px-3 text-[8px] font-bold text-amber-700">Hide</button><button onClick={()=>openImpact("Merge")} className="h-8 rounded-lg border border-violet-200 bg-white px-3 text-[8px] font-bold text-violet-700">Merge</button><button onClick={()=>openImpact("Archive")} className="h-8 rounded-lg border border-rose-200 bg-white px-3 text-[8px] font-bold text-rose-700">Archive</button><button onClick={()=>setSelectedIds([])} className="flex h-8 w-8 items-center justify-center rounded-lg text-[#708079]"><Icon name="close" size={12}/></button></div></div>}

      <div className="overflow-x-auto"><table className="w-full min-w-[1180px] text-left"><thead className="bg-[#fafbfa] text-[7px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="w-12 px-5 py-3.5"><input type="checkbox" aria-label="Select all visible brands" checked={allVisibleSelected} onChange={event=>setSelectedIds(current=>event.target.checked?Array.from(new Set([...current,...filtered.map(item=>item.id)])):current.filter(id=>!filtered.some(item=>item.id===id)))} className="h-3.5 w-3.5 accent-[#3b646d]"/></th><th className="px-2 py-3.5">Brand</th><th className="px-4 py-3.5">Origin</th><th className="px-4 py-3.5">Product coverage</th><th className="px-4 py-3.5">Supply source</th><th className="px-4 py-3.5">Storefront</th><th className="px-4 py-3.5">Content health</th><th className="px-4 py-3.5">Order</th><th className="px-4 py-3.5">Updated</th><th className="w-12 px-4 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{filtered.map(brand=><tr key={brand.id} className="text-[8.5px] text-[#5f6e67] hover:bg-[#fafcfb]"><td className="px-5 py-4"><input type="checkbox" aria-label={"Select "+brand.name} checked={selectedIds.includes(brand.id)} onChange={event=>setSelectedIds(current=>event.target.checked?[...current,brand.id]:current.filter(id=>id!==brand.id))} className="h-3.5 w-3.5 accent-[#3b646d]"/></td><td className="px-2 py-4"><button onClick={()=>setFocused(brand)} className="flex min-w-[230px] items-center gap-3 text-left"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-[#dce4e0] bg-white text-[8px] font-black text-[#3b646d]">{brand.name.slice(0,3).toUpperCase()}</span><span><b className="block max-w-[200px] truncate text-[9px] text-[#33423b]">{brand.name}</b><small className="mt-1 block font-mono text-[6.5px] text-[#929d97]">/{brand.slug}</small></span></button></td><td className="px-4 py-4"><b className="block text-[8px] text-[#53625c]">{brand.country}</b><span className="mt-1 block text-[7px] text-[#929d97]">{brand.website?"Official site linked":"Website missing"}</span></td><td className="px-4 py-4"><b className={"block text-[9px] "+(brand.products===0?"text-amber-700":"text-[#405049]")}>{brand.products} products</b><span className="mt-1 block text-[7px] text-[#929d97]">{brand.liveProducts} live · {brand.activeSuppliers} source{brand.activeSuppliers===1?"":"s"}</span></td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[7px] font-bold "+verificationTone(brand.verification)}>{brand.verification}</span><span className="mt-1.5 block max-w-[155px] truncate font-mono text-[6px] text-[#929d97]">{brand.documentRef||"No evidence reference"}</span></td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[7px] font-bold ring-1 ring-inset "+statusTone(brand.status)}>{brand.status}</span>{brand.featured&&<span className="ml-1 rounded bg-[#edf3f4] px-1.5 py-0.5 text-[6px] font-bold text-[#3b646d]">Featured</span>}</td><td className="px-4 py-4"><div className="flex items-center gap-2"><div className="h-1.5 w-14 overflow-hidden rounded-full bg-[#e8ecea]"><div style={{width:contentScore(brand)+"%"}} className={"h-full rounded-full "+(contentScore(brand)>=85?"bg-emerald-500":contentScore(brand)>=60?"bg-amber-500":"bg-rose-500")}/></div><b className="text-[7.5px] text-[#596861]">{contentScore(brand)}%</b></div><span className="mt-1.5 block text-[6.5px] text-[#929d97]">{brand.logo&&brand.hero?"Brand assets ready":"Media incomplete"}</span></td><td className="px-4 py-4"><div className="flex items-center gap-1"><button aria-label={"Move "+brand.name+" up"} onClick={()=>moveBrand(brand.id,-1)} className="flex h-7 w-7 items-center justify-center rounded-lg border border-[#e1e7e4] text-[9px] text-[#718079]">↑</button><b className="w-5 text-center text-[8px] text-[#405049]">{brand.order}</b><button aria-label={"Move "+brand.name+" down"} onClick={()=>moveBrand(brand.id,1)} className="flex h-7 w-7 items-center justify-center rounded-lg border border-[#e1e7e4] text-[9px] text-[#718079]">↓</button></div></td><td className="px-4 py-4"><span className="text-[7px] text-[#718079]">{brand.updated}</span></td><td className="px-4 py-4"><button aria-label={"Open "+brand.name} onClick={()=>setFocused(brand)} className="flex h-8 w-8 items-center justify-center rounded-lg text-[#8a9590] hover:bg-[#edf3f4] hover:text-[#3b646d]"><Icon name="more" size={13}/></button></td></tr>)}</tbody></table></div>
      {filtered.length===0&&<div className="flex flex-col items-center px-5 py-14 text-center"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#edf3f4] text-[#3b646d]"><Icon name="search" size={18}/></span><b className="mt-4 text-[11px] text-[#405049]">No matching brands</b><p className="mt-1 text-[8px] text-[#929d97]">Try another name, country, verification or status.</p><button onClick={()=>{setQuery("");setStatus("All statuses");setCountry("All countries");setVerification("All verification");setView("All brands")}} className="mt-4 h-9 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#3b646d]">Clear filters</button></div>}<div className="flex flex-col gap-2 border-t border-[#e8ecea] bg-[#fafbfa] px-5 py-3 text-[7.5px] text-[#87928d] sm:flex-row sm:items-center sm:justify-between"><span>Showing {filtered.length} of {brands.length} representative brand records</span><span>Featured order is finalized in Homepage CMS; supplier terms stay in Suppliers.</span></div>
    </section>

    <section className="flex gap-3 rounded-2xl border border-[#d8e4e1] bg-[#edf3f4] p-4 text-[8px] leading-4 text-[#526965]"><Icon name="check" size={13} className="mt-0.5 shrink-0"/><p><b>Trust wording:</b> “Source verified” means BrandnBeauty reviewed procurement evidence. It must never be presented as “officially authorized” unless a valid brand authorization agreement exists.</p></section>

    {focused&&<div className="fixed inset-0 z-[70] bg-[#17231f]/30 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-[460px] overflow-y-auto bg-white shadow-[-25px_0_70px_rgba(17,35,30,.18)]"><div className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Brand inspector</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">{focused.name}</h2><p className="mt-1 font-mono text-[7.5px] text-[#929d97]">/{focused.slug} · {focused.id}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></div><div className="space-y-4 p-5"><div className="flex items-center gap-4 rounded-xl border border-[#e2e8e5] bg-[#fafbfa] p-4"><span className="flex h-14 w-14 items-center justify-center rounded-xl border border-[#dce4e0] bg-white text-[10px] font-black text-[#3b646d]">{focused.name.slice(0,3).toUpperCase()}</span><div><span className={"inline-flex rounded-full px-2 py-1 text-[7px] font-bold ring-1 ring-inset "+statusTone(focused.status)}>{focused.status}</span><b className="mt-2 block text-[9px] text-[#405049]">{focused.country} · order {focused.order}</b></div></div><div className="grid grid-cols-2 gap-2">{[["Products",String(focused.products)],["Live products",String(focused.liveProducts)],["Active sources",String(focused.activeSuppliers)],["Content health",contentScore(focused)+"%"]].map(([label,value])=><div key={label} className="rounded-xl border border-[#e2e8e5] p-4"><span className="text-[7px] font-bold uppercase text-[#929d97]">{label}</span><b className="mt-2 block text-[9px] text-[#405049]">{value}</b></div>)}</div><div className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between gap-3"><b className="text-[8.5px] text-[#405049]">Supply-source evidence</b><span className={"rounded-full px-2 py-1 text-[7px] font-bold "+verificationTone(focused.verification)}>{focused.verification}</span></div><p className="mt-3 font-mono text-[7px] text-[#718079]">{focused.documentRef||"No evidence reference"}</p><p className="mt-2 text-[7.5px] leading-4 text-[#718079]">{focused.sourceNote}</p></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8.5px] text-[#405049]">Storefront story</b><p className="mt-2 text-[7.5px] leading-4 text-[#718079]">{focused.description||"Brand description has not been added."}</p></div><button onClick={()=>showNotice("Brand editor opens from the final safe control layer.")} className="flex h-10 w-full items-center justify-center gap-2 rounded-xl bg-[#3b646d] text-[8.5px] font-bold text-white"><Icon name="edit" size={12}/>Edit brand</button><div className="grid grid-cols-2 gap-2"><button onClick={()=>onNavigate("Products")} className="flex h-10 items-center justify-center gap-2 rounded-xl border border-[#dce4e0] text-[8px] font-bold text-[#58675f]"><Icon name="products" size={12}/>View products</button><button onClick={()=>showNotice("Brand storefront preview prepared for integration.")} className="flex h-10 items-center justify-center gap-2 rounded-xl border border-[#dce4e0] text-[8px] font-bold text-[#58675f]"><Icon name="eye" size={12}/>Preview</button></div><div className="flex gap-3 rounded-xl bg-[#edf3f4] p-4 text-[7.5px] leading-4 text-[#526965]"><Icon name="history" size={12} className="mt-0.5 shrink-0"/><p>Production will preserve brand versions, evidence updates, product reassignment and publishing actor.</p></div></div></aside></div>}

    {editorOpen&&<div className="fixed inset-0 z-[80] flex items-center justify-center bg-[#17231f]/35 p-3 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setEditorOpen(false)}}><section className="max-h-[94vh] w-full max-w-4xl overflow-y-auto rounded-2xl bg-white shadow-[0_30px_90px_rgba(17,35,30,.25)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Brand details</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">{editorMode==="Create"?"Create brand draft":"Edit "+draft.name}</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Identity, evidence and storefront content remain draft until separate approval.</p></div><button onClick={()=>setEditorOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="grid gap-5 p-5 lg:grid-cols-[minmax(0,1fr)_270px]"><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><label className="space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Brand name</span><input value={draft.name} onChange={event=>{const name=event.target.value;setDraft(current=>({...current,name,slug:editorMode==="Create"&&(!current.slug||current.slug===current.name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,""))?name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,""):current.slug}))}} placeholder="e.g. Round Lab" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] font-medium outline-none focus:border-[#9eb7b4]"/></label><label className="space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">URL slug</span><div className="flex h-10 items-center rounded-xl border border-[#dce4e0] px-3 focus-within:border-[#9eb7b4]"><span className="text-[8px] text-[#9aa49f]">/</span><input value={draft.slug} onChange={event=>setDraft(current=>({...current,slug:event.target.value.toLowerCase().replace(/[^a-z0-9-]/g,"-").replace(/-+/g,"-")}))} className="min-w-0 flex-1 pl-0.5 text-[9px] font-medium outline-none"/></div>{!slugUnique&&<small className="block text-[7px] font-semibold text-rose-600">This slug is already in use.</small>}</label></div><div className="grid gap-3 sm:grid-cols-2"><label className="space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Country of origin</span><input value={draft.country} onChange={event=>setDraft(current=>({...current,country:event.target.value}))} className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] font-medium outline-none focus:border-[#9eb7b4]"/></label><label className="space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Display order</span><input type="number" min="1" value={draft.order} onChange={event=>setDraft(current=>({...current,order:Number(event.target.value)||1}))} className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] font-medium outline-none focus:border-[#9eb7b4]"/></label></div><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Brand tagline</span><input value={draft.tagline} onChange={event=>setDraft(current=>({...current,tagline:event.target.value}))} placeholder="Short, factual positioning line" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] font-medium outline-none focus:border-[#9eb7b4]"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Customer-facing description</span><textarea rows={3} value={draft.description} onChange={event=>setDraft(current=>({...current,description:event.target.value}))} placeholder="Describe the brand without unverified claims or authorization language." className="w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Official website</span><input value={draft.website} onChange={event=>setDraft(current=>({...current,website:event.target.value}))} placeholder="https://..." className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] font-medium outline-none focus:border-[#9eb7b4]"/></label><div className="grid gap-3 sm:grid-cols-2"><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Logo asset</span><input value={draft.logo} onChange={event=>setDraft(current=>({...current,logo:event.target.value}))} placeholder="Media library reference" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] font-medium outline-none focus:border-[#9eb7b4]"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Brand hero asset</span><input value={draft.hero} onChange={event=>setDraft(current=>({...current,hero:event.target.value}))} placeholder="Media library reference" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] font-medium outline-none focus:border-[#9eb7b4]"/></label></div><label className="flex cursor-pointer items-start justify-between gap-3 rounded-xl border border-[#e2e8e5] p-4"><span><b className="block text-[8.5px] text-[#405049]">Featured-brand eligibility</b><small className="mt-1 block text-[7px] text-[#929d97]">Homepage CMS controls the final block and order.</small></span><input type="checkbox" checked={draft.featured} onChange={event=>setDraft(current=>({...current,featured:event.target.checked}))} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/></label><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-end"><label className="min-w-0 flex-1 space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5d7775]">Supply-source verification</span><select value={draft.verification} onChange={event=>setDraft(current=>({...current,verification:event.target.value as BrandVerification}))} className="h-10 w-full rounded-xl border border-[#cfded9] bg-white px-3 text-[8.5px] font-bold text-[#486965] outline-none"><option>Source verified</option><option>Documents pending</option><option>Not verified</option></select></label><label className="min-w-0 flex-1 space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5d7775]">Evidence reference</span><input value={draft.documentRef} onChange={event=>setDraft(current=>({...current,documentRef:event.target.value}))} placeholder="Invoice, PO or document ID" className="h-10 w-full rounded-xl border border-[#cfded9] bg-white px-3 text-[9px] outline-none"/></label></div><label className="mt-3 block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5d7775]">Internal source note</span><textarea rows={3} value={draft.sourceNote} onChange={event=>setDraft(current=>({...current,sourceNote:event.target.value}))} placeholder="What was reviewed and what remains uncertain?" className="w-full resize-none rounded-xl border border-[#cfded9] bg-white p-3 text-[9px] leading-5 outline-none"/></label>{!verificationReady&&<p className="mt-2 text-[7px] font-semibold text-rose-700">Verified status requires both an evidence reference and an internal review note.</p>}</div><div className="rounded-xl border border-[#e2e8e5] p-4"><div className="mb-3 flex items-center justify-between"><b className="text-[8.5px] text-[#405049]">Search appearance</b><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold "+(contentScore(draft)>=85?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700")}>{contentScore(draft)}% complete</span></div><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">SEO title · {draft.seoTitle.length}/60</span><input maxLength={60} value={draft.seoTitle} onChange={event=>setDraft(current=>({...current,seoTitle:event.target.value}))} className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><label className="mt-3 block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Meta description · {draft.seoDescription.length}/160</span><textarea maxLength={160} rows={3} value={draft.seoDescription} onChange={event=>setDraft(current=>({...current,seoDescription:event.target.value}))} className="w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label></div></div><aside className="space-y-3"><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5d7775]">Dependency summary</p><div className="mt-3 space-y-2">{[["Mapped products",String(draft.products)],["Live products",String(draft.liveProducts)],["Active sources",String(draft.activeSuppliers)],["Current status",draft.status]].map(([label,value])=><div key={label} className="flex items-center justify-between gap-3 text-[7.5px]"><span className="text-[#70837f]">{label}</span><b className="text-[#405b58]">{value}</b></div>)}</div></div>{slugChanged&&<div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><div className="flex items-center gap-2 text-amber-800"><Icon name="alert" size={12}/><b className="text-[8px]">Slug redirect required</b></div><p className="mt-2 text-[7px] leading-4 text-amber-700">The old URL /{originalBrand?.slug} must redirect to protect customer links and SEO.</p><label className="mt-3 block space-y-1.5"><span className="text-[7px] font-bold uppercase text-amber-800">Redirect destination</span><input value={redirectPath} onChange={event=>setRedirectPath(event.target.value)} placeholder={"/"+draft.slug} className="h-9 w-full rounded-lg border border-amber-200 bg-white px-3 text-[8px] outline-none"/></label></div>}<div className="rounded-xl border border-rose-100 bg-rose-50/60 p-4 text-[7.5px] leading-4 text-rose-800"><b className="block text-[8px]">Trust-language guardrail</b><p className="mt-2">Never use “official,” “authorized” or equivalent wording unless a valid authorization agreement is recorded.</p></div><div className="rounded-xl border border-[#e2e8e5] p-4 text-[7.5px] leading-4 text-[#718079]"><b className="block text-[8px] text-[#405049]">Versioned change</b><p className="mt-2">Saving creates a recoverable draft with actor, evidence status and changed fields.</p></div></aside></div><footer className="sticky bottom-0 flex flex-col-reverse gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur sm:flex-row sm:justify-end"><button onClick={()=>setEditorOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8.5px] font-bold text-[#65736c]">Cancel</button><button onClick={saveBrandDraft} disabled={!editorValid} className="flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-5 text-[8.5px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40"><Icon name="check" size={12}/>Save brand draft</button></footer></section></div>}

    {impactOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-3 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setImpactOpen(false)}}><section className="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white shadow-[0_30px_90px_rgba(17,35,30,.25)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Human approval required</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">{pendingAction} brand version</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Review products, URLs, evidence and storefront impact.</p></div><button onClick={()=>setImpactOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between"><b className="text-[8.5px] text-[#405049]">Selected brands</b><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">{impactTargets.length}</span></div><div className="mt-3 divide-y divide-[#edf0ee]">{impactTargets.map(item=><div key={item.id} className="flex items-center justify-between gap-3 py-2.5"><div><b className="block text-[8px] text-[#405049]">{item.name}</b><span className="mt-0.5 block font-mono text-[6.5px] text-[#929d97]">/{item.slug}</span></div><span className="text-[7px] text-[#718079]">{item.products} products · {item.verification}</span></div>)}</div></div><div className={"rounded-xl border p-4 "+(pendingAction==="Publish"?"border-emerald-200 bg-emerald-50":pendingAction==="Hide"?"border-amber-200 bg-amber-50":pendingAction==="Merge"?"border-violet-200 bg-violet-50":"border-rose-200 bg-rose-50")}><b className={"text-[8.5px] "+(pendingAction==="Publish"?"text-emerald-800":pendingAction==="Hide"?"text-amber-800":pendingAction==="Merge"?"text-violet-800":"text-rose-800")}>{pendingAction==="Publish"?"Makes the canonical brand page customer-visible.":pendingAction==="Hide"?"Removes customer discovery while preserving products and history.":pendingAction==="Merge"?"Moves products into one canonical brand record and retires duplicates.":"Retires the brand after product reassignment and URL protection."}</b><p className="mt-2 text-[7.5px] leading-4 text-[#65736c]">{pendingAction==="Publish"?"Requires mapped products, active source, verified evidence and at least 85% content readiness.":pendingAction==="Hide"?"Featured placement is removed; product-brand assignments remain unchanged.":"Products and live listings move to the chosen destination; historical IDs remain auditable."}</p></div>{publishBlockers.length>0&&<div className="rounded-xl border border-rose-200 bg-rose-50 p-4"><div className="flex items-center gap-2 text-rose-800"><Icon name="alert" size={12}/><b className="text-[8.5px]">Resolve blockers first</b></div><div className="mt-3 space-y-2">{publishBlockers.map(item=><p key={item.id} className="text-[7.5px] leading-4 text-rose-700"><b>{item.name}:</b> {item.products===0?"assign products":item.activeSuppliers===0?"connect an active supply source":item.verification!=="Source verified"?"complete source evidence review":"complete brand story, media and SEO to 85%"} before publishing.</p>)}</div></div>}{destinationRequired&&<label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Canonical destination brand</span><select value={destinationId} onChange={event=>setDestinationId(event.target.value)} className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option value="">Choose destination</option>{brands.filter(item=>!actionIds.includes(item.id)&&item.status!=="Archived").map(item=><option key={item.id} value={item.id}>{item.name} · {item.products} products</option>)}</select><small className="block text-[7px] text-[#929d97]">All products, live counts and storefront references move to this canonical record.</small></label>}<label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">{pendingAction==="Publish"?"Release note (optional)":"Reason for "+pendingAction.toLowerCase()}</span><textarea rows={3} value={actionReason} onChange={event=>setActionReason(event.target.value)} placeholder={pendingAction==="Publish"?"What is ready in this version?":"Required for the audit log"} className="w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label><label className="flex cursor-pointer items-start gap-3 rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><input type="checkbox" checked={actionConfirmed} onChange={event=>setActionConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 shrink-0 accent-[#3b646d]"/><span><b className="block text-[8.5px] text-[#405b58]">I reviewed catalog, trust and customer impact</b><small className="mt-1 block text-[7px] leading-4 text-[#70837f]">The audit trail records actor, reason, before/after brand IDs, source evidence and reassigned products. Previous versions remain recoverable.</small></span></label></div><footer className="flex flex-col-reverse gap-2 border-t border-[#e8ecea] p-4 sm:flex-row sm:justify-end"><button onClick={()=>setImpactOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8.5px] font-bold text-[#65736c]">Cancel</button><button onClick={applyBrandImpact} disabled={impactBlocked||!actionConfirmed||(pendingAction!=="Publish"&&!actionReason.trim())} className={"flex h-10 items-center justify-center gap-2 rounded-xl px-5 text-[8.5px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40 "+(pendingAction==="Archive"?"bg-rose-700":pendingAction==="Hide"?"bg-amber-600":pendingAction==="Merge"?"bg-violet-700":"bg-[#3b646d]")}><Icon name="check" size={12}/>{impactBlocked?"Resolve blockers":pendingAction+" selected"}</button></footer></section></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

type OfferStatus="Live"|"Scheduled"|"Draft"|"Paused"|"Ended"|"Archived";
type OfferType="Percentage"|"Fixed amount"|"Bundle"|"Buy X Get Y"|"Free shipping"|"Coupon";
type OfferRecord={
  id:string;name:string;type:OfferType;code:string;status:OfferStatus;benefit:string;eligibility:string;
  starts:string;ends:string;usage:number;limit:number|null;orders:number;revenue:number;margin:number;marginFloor:number;
  channels:string[];homepage:boolean;stackable:boolean;updated:string;
};

const initialOffers:OfferRecord[]=[
  {id:"OFF-2408",name:"Full Body Brightening Combo",type:"Bundle",code:"AUTO-BODY",status:"Live",benefit:"Save ৳320",eligibility:"4 selected body-care products",starts:"18 Aug · 12:00 AM",ends:"31 Aug · 11:59 PM",usage:184,limit:300,orders:184,revenue:291640,margin:31,marginFloor:25,channels:["Website","Admin"],homepage:true,stackable:false,updated:"12 min ago"},
  {id:"OFF-2407",name:"Acne Care Combo",type:"Bundle",code:"AUTO-ACNE",status:"Live",benefit:"Save ৳260",eligibility:"3 acne-care products",starts:"10 Aug · 12:00 AM",ends:"Open ended",usage:96,limit:null,orders:96,revenue:185280,margin:28,marginFloor:25,channels:["Website","Messenger"],homepage:true,stackable:false,updated:"34 min ago"},
  {id:"OFF-2406",name:"Buy 1 Get 1 Minis",type:"Buy X Get Y",code:"MINI-B1G1",status:"Scheduled",benefit:"1 free mini",eligibility:"Selected minis · same SKU",starts:"25 Aug · 10:00 AM",ends:"27 Aug · 11:59 PM",usage:0,limit:120,orders:0,revenue:0,margin:23,marginFloor:25,channels:["Website"],homepage:false,stackable:false,updated:"2 hr ago"},
  {id:"OFF-2405",name:"First Order Welcome",type:"Coupon",code:"WELCOME10",status:"Live",benefit:"10% off · max ৳150",eligibility:"First completed order · min ৳899",starts:"01 Aug · 12:00 AM",ends:"Open ended",usage:312,limit:1000,orders:286,revenue:344210,margin:35,marginFloor:25,channels:["Website","Admin"],homepage:false,stackable:false,updated:"Yesterday"},
  {id:"OFF-2404",name:"Free Delivery Dhaka",type:"Free shipping",code:"DHAKA-FREE",status:"Draft",benefit:"Free delivery",eligibility:"Dhaka metro · min ৳1,499",starts:"Not scheduled",ends:"Not scheduled",usage:0,limit:null,orders:0,revenue:0,margin:29,marginFloor:25,channels:["Website"],homepage:false,stackable:false,updated:"Yesterday"},
  {id:"OFF-2403",name:"Flash Sale Sunscreen",type:"Percentage",code:"SUN20",status:"Paused",benefit:"20% off",eligibility:"2 sunscreen products · min 1 item",starts:"19 Aug · 06:00 PM",ends:"22 Aug · 11:59 PM",usage:78,limit:150,orders:72,revenue:89640,margin:19,marginFloor:25,channels:["Website","Facebook"],homepage:true,stackable:false,updated:"2 days ago"},
  {id:"OFF-2402",name:"Editor’s Routine Bundle",type:"Fixed amount",code:"EDITORS250",status:"Scheduled",benefit:"৳250 off",eligibility:"Editor’s Picks · min ৳1,799",starts:"01 Sep · 12:00 AM",ends:"15 Sep · 11:59 PM",usage:0,limit:250,orders:0,revenue:0,margin:32,marginFloor:25,channels:["Website","Admin"],homepage:true,stackable:true,updated:"3 days ago"},
  {id:"OFF-2401",name:"Eid Glow Campaign",type:"Percentage",code:"EID15",status:"Ended",benefit:"15% off",eligibility:"Sitewide · exclusions applied",starts:"01 Jun · 12:00 AM",ends:"12 Jun · 11:59 PM",usage:418,limit:500,orders:391,revenue:512780,margin:26,marginFloor:25,channels:["Website","Admin"],homepage:false,stackable:false,updated:"12 Jun"},
];

type OfferView="All offers"|"Live"|"Scheduled"|"Drafts"|"Needs review"|"Ended";

function OffersDealsWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [offers,setOffers]=useState(initialOffers);
  const [view,setView]=useState<OfferView>("All offers");
  const [query,setQuery]=useState("");
  const [status,setStatus]=useState("All statuses");
  const [type,setType]=useState("All types");
  const [channel,setChannel]=useState("All channels");
  const [sort,setSort]=useState("Soonest ending");
  const [selectedIds,setSelectedIds]=useState<string[]>([]);
  const [focused,setFocused]=useState<OfferRecord|null>(null);
  const [editorOpen,setEditorOpen]=useState(false);
  const [editorMode,setEditorMode]=useState<"Create"|"Edit">("Create");
  const [draft,setDraft]=useState<OfferRecord>(initialOffers[0]);
  const [impactOpen,setImpactOpen]=useState(false);
  const [pendingAction,setPendingAction]=useState<"Publish"|"Pause"|"End"|"Archive">("Publish");
  const [actionIds,setActionIds]=useState<string[]>([]);
  const [actionReason,setActionReason]=useState("");
  const [actionConfirmed,setActionConfirmed]=useState(false);
  const [notice,setNotice]=useState("");
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const views:OfferView[]=["All offers","Live","Scheduled","Drafts","Needs review","Ended"];
  const viewCounts:Record<OfferView,number>={
    "All offers":offers.filter(item=>item.status!=="Archived").length,
    "Live":offers.filter(item=>item.status==="Live").length,
    "Scheduled":offers.filter(item=>item.status==="Scheduled").length,
    "Drafts":offers.filter(item=>item.status==="Draft").length,
    "Needs review":offers.filter(item=>item.margin<item.marginFloor||item.status==="Paused").length,
    "Ended":offers.filter(item=>item.status==="Ended").length,
  };
  let filtered=offers.filter(offer=>{
    const matchesQuery=(offer.name+" "+offer.code+" "+offer.eligibility).toLowerCase().includes(query.toLowerCase());
    const matchesStatus=status==="All statuses"||offer.status===status;
    const matchesType=type==="All types"||offer.type===type;
    const matchesChannel=channel==="All channels"||offer.channels.includes(channel);
    const matchesView=view==="All offers"||(view==="Live"&&offer.status==="Live")||(view==="Scheduled"&&offer.status==="Scheduled")||(view==="Drafts"&&offer.status==="Draft")||(view==="Needs review"&&(offer.margin<offer.marginFloor||offer.status==="Paused"))||(view==="Ended"&&offer.status==="Ended");
    return matchesQuery&&matchesStatus&&matchesType&&matchesChannel&&matchesView;
  });
  filtered=[...filtered].sort((a,b)=>sort==="Highest revenue"?b.revenue-a.revenue:sort==="Lowest margin"?a.margin-b.margin:sort==="Most used"?b.usage-a.usage:a.ends.localeCompare(b.ends));
  const allVisibleSelected=filtered.length>0&&filtered.every(item=>selectedIds.includes(item.id));
  const offerTone=(value:OfferStatus)=>value==="Live"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Scheduled"?"bg-sky-50 text-sky-700 ring-sky-200":value==="Draft"?"bg-slate-100 text-slate-600 ring-slate-200":value==="Paused"?"bg-amber-50 text-amber-700 ring-amber-200":value==="Ended"?"bg-violet-50 text-violet-700 ring-violet-200":"bg-rose-50 text-rose-700 ring-rose-200";
  const money=(value:number)=>value===0?"—":"৳"+new Intl.NumberFormat("en-BD",{maximumFractionDigits:0}).format(value);
  const usagePercent=(offer:OfferRecord)=>offer.limit?Math.min(100,Math.round((offer.usage/offer.limit)*100)):offer.usage>0?34:0;
  const riskOffers=offers.filter(item=>item.margin<item.marginFloor);
  const blankOffer:OfferRecord={id:"OFF-NEW",name:"",type:"Percentage",code:"",status:"Draft",benefit:"",eligibility:"",starts:"",ends:"",usage:0,limit:null,orders:0,revenue:0,margin:30,marginFloor:25,channels:["Website"],homepage:false,stackable:false,updated:"Not saved"};
  const openEditor=(mode:"Create"|"Edit",offer?:OfferRecord)=>{setEditorMode(mode);setDraft(offer?{...offer,channels:[...offer.channels]}:blankOffer);setEditorOpen(true);setFocused(null)};
  const codeUnique=!offers.some(item=>item.id!==draft.id&&item.code.trim().toLowerCase()===draft.code.trim().toLowerCase());
  const datesValid=Boolean(draft.starts.trim()&&draft.ends.trim()&&draft.starts!==draft.ends);
  const editorValid=Boolean(draft.name.trim()&&draft.code.trim()&&draft.benefit.trim()&&draft.eligibility.trim()&&draft.channels.length&&codeUnique&&datesValid&&draft.marginFloor>0);
  const saveOfferDraft=()=>{
    if(!editorValid){showNotice("Complete the rule, unique code, eligibility, channels and schedule.");return}
    const normalized:OfferRecord={...draft,status:editorMode==="Create"?"Draft":draft.status,updated:"Draft changes"};
    setOffers(current=>editorMode==="Create"?[{...normalized,id:"OFF-"+String(2409+current.length)},...current]:current.map(item=>item.id===draft.id?normalized:item));
    setEditorOpen(false);showNotice(editorMode==="Create"?"Offer draft created. Review margin and conflicts before publishing.":"Offer draft saved as a versioned change.");
  };
  const openImpact=(action:"Publish"|"Pause"|"End"|"Archive",ids:string[])=>{setPendingAction(action);setActionIds(ids);setActionReason("");setActionConfirmed(false);setImpactOpen(true);setFocused(null)};
  const impactTargets=offers.filter(item=>actionIds.includes(item.id));
  const publishBlockers=pendingAction==="Publish"?impactTargets.filter(item=>!item.name.trim()||!item.code.trim()||!item.eligibility.trim()||!item.starts.trim()||item.margin<item.marginFloor):[];
  const applyImpact=()=>{
    if(!actionConfirmed||publishBlockers.length>0||(pendingAction!=="Publish"&&!actionReason.trim()))return;
    const nextStatus:OfferStatus=pendingAction==="Publish"?(impactTargets.some(item=>item.starts.toLowerCase().includes("sep")||item.starts.toLowerCase().includes("25 aug"))?"Scheduled":"Live"):pendingAction==="Pause"?"Paused":pendingAction==="End"?"Ended":"Archived";
    setOffers(current=>current.map(item=>actionIds.includes(item.id)?{...item,status:nextStatus,homepage:pendingAction==="Archive"?false:item.homepage,updated:"Just now"}:item));
    setSelectedIds([]);setImpactOpen(false);showNotice(actionIds.length+" offer"+(actionIds.length===1?"":"s")+" moved to "+nextStatus.toLowerCase()+".");
  };

  return <div className="space-y-5">
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Commercial control</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Offers &amp; Deals</h1><p className="mt-1.5 max-w-2xl text-[12.5px] leading-5 text-[#66736d]">Plan discounts, bundles and coupons while protecting margin, eligibility and storefront consistency.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>showNotice("Offer export prepared with current filters and performance fields.")} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="download" size={13}/>Export</button><button onClick={()=>openEditor("Create")} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="plus" size={13}/>Create offer</button></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Live offers",String(viewCounts.Live),"3 storefront surfaces","store"],["Scheduled",String(viewCounts.Scheduled),"Next launch · 25 Aug","calendar"],["Revenue influenced",money(offers.reduce((sum,item)=>sum+item.revenue,0)),"Attributed offer orders","finance"],["Margin risk",String(riskOffers.length),"Below configured floor","alert"]].map(([label,value,note,icon],index)=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-start justify-between"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#edf3f4] text-[#3b646d]"><Icon name={icon as IconName} size={15}/></span><span className={"rounded-full px-2 py-1 text-[7px] font-bold "+(index===3?"bg-rose-50 text-rose-700":"bg-emerald-50 text-emerald-700")}>{index===3?"Review":"Healthy"}</span></div><b className="mt-4 block text-[22px] tracking-[-.03em] text-[#23322b]">{value}</b><span className="mt-1 block text-[9px] font-bold text-[#65736c]">{label}</span><small className="mt-1 block text-[7.5px] text-[#929d97]">{note}</small></article>)}</section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Offer calendar</p><b className="mt-1 block text-[12px] text-[#33423b]">2 launches are scheduled</b></div><span className="rounded-full bg-sky-50 px-2 py-1 text-[7px] font-bold text-sky-700">On track</span></div><div className="mt-3 space-y-2">{offers.filter(item=>item.status==="Scheduled").map(item=><button key={item.id} onClick={()=>setFocused(item)} className="flex w-full items-center justify-between gap-3 rounded-lg bg-[#f8faf9] px-3 py-2 text-left"><span className="truncate text-[7.5px] font-bold text-[#52615a]">{item.name}</span><span className="shrink-0 text-[7px] text-[#87928d]">{item.starts.split(" · ")[0]}</span></button>)}</div></article><article className="rounded-2xl border border-rose-100 bg-rose-50/60 p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-rose-700">Margin guardrail</p><b className="mt-1 block text-[12px] text-rose-900">2 offers need commercial review</b></div><Icon name="alert" size={15} className="text-rose-700"/></div><p className="mt-3 text-[7.5px] leading-4 text-rose-800">Projected contribution margin is below the 25% floor. Publishing remains human-approved.</p><button onClick={()=>setView("Needs review")} className="mt-3 text-[7.5px] font-bold text-rose-800">Review risky offers →</button></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5d7775]">Stacking control</p><b className="mt-1 block text-[12px] text-[#304d4d]">1 potential rule conflict</b></div><span className="rounded-full bg-white px-2 py-1 text-[7px] font-bold text-amber-700">Review</span></div><p className="mt-3 text-[7.5px] leading-4 text-[#647b77]">Editor’s bundle is marked stackable and overlaps WELCOME10 eligibility. Conflict detection requires backend rule evaluation.</p></article></section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{views.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold transition "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d] hover:text-[#53645d]")}>{item}<span className={"ml-2 rounded-full px-1.5 py-0.5 text-[7px] "+(view===item?"bg-[#edf3f4]":"bg-[#f2f4f3]")}>{viewCounts[item]}</span></button>)}</div></div><div className="space-y-3 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:p-5"><div className="flex flex-col gap-2 xl:flex-row"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search offer, code or eligibility..." className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><select value={status} onChange={event=>setStatus(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All statuses</option>{["Live","Scheduled","Draft","Paused","Ended","Archived"].map(item=><option key={item}>{item}</option>)}</select><select value={type} onChange={event=>setType(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All types</option>{["Percentage","Fixed amount","Bundle","Buy X Get Y","Free shipping","Coupon"].map(item=><option key={item}>{item}</option>)}</select><select value={channel} onChange={event=>setChannel(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All channels</option>{["Website","Admin","Messenger","Facebook"].map(item=><option key={item}>{item}</option>)}</select><select value={sort} onChange={event=>setSort(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>Soonest ending</option><option>Highest revenue</option><option>Lowest margin</option><option>Most used</option></select></div></div>

      {selectedIds.length>0&&<div className="flex flex-col gap-3 border-b border-[#d8e4e0] bg-[#edf3f4] px-4 py-3 sm:flex-row sm:items-center sm:px-5"><div className="flex min-w-0 flex-1 items-center gap-2"><span className="flex h-7 min-w-7 items-center justify-center rounded-lg bg-[#3b646d] px-2 text-[8px] font-bold text-white">{selectedIds.length}</span><b className="text-[8.5px] text-[#405b58]">offers selected</b></div><div className="flex flex-wrap gap-2"><button onClick={()=>openImpact("Publish",selectedIds)} className="h-8 rounded-lg border border-[#c7d8d3] bg-white px-3 text-[8px] font-bold text-[#416764]">Publish / schedule</button><button onClick={()=>openImpact("Pause",selectedIds)} className="h-8 rounded-lg border border-amber-200 bg-white px-3 text-[8px] font-bold text-amber-700">Pause</button><button onClick={()=>setSelectedIds([])} className="flex h-8 w-8 items-center justify-center rounded-lg text-[#708079]"><Icon name="close" size={12}/></button></div></div>}

      <div className="overflow-x-auto"><table className="w-full min-w-[1320px] text-left"><thead className="bg-[#fafbfa] text-[7px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="w-12 px-5 py-3.5"><input type="checkbox" aria-label="Select all visible offers" checked={allVisibleSelected} onChange={event=>setSelectedIds(current=>event.target.checked?Array.from(new Set([...current,...filtered.map(item=>item.id)])):current.filter(id=>!filtered.some(item=>item.id===id)))} className="h-3.5 w-3.5 accent-[#3b646d]"/></th><th className="px-2 py-3.5">Offer</th><th className="px-4 py-3.5">Benefit</th><th className="px-4 py-3.5">Eligibility</th><th className="px-4 py-3.5">Schedule</th><th className="px-4 py-3.5">Usage &amp; performance</th><th className="px-4 py-3.5">Margin health</th><th className="px-4 py-3.5">Status &amp; surfaces</th><th className="px-4 py-3.5">Updated</th><th className="w-12 px-4 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{filtered.map(offer=><tr key={offer.id} className="text-[8.5px] text-[#5f6e67] hover:bg-[#fafcfb]"><td className="px-5 py-4"><input type="checkbox" aria-label={"Select "+offer.name} checked={selectedIds.includes(offer.id)} onChange={event=>setSelectedIds(current=>event.target.checked?[...current,offer.id]:current.filter(id=>id!==offer.id))} className="h-3.5 w-3.5 accent-[#3b646d]"/></td><td className="px-2 py-4"><button onClick={()=>setFocused(offer)} className="min-w-[210px] text-left"><b className="block max-w-[210px] truncate text-[9px] text-[#33423b]">{offer.name}</b><span className="mt-1 flex items-center gap-1.5"><small className="font-mono text-[6.5px] text-[#3b646d]">{offer.code}</small><small className="text-[6.5px] text-[#9aa49f]">· {offer.id}</small></span></button></td><td className="px-4 py-4"><span className="inline-flex rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">{offer.type}</span><b className="mt-1.5 block text-[8px] text-[#405049]">{offer.benefit}</b></td><td className="max-w-[210px] px-4 py-4"><span className="block leading-4">{offer.eligibility}</span><small className="mt-1 block text-[6.5px] text-[#929d97]">{offer.stackable?"Stackable · exclusions apply":"Not stackable"}</small></td><td className="px-4 py-4"><b className="block text-[7.5px] text-[#52615a]">{offer.starts}</b><span className="mt-1 block text-[7px] text-[#929d97]">to {offer.ends}</span></td><td className="min-w-[170px] px-4 py-4"><div className="flex items-center justify-between"><b className="text-[8px] text-[#405049]">{offer.usage}{offer.limit?" / "+offer.limit:" uses"}</b><span className="text-[7px] text-[#728078]">{money(offer.revenue)}</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#edf1ef]"><div className="h-full rounded-full bg-[#5f8585]" style={{width:usagePercent(offer)+"%"}}/></div><small className="mt-1 block text-[6.5px] text-[#929d97]">{offer.orders} attributed orders</small></td><td className="px-4 py-4"><div className="flex items-center gap-2"><b className={"text-[10px] "+(offer.margin<offer.marginFloor?"text-rose-700":"text-emerald-700")}>{offer.margin}%</b><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold "+(offer.margin<offer.marginFloor?"bg-rose-50 text-rose-700":"bg-emerald-50 text-emerald-700")}>{offer.margin<offer.marginFloor?"Below floor":"Protected"}</span></div><small className="mt-1.5 block text-[6.5px] text-[#929d97]">Floor {offer.marginFloor}% · projected</small></td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[7px] font-bold ring-1 ring-inset "+offerTone(offer.status)}>{offer.status}</span><span className="mt-1.5 block max-w-[160px] truncate text-[6.5px] text-[#87928d]">{offer.channels.join(" · ")}{offer.homepage?" · Homepage":""}</span></td><td className="px-4 py-4 text-[7px] text-[#87928d]">{offer.updated}</td><td className="px-4 py-4"><button onClick={()=>setFocused(offer)} aria-label={"Open "+offer.name} className="flex h-8 w-8 items-center justify-center rounded-lg text-[#84908a] hover:bg-[#edf3f4] hover:text-[#3b646d]"><Icon name="chevron" size={13}/></button></td></tr>)}</tbody></table>{filtered.length===0&&<div className="flex flex-col items-center justify-center px-5 py-16 text-center"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#edf3f4] text-[#3b646d]"><Icon name="search" size={18}/></span><b className="mt-3 text-[10px] text-[#405049]">No offers match this view</b><p className="mt-1 text-[8px] text-[#929d97]">Clear filters or choose another status.</p><button onClick={()=>{setQuery("");setStatus("All statuses");setType("All types");setChannel("All channels");setView("All offers")}} className="mt-4 rounded-lg border border-[#dce4e0] px-3 py-2 text-[8px] font-bold text-[#3b646d]">Clear filters</button></div>}</div>
    </section>

    <section className="grid gap-3 lg:grid-cols-2"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">System boundary</p><b className="mt-1 block text-[12px] text-[#33423b]">Existing offer controls remain the source of truth</b><p className="mt-3 text-[7.5px] leading-4 text-[#87928d]">Discount rules, storefront offer placements and existing business logic are preserved. Projected margin and stacking diagnosis are labelled as backend-dependent until implemented.</p></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5d7775]">Storefront ownership</p><b className="mt-1 block text-[12px] text-[#304d4d]">Promotion logic here. Placement order in CMS.</b><p className="mt-3 text-[7.5px] leading-4 text-[#647b77]">An offer may be eligible for homepage display, but Homepage CMS controls its final position and creative.</p><button onClick={()=>onNavigate("Homepage CMS")} className="mt-3 text-[7.5px] font-bold text-[#3b646d]">Open Homepage CMS →</button></article></section>

    {focused&&<div className="fixed inset-0 z-[80] bg-[#17231f]/25 backdrop-blur-[1px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-md overflow-y-auto bg-white shadow-[-24px_0_70px_rgba(18,37,31,.16)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Offer inspector</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">{focused.name}</h2><p className="mt-1 font-mono text-[7px] text-[#87928d]">{focused.code} · {focused.id}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="flex flex-wrap gap-2"><span className={"inline-flex rounded-full px-2.5 py-1 text-[7.5px] font-bold ring-1 ring-inset "+offerTone(focused.status)}>{focused.status}</span><span className="rounded-full bg-[#edf3f4] px-2.5 py-1 text-[7.5px] font-bold text-[#3b646d]">{focused.type}</span>{focused.homepage&&<span className="rounded-full bg-violet-50 px-2.5 py-1 text-[7.5px] font-bold text-violet-700">Homepage eligible</span>}</div><div className="grid grid-cols-2 gap-3">{[["Benefit",focused.benefit],["Projected margin",focused.margin+"%"],["Usage",focused.usage+(focused.limit?" / "+focused.limit:"")],["Revenue",money(focused.revenue)]].map(([label,value])=><div key={label} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6.5px] font-bold uppercase tracking-[.08em] text-[#929d97]">{label}</span><b className="mt-1 block text-[9px] text-[#405049]">{value}</b></div>)}</div><div className="rounded-xl border border-[#e2e8e5] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Rule summary</p><div className="mt-3 space-y-2.5">{[["Eligibility",focused.eligibility],["Schedule",focused.starts+" → "+focused.ends],["Channels",focused.channels.join(", ")],["Stacking",focused.stackable?"Allowed with exclusions":"Blocked"]].map(([label,value])=><div key={label} className="flex items-start justify-between gap-4 text-[7.5px]"><span className="shrink-0 text-[#929d97]">{label}</span><b className="max-w-[240px] text-right leading-4 text-[#52615a]">{value}</b></div>)}</div></div>{focused.margin<focused.marginFloor&&<div className="rounded-xl border border-rose-200 bg-rose-50 p-4"><div className="flex items-center gap-2 text-rose-800"><Icon name="alert" size={12}/><b className="text-[8.5px]">Below margin floor</b></div><p className="mt-2 text-[7.5px] leading-4 text-rose-700">Projected margin is {focused.margin}% against the {focused.marginFloor}% guardrail. Review COGS, discount and stacking before release.</p></div>}<div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Attribution note</b><p className="mt-2 text-[7.5px] leading-4 text-[#70837f]">Revenue is influenced revenue, not necessarily incremental revenue. A backend attribution model is required for causal reporting.</p></div></div><footer className="sticky bottom-0 flex gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur"><button onClick={()=>openEditor("Edit",focused)} className="flex h-10 flex-1 items-center justify-center gap-2 rounded-xl border border-[#dce4e0] text-[8.5px] font-bold text-[#596962]"><Icon name="edit" size={12}/>Edit offer</button><button onClick={()=>openImpact(focused.status==="Live"?"Pause":"Publish",[focused.id])} className="flex h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-[#3b646d] text-[8.5px] font-bold text-white"><Icon name="check" size={12}/>{focused.status==="Live"?"Pause offer":"Publish / schedule"}</button></footer></aside></div>}

    {editorOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-3 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setEditorOpen(false)}}><section className="max-h-[94vh] w-full max-w-5xl overflow-y-auto rounded-2xl bg-white shadow-[0_30px_90px_rgba(17,35,30,.25)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Versioned offer builder</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">{editorMode} offer</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Define the commercial rule first; publishing stays a separate approval.</p></div><button onClick={()=>setEditorOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="grid gap-5 p-5 lg:grid-cols-[minmax(0,1fr)_280px]"><div className="space-y-4"><div className="rounded-2xl border border-[#e2e8e5] p-4"><div className="mb-4"><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Offer identity</p><b className="mt-1 block text-[11px] text-[#405049]">Name, mechanism and customer benefit</b></div><div className="grid gap-3 sm:grid-cols-2"><label className="block space-y-1.5 sm:col-span-2"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Internal offer name *</span><input value={draft.name} onChange={event=>setDraft(current=>({...current,name:event.target.value}))} placeholder="e.g. September Skin Barrier Week" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Offer type *</span><select value={draft.type} onChange={event=>setDraft(current=>({...current,type:event.target.value as OfferType}))} className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none">{["Percentage","Fixed amount","Bundle","Buy X Get Y","Free shipping","Coupon"].map(item=><option key={item}>{item}</option>)}</select></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Code / rule key *</span><input value={draft.code} onChange={event=>setDraft(current=>({...current,code:event.target.value.toUpperCase().replace(/\s/g,"-")}))} placeholder="SEPT20" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 font-mono text-[9px] outline-none focus:border-[#9eb7b4]"/><small className={"block text-[6.5px] "+(codeUnique?"text-emerald-700":"text-rose-700")}>{codeUnique?"Unique across active and archived offers":"Code already exists"}</small></label><label className="block space-y-1.5 sm:col-span-2"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Customer benefit *</span><input value={draft.benefit} onChange={event=>setDraft(current=>({...current,benefit:event.target.value}))} placeholder="e.g. 15% off · max ৳250" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label></div></div><div className="rounded-2xl border border-[#e2e8e5] p-4"><div className="mb-4"><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Eligibility &amp; limits</p><b className="mt-1 block text-[11px] text-[#405049]">Who qualifies, what applies and how often</b></div><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Eligibility summary *</span><textarea rows={3} value={draft.eligibility} onChange={event=>setDraft(current=>({...current,eligibility:event.target.value}))} placeholder="Products, categories, brands, customer segment and minimum order" className="w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Maximum uses</span><input type="number" min="0" value={draft.limit??""} onChange={event=>setDraft(current=>({...current,limit:event.target.value?Number(event.target.value):null}))} placeholder="Unlimited" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Per-customer cap</span><select className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f]"><option>1 use per customer</option><option>2 uses per customer</option><option>Unlimited</option></select></label></div><label className="mt-3 flex cursor-pointer items-start justify-between gap-3 rounded-xl border border-[#e2e8e5] p-4"><span><b className="block text-[8.5px] text-[#405049]">Allow stacking</b><small className="mt-1 block text-[7px] leading-4 text-[#929d97]">If enabled, configure explicit exclusions before publication.</small></span><input type="checkbox" checked={draft.stackable} onChange={event=>setDraft(current=>({...current,stackable:event.target.checked}))} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/></label></div><div className="rounded-2xl border border-[#e2e8e5] p-4"><div className="mb-4"><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Schedule &amp; surfaces</p><b className="mt-1 block text-[11px] text-[#405049]">Control timing and where the rule may be used</b></div><div className="grid gap-3 sm:grid-cols-2"><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Starts *</span><input value={draft.starts} onChange={event=>setDraft(current=>({...current,starts:event.target.value}))} placeholder="01 Sep · 12:00 AM" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Ends *</span><input value={draft.ends} onChange={event=>setDraft(current=>({...current,ends:event.target.value}))} placeholder="15 Sep · 11:59 PM or Open ended" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none"/></label></div><div className="mt-4"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Allowed channels *</span><div className="mt-2 flex flex-wrap gap-2">{["Website","Admin","Messenger","Facebook"].map(item=><label key={item} className={"flex cursor-pointer items-center gap-2 rounded-lg border px-3 py-2 text-[7.5px] font-bold "+(draft.channels.includes(item)?"border-[#9fb8b5] bg-[#edf3f4] text-[#3b646d]":"border-[#dce4e0] text-[#718079]")}><input type="checkbox" checked={draft.channels.includes(item)} onChange={event=>setDraft(current=>({...current,channels:event.target.checked?[...current.channels,item]:current.channels.filter(channelName=>channelName!==item)}))} className="h-3.5 w-3.5 accent-[#3b646d]"/>{item}</label>)}</div></div><label className="mt-4 flex cursor-pointer items-start justify-between gap-3 rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><span><b className="block text-[8.5px] text-[#405b58]">Homepage placement eligible</b><small className="mt-1 block text-[7px] text-[#70837f]">Homepage CMS still owns block position, creative and final visibility.</small></span><input type="checkbox" checked={draft.homepage} onChange={event=>setDraft(current=>({...current,homepage:event.target.checked}))} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/></label></div></div><aside className="space-y-3"><div className="rounded-2xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5d7775]">Commercial guardrail</p><div className="mt-3 grid grid-cols-2 gap-2"><label className="block space-y-1.5"><span className="text-[6.5px] font-bold text-[#70837f]">Projected margin</span><input type="number" min="0" max="100" value={draft.margin} onChange={event=>setDraft(current=>({...current,margin:Number(event.target.value)}))} className="h-9 w-full rounded-lg border border-[#cfded9] bg-white px-3 text-[8.5px] font-bold outline-none"/></label><label className="block space-y-1.5"><span className="text-[6.5px] font-bold text-[#70837f]">Minimum floor</span><input type="number" min="0" max="100" value={draft.marginFloor} onChange={event=>setDraft(current=>({...current,marginFloor:Number(event.target.value)}))} className="h-9 w-full rounded-lg border border-[#cfded9] bg-white px-3 text-[8.5px] font-bold outline-none"/></label></div><div className={"mt-3 rounded-xl p-3 "+(draft.margin<draft.marginFloor?"bg-rose-50 text-rose-800":"bg-white text-emerald-800")}><b className="block text-[8px]">{draft.margin<draft.marginFloor?"Publication blocker":"Margin floor protected"}</b><p className="mt-1 text-[6.5px] leading-4">{draft.margin<draft.marginFloor?"Projected margin is below the commercial floor.":"Projected margin remains above the configured floor."}</p></div><p className="mt-3 text-[6.5px] leading-4 text-[#70837f]">Requires backend: calculate margin from COGS, courier, payment fees, discounts and expected returns.</p></div><div className="rounded-2xl border border-amber-200 bg-amber-50 p-4"><div className="flex items-center gap-2 text-amber-800"><Icon name="alert" size={12}/><b className="text-[8px]">Stacking diagnostics</b></div><p className="mt-2 text-[7px] leading-4 text-amber-700">{draft.stackable?"Potential overlap with WELCOME10. Add exclusions before publish.":"Stacking disabled; checkout should apply one eligible promotion."}</p><small className="mt-2 block text-[6.5px] font-semibold text-amber-800">Requires backend rule evaluation</small></div><div className="rounded-2xl border border-[#e2e8e5] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Pre-publish checks</p><div className="mt-3 space-y-2">{[["Unique code",codeUnique],["Eligibility defined",Boolean(draft.eligibility.trim())],["Schedule valid",datesValid],["Channel selected",draft.channels.length>0],["Margin protected",draft.margin>=draft.marginFloor]].map(([label,valid])=><div key={String(label)} className="flex items-center justify-between gap-3 text-[7.5px]"><span className="text-[#718079]">{label as string}</span><span className={"flex h-5 w-5 items-center justify-center rounded-full "+(valid?"bg-emerald-50 text-emerald-700":"bg-rose-50 text-rose-700")}><Icon name={valid?"check":"close"} size={9}/></span></div>)}</div></div><div className="rounded-2xl border border-[#e2e8e5] p-4 text-[7px] leading-4 text-[#718079]"><b className="block text-[8px] text-[#405049]">Safe change model</b><p className="mt-2">Save creates a recoverable draft. Publishing, pausing, ending and archiving require a separate human approval and audit reason.</p></div></aside></div><footer className="sticky bottom-0 flex flex-col-reverse gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur sm:flex-row sm:justify-end"><button onClick={()=>setEditorOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8.5px] font-bold text-[#65736c]">Cancel</button><button onClick={saveOfferDraft} disabled={!editorValid} className="flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-5 text-[8.5px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40"><Icon name="check" size={12}/>Save offer draft</button></footer></section></div>}

    {impactOpen&&<div className="fixed inset-0 z-[95] flex items-center justify-center bg-[#17231f]/35 p-3 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setImpactOpen(false)}}><section className="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white shadow-[0_30px_90px_rgba(17,35,30,.25)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Human approval required</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Manage offer status</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Review customer, margin and storefront impact before release.</p></div><button onClick={()=>setImpactOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid grid-cols-4 gap-2">{(["Publish","Pause","End","Archive"] as const).map(action=><button key={action} onClick={()=>setPendingAction(action)} className={"rounded-xl border px-2 py-2.5 text-[7.5px] font-bold "+(pendingAction===action?"border-[#3b646d] bg-[#edf3f4] text-[#3b646d]":"border-[#e2e8e5] text-[#718079]")}>{action}</button>)}</div><div className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between"><b className="text-[8.5px] text-[#405049]">Selected offers</b><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">{impactTargets.length}</span></div><div className="mt-3 divide-y divide-[#edf0ee]">{impactTargets.map(item=><div key={item.id} className="flex items-center justify-between gap-3 py-2.5"><div><b className="block text-[8px] text-[#405049]">{item.name}</b><span className="mt-0.5 block font-mono text-[6.5px] text-[#929d97]">{item.code}</span></div><span className={"text-[7px] font-bold "+(item.margin<item.marginFloor?"text-rose-700":"text-emerald-700")}>{item.margin}% margin</span></div>)}</div></div><div className={"rounded-xl border p-4 "+(pendingAction==="Publish"?"border-emerald-200 bg-emerald-50":pendingAction==="Pause"?"border-amber-200 bg-amber-50":"border-rose-200 bg-rose-50")}><b className="text-[8.5px] text-[#405049]">{pendingAction==="Publish"?"Valid offers become live now or scheduled for their start date.":pendingAction==="Pause"?"Checkout stops applying the offer; configuration and usage history remain.":pendingAction==="End"?"The campaign closes permanently; existing order history remains attributed.":"The record leaves active operations and homepage eligibility is removed."}</b><p className="mt-2 text-[7.5px] leading-4 text-[#65736c]">No financial or customer-impacting change is applied automatically. This action is recorded with actor, time, reason and before/after state.</p></div>{publishBlockers.length>0&&<div className="rounded-xl border border-rose-200 bg-rose-50 p-4"><div className="flex items-center gap-2 text-rose-800"><Icon name="alert" size={12}/><b className="text-[8.5px]">Publication blocked</b></div><div className="mt-3 space-y-2">{publishBlockers.map(item=><p key={item.id} className="text-[7.5px] leading-4 text-rose-700"><b>{item.name}:</b> {item.margin<item.marginFloor?"projected margin is below the configured floor":"complete rule, eligibility and schedule fields"}.</p>)}</div></div>}<label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">{pendingAction==="Publish"?"Release note (optional)":"Audit reason *"}</span><textarea rows={3} value={actionReason} onChange={event=>setActionReason(event.target.value)} placeholder={pendingAction==="Publish"?"What was reviewed in this release?":"Required reason for the audit log"} className="w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label><label className="flex cursor-pointer items-start gap-3 rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><input type="checkbox" checked={actionConfirmed} onChange={event=>setActionConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 shrink-0 accent-[#3b646d]"/><span><b className="block text-[8.5px] text-[#405b58]">I reviewed rule, schedule, margin and storefront impact</b><small className="mt-1 block text-[7px] leading-4 text-[#70837f]">The previous version remains recoverable. Any automated future workflow must use the same approval boundary.</small></span></label></div><footer className="flex flex-col-reverse gap-2 border-t border-[#e8ecea] p-4 sm:flex-row sm:justify-end"><button onClick={()=>setImpactOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8.5px] font-bold text-[#65736c]">Cancel</button><button onClick={applyImpact} disabled={!actionConfirmed||publishBlockers.length>0||(pendingAction!=="Publish"&&!actionReason.trim())} className={"flex h-10 items-center justify-center gap-2 rounded-xl px-5 text-[8.5px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40 "+(pendingAction==="Archive"||pendingAction==="End"?"bg-rose-700":pendingAction==="Pause"?"bg-amber-600":"bg-[#3b646d]")}><Icon name="check" size={12}/>{publishBlockers.length?"Resolve blockers":pendingAction+" selected"}</button></footer></section></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

type RecommendationStatus="Live"|"Scheduled"|"Draft"|"Paused"|"Archived";
type RecommendationStrategy="Complete the routine"|"Frequently bought together"|"Similar alternative"|"Upgrade"|"Best sellers"|"New arrivals";
type RecommendationMethod="Manual"|"Rule-assisted"|"AI suggestion";
type RecommendationSet={
  id:string;name:string;strategy:RecommendationStrategy;method:RecommendationMethod;source:string;sourceScope:string;
  targets:string[];surfaces:string[];status:RecommendationStatus;priority:number;coverage:number;orders:number;revenue:number;
  margin:number;stockSafe:boolean;fallback:string;schedule:string;updated:string;
};

const initialRecommendationSets:RecommendationSet[]=[
  {id:"REC-108",name:"Acne Routine Completion",strategy:"Complete the routine",method:"Manual",source:"Acne Control Facewash",sourceScope:"1 product",targets:["Salicylic Acid Serum","Hydra Gel Moisturizer","Daily Sun Gel SPF 50"],surfaces:["Product page","Cart"],status:"Live",priority:1,coverage:100,orders:82,revenue:104540,margin:37,stockSafe:true,fallback:"Best in-stock match",schedule:"Always on",updated:"18 min ago"},
  {id:"REC-107",name:"Brightening Body Pairing",strategy:"Frequently bought together",method:"Rule-assisted",source:"Kojic Body Wash",sourceScope:"1 product",targets:["Double Brightening Kojic Soap","Niacinamide Body Lotion"],surfaces:["Product page","Cart"],status:"Live",priority:2,coverage:100,orders:64,revenue:72160,margin:34,stockSafe:true,fallback:"Hide unavailable item",schedule:"Always on",updated:"42 min ago"},
  {id:"REC-106",name:"Vitamin C Routine",strategy:"Complete the routine",method:"Manual",source:"Vitamin C Serum",sourceScope:"1 product",targets:["Gentle Cleanser","Hydra Gel Moisturizer","Daily Sun Gel SPF 50"],surfaces:["Product page"],status:"Live",priority:1,coverage:100,orders:51,revenue:69870,margin:39,stockSafe:true,fallback:"Best in-stock match",schedule:"Always on",updated:"Yesterday"},
  {id:"REC-105",name:"Sunscreen Alternatives",strategy:"Similar alternative",method:"Rule-assisted",source:"Sunscreen category",sourceScope:"8 products",targets:["Daily Sun Gel SPF 50","Aqua Sun Essence","Mineral Sun Cream"],surfaces:["Product page","Search no-result"],status:"Draft",priority:3,coverage:75,orders:0,revenue:0,margin:31,stockSafe:false,fallback:"Hide block",schedule:"Not scheduled",updated:"Yesterday"},
  {id:"REC-104",name:"Routine Upgrade Test",strategy:"Upgrade",method:"AI suggestion",source:"Low-AOV skincare carts",sourceScope:"132 carts / 30D",targets:["Editor’s Routine Bundle","Barrier Repair Set"],surfaces:["Cart"],status:"Draft",priority:4,coverage:62,orders:0,revenue:0,margin:29,stockSafe:true,fallback:"Keep current cart",schedule:"Not scheduled",updated:"2 days ago"},
  {id:"REC-103",name:"Homepage Best Sellers",strategy:"Best sellers",method:"Rule-assisted",source:"Delivered sales · 30 days",sourceScope:"228 live products",targets:["Kojic Body Wash","Acne Control Facewash","Vitamin C Serum","Daily Sun Gel SPF 50"],surfaces:["Homepage"],status:"Live",priority:1,coverage:96,orders:218,revenue:283420,margin:35,stockSafe:true,fallback:"Next ranked product",schedule:"Refresh daily",updated:"Today · 6:00 AM"},
  {id:"REC-102",name:"New Arrival Discovery",strategy:"New arrivals",method:"Rule-assisted",source:"Published within 30 days",sourceScope:"12 products",targets:["Barrier Repair Cream","Cica Calming Toner","Rice Cleansing Oil"],surfaces:["Homepage","Product page"],status:"Scheduled",priority:5,coverage:83,orders:0,revenue:0,margin:33,stockSafe:true,fallback:"Newest in-stock item",schedule:"25 Aug · 10:00 AM",updated:"3 days ago"},
  {id:"REC-101",name:"Haircare Cross-sell",strategy:"Frequently bought together",method:"Manual",source:"Ketoconazole Shampoo",sourceScope:"1 product",targets:["Scalp Massager","Hair Growth Tonic"],surfaces:["Product page"],status:"Paused",priority:6,coverage:50,orders:17,revenue:18490,margin:22,stockSafe:false,fallback:"Hide block",schedule:"Paused 19 Aug",updated:"3 days ago"},
];

type RecommendationView="All sets"|"Live"|"Drafts"|"Needs review"|"AI suggestions"|"Paused";

function ProductRecommendationsWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [sets,setSets]=useState(initialRecommendationSets);
  const [view,setView]=useState<RecommendationView>("All sets");
  const [query,setQuery]=useState("");
  const [strategy,setStrategy]=useState("All strategies");
  const [method,setMethod]=useState("All methods");
  const [surface,setSurface]=useState("All surfaces");
  const [sort,setSort]=useState("Priority");
  const [selectedIds,setSelectedIds]=useState<string[]>([]);
  const [focused,setFocused]=useState<RecommendationSet|null>(null);
  const [editorOpen,setEditorOpen]=useState(false);
  const [editorMode,setEditorMode]=useState<"Create"|"Edit">("Create");
  const [draft,setDraft]=useState<RecommendationSet>(initialRecommendationSets[0]);
  const [targetInput,setTargetInput]=useState("");
  const [impactOpen,setImpactOpen]=useState(false);
  const [pendingAction,setPendingAction]=useState<"Publish"|"Pause"|"Archive">("Publish");
  const [actionIds,setActionIds]=useState<string[]>([]);
  const [actionReason,setActionReason]=useState("");
  const [actionConfirmed,setActionConfirmed]=useState(false);
  const [notice,setNotice]=useState("");
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const views:RecommendationView[]=["All sets","Live","Drafts","Needs review","AI suggestions","Paused"];
  const needsReview=(item:RecommendationSet)=>item.coverage<80||item.margin<25||!item.stockSafe||item.method==="AI suggestion";
  const viewCounts:Record<RecommendationView,number>={
    "All sets":sets.filter(item=>item.status!=="Archived").length,
    "Live":sets.filter(item=>item.status==="Live").length,
    "Drafts":sets.filter(item=>item.status==="Draft").length,
    "Needs review":sets.filter(needsReview).length,
    "AI suggestions":sets.filter(item=>item.method==="AI suggestion").length,
    "Paused":sets.filter(item=>item.status==="Paused").length,
  };
  let filtered=sets.filter(item=>{
    const matchesQuery=(item.name+" "+item.source+" "+item.targets.join(" ")).toLowerCase().includes(query.toLowerCase());
    const matchesStrategy=strategy==="All strategies"||item.strategy===strategy;
    const matchesMethod=method==="All methods"||item.method===method;
    const matchesSurface=surface==="All surfaces"||item.surfaces.includes(surface);
    const matchesView=view==="All sets"||(view==="Live"&&item.status==="Live")||(view==="Drafts"&&item.status==="Draft")||(view==="Needs review"&&needsReview(item))||(view==="AI suggestions"&&item.method==="AI suggestion")||(view==="Paused"&&item.status==="Paused");
    return matchesQuery&&matchesStrategy&&matchesMethod&&matchesSurface&&matchesView;
  });
  filtered=[...filtered].sort((a,b)=>sort==="Highest revenue"?b.revenue-a.revenue:sort==="Lowest coverage"?a.coverage-b.coverage:sort==="Recently updated"?a.updated.localeCompare(b.updated):a.priority-b.priority);
  const allVisibleSelected=filtered.length>0&&filtered.every(item=>selectedIds.includes(item.id));
  const money=(value:number)=>value===0?"—":"৳"+new Intl.NumberFormat("en-BD",{maximumFractionDigits:0}).format(value);
  const statusTone=(value:RecommendationStatus)=>value==="Live"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Scheduled"?"bg-sky-50 text-sky-700 ring-sky-200":value==="Draft"?"bg-slate-100 text-slate-600 ring-slate-200":value==="Paused"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-rose-50 text-rose-700 ring-rose-200";
  const methodTone=(value:RecommendationMethod)=>value==="Manual"?"bg-[#edf3f4] text-[#3b646d]":value==="Rule-assisted"?"bg-violet-50 text-violet-700":"bg-amber-50 text-amber-700";
  const totalRevenue=sets.reduce((sum,item)=>sum+item.revenue,0);
  const averageCoverage=Math.round(sets.filter(item=>item.status!=="Archived").reduce((sum,item)=>sum+item.coverage,0)/sets.filter(item=>item.status!=="Archived").length);
  const blankSet:RecommendationSet={id:"REC-NEW",name:"",strategy:"Complete the routine",method:"Manual",source:"",sourceScope:"1 product",targets:[],surfaces:["Product page"],status:"Draft",priority:sets.length+1,coverage:100,orders:0,revenue:0,margin:30,stockSafe:true,fallback:"Best in-stock match",schedule:"Always on",updated:"Not saved"};
  const openEditor=(mode:"Create"|"Edit",item?:RecommendationSet)=>{setEditorMode(mode);setDraft(item?{...item,targets:[...item.targets],surfaces:[...item.surfaces]}:blankSet);setTargetInput("");setEditorOpen(true);setFocused(null)};
  const editorValid=Boolean(draft.name.trim()&&draft.source.trim()&&draft.sourceScope.trim()&&draft.targets.length&&draft.surfaces.length&&draft.fallback.trim()&&draft.schedule.trim());
  const addTarget=()=>{const value=targetInput.trim();if(!value||draft.targets.some(item=>item.toLowerCase()===value.toLowerCase()))return;setDraft(current=>({...current,targets:[...current.targets,value]}));setTargetInput("")};
  const saveRecommendationDraft=()=>{
    if(!editorValid){showNotice("Complete source, recommended products, surfaces, fallback and schedule.");return}
    const normalized:RecommendationSet={...draft,status:editorMode==="Create"||draft.method==="AI suggestion"?"Draft":draft.status,updated:"Draft changes"};
    setSets(current=>editorMode==="Create"?[{...normalized,id:"REC-"+String(109+current.length)},...current]:current.map(item=>item.id===draft.id?normalized:item));
    setEditorOpen(false);showNotice(draft.method==="AI suggestion"?"AI suggestion saved as an unapproved draft.":editorMode==="Create"?"Recommendation draft created. Review safety before publishing.":"Recommendation draft saved as a versioned change.");
  };
  const openImpact=(action:"Publish"|"Pause"|"Archive",ids:string[])=>{setPendingAction(action);setActionIds(ids);setActionReason("");setActionConfirmed(false);setImpactOpen(true);setFocused(null)};
  const impactTargets=sets.filter(item=>actionIds.includes(item.id));
  const publishBlockers=pendingAction==="Publish"?impactTargets.filter(item=>item.targets.length===0||item.surfaces.length===0||item.coverage<80||item.margin<25||!item.stockSafe||item.method==="AI suggestion"):[];
  const applyRecommendationImpact=()=>{
    if(!actionConfirmed||publishBlockers.length>0||(pendingAction!=="Publish"&&!actionReason.trim()))return;
    setSets(current=>current.map(item=>actionIds.includes(item.id)?{...item,status:pendingAction==="Publish"?(item.schedule==="Always on"?"Live":"Scheduled"):pendingAction==="Pause"?"Paused":"Archived",updated:"Just now"}:item));
    setSelectedIds([]);setImpactOpen(false);showNotice(actionIds.length+" recommendation set"+(actionIds.length===1?"":"s")+" updated with an audit event.");
  };

  return <div className="space-y-5">
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Merchandising intelligence</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Product Recommendations</h1><p className="mt-1.5 max-w-2xl text-[12.5px] leading-5 text-[#66736d]">Curate useful product pairings that improve routine quality and order value—without sacrificing stock or margin.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>showNotice("Recommendation export prepared with mappings and performance fields.")} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="download" size={13}/>Export</button><button onClick={()=>openEditor("Create")} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="plus" size={13}/>Create set</button></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Live sets",String(viewCounts.Live),"Across 4 selling surfaces","products"],["Catalog coverage",averageCoverage+"%","Eligible source coverage","reports"],["Revenue influenced",money(totalRevenue),"Attributed recommendation orders","finance"],["Needs review",String(viewCounts["Needs review"]),"Stock, margin or AI review","alert"]].map(([label,value,note,icon],index)=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-start justify-between"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#edf3f4] text-[#3b646d]"><Icon name={icon as IconName} size={15}/></span><span className={"rounded-full px-2 py-1 text-[7px] font-bold "+(index===3?"bg-amber-50 text-amber-700":"bg-emerald-50 text-emerald-700")}>{index===3?"Review":"Healthy"}</span></div><b className="mt-4 block text-[22px] tracking-[-.03em] text-[#23322b]">{value}</b><span className="mt-1 block text-[9px] font-bold text-[#65736c]">{label}</span><small className="mt-1 block text-[7.5px] text-[#929d97]">{note}</small></article>)}</section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Coverage gap</p><b className="mt-1 block text-[12px] text-[#33423b]">18 best sellers have no routine pairing</b></div><span className="rounded-full bg-amber-50 px-2 py-1 text-[7px] font-bold text-amber-700">Action</span></div><p className="mt-3 text-[7.5px] leading-4 text-[#87928d]">Start with high-traffic products where a genuinely useful next step exists.</p><button onClick={()=>setView("Needs review")} className="mt-3 text-[7.5px] font-bold text-[#3b646d]">Review gaps →</button></article><article className="rounded-2xl border border-rose-100 bg-rose-50/60 p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-rose-700">Stock &amp; margin safety</p><b className="mt-1 block text-[12px] text-rose-900">2 sets may degrade customer experience</b></div><Icon name="alert" size={15} className="text-rose-700"/></div><p className="mt-3 text-[7.5px] leading-4 text-rose-800">One set contains low-stock targets; another falls below the 25% margin floor.</p><button onClick={()=>setView("Needs review")} className="mt-3 text-[7.5px] font-bold text-rose-800">Open safety review →</button></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5d7775]">AI suggestion inbox</p><b className="mt-1 block text-[12px] text-[#304d4d]">1 unapproved suggestion</b></div><span className="rounded-full bg-white px-2 py-1 text-[7px] font-bold text-[#3b646d]">Human review</span></div><p className="mt-3 text-[7.5px] leading-4 text-[#647b77]">AI may propose candidates and explain evidence; it never publishes or changes merchandising autonomously.</p><button onClick={()=>setView("AI suggestions")} className="mt-3 text-[7.5px] font-bold text-[#3b646d]">Review suggestion →</button></article></section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{views.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold transition "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d] hover:text-[#53645d]")}>{item}<span className={"ml-2 rounded-full px-1.5 py-0.5 text-[7px] "+(view===item?"bg-[#edf3f4]":"bg-[#f2f4f3]")}>{viewCounts[item]}</span></button>)}</div></div><div className="space-y-3 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:p-5"><div className="flex flex-col gap-2 xl:flex-row"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search set, source or recommended product..." className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><select value={strategy} onChange={event=>setStrategy(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All strategies</option>{["Complete the routine","Frequently bought together","Similar alternative","Upgrade","Best sellers","New arrivals"].map(item=><option key={item}>{item}</option>)}</select><select value={method} onChange={event=>setMethod(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All methods</option><option>Manual</option><option>Rule-assisted</option><option>AI suggestion</option></select><select value={surface} onChange={event=>setSurface(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>All surfaces</option>{["Product page","Cart","Homepage","Search no-result"].map(item=><option key={item}>{item}</option>)}</select><select value={sort} onChange={event=>setSort(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>Priority</option><option>Highest revenue</option><option>Lowest coverage</option><option>Recently updated</option></select></div></div>

      {selectedIds.length>0&&<div className="flex flex-col gap-3 border-b border-[#d8e4e0] bg-[#edf3f4] px-4 py-3 sm:flex-row sm:items-center sm:px-5"><div className="flex min-w-0 flex-1 items-center gap-2"><span className="flex h-7 min-w-7 items-center justify-center rounded-lg bg-[#3b646d] px-2 text-[8px] font-bold text-white">{selectedIds.length}</span><b className="text-[8.5px] text-[#405b58]">recommendation sets selected</b></div><div className="flex flex-wrap gap-2"><button onClick={()=>openImpact("Publish",selectedIds)} className="h-8 rounded-lg border border-[#c7d8d3] bg-white px-3 text-[8px] font-bold text-[#416764]">Publish</button><button onClick={()=>openImpact("Pause",selectedIds)} className="h-8 rounded-lg border border-amber-200 bg-white px-3 text-[8px] font-bold text-amber-700">Pause</button><button onClick={()=>setSelectedIds([])} className="flex h-8 w-8 items-center justify-center rounded-lg text-[#708079]"><Icon name="close" size={12}/></button></div></div>}

      <div className="overflow-x-auto"><table className="w-full min-w-[1320px] text-left"><thead className="bg-[#fafbfa] text-[7px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="w-12 px-5 py-3.5"><input type="checkbox" aria-label="Select all visible recommendation sets" checked={allVisibleSelected} onChange={event=>setSelectedIds(current=>event.target.checked?Array.from(new Set([...current,...filtered.map(item=>item.id)])):current.filter(id=>!filtered.some(item=>item.id===id)))} className="h-3.5 w-3.5 accent-[#3b646d]"/></th><th className="px-2 py-3.5">Recommendation set</th><th className="px-4 py-3.5">Source</th><th className="px-4 py-3.5">Recommended products</th><th className="px-4 py-3.5">Surfaces &amp; method</th><th className="px-4 py-3.5">Coverage</th><th className="px-4 py-3.5">Performance</th><th className="px-4 py-3.5">Safety</th><th className="px-4 py-3.5">Status</th><th className="w-12 px-4 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{filtered.map(item=><tr key={item.id} className="text-[8.5px] text-[#5f6e67] hover:bg-[#fafcfb]"><td className="px-5 py-4"><input type="checkbox" aria-label={"Select "+item.name} checked={selectedIds.includes(item.id)} onChange={event=>setSelectedIds(current=>event.target.checked?[...current,item.id]:current.filter(id=>id!==item.id))} className="h-3.5 w-3.5 accent-[#3b646d]"/></td><td className="px-2 py-4"><button onClick={()=>setFocused(item)} className="min-w-[210px] text-left"><b className="block max-w-[210px] truncate text-[9px] text-[#33423b]">{item.name}</b><span className="mt-1 block text-[6.5px] font-bold text-[#3b646d]">{item.strategy}</span><small className="mt-1 block font-mono text-[6.5px] text-[#929d97]">{item.id} · priority {item.priority}</small></button></td><td className="max-w-[190px] px-4 py-4"><b className="block truncate text-[8px] text-[#52615a]">{item.source}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">{item.sourceScope}</span></td><td className="max-w-[240px] px-4 py-4"><div className="flex flex-wrap gap-1">{item.targets.slice(0,2).map(target=><span key={target} className="max-w-[130px] truncate rounded-md bg-[#f1f4f2] px-2 py-1 text-[6.5px] font-bold text-[#65736c]">{target}</span>)}{item.targets.length>2&&<span className="rounded-md bg-[#edf3f4] px-2 py-1 text-[6.5px] font-bold text-[#3b646d]">+{item.targets.length-2}</span>}</div><small className="mt-1.5 block text-[6.5px] text-[#929d97]">Fallback: {item.fallback}</small></td><td className="px-4 py-4"><div className="flex flex-wrap gap-1">{item.surfaces.map(place=><span key={place} className="rounded-md border border-[#e2e8e5] px-2 py-1 text-[6.5px] font-bold text-[#65736c]">{place}</span>)}</div><span className={"mt-1.5 inline-flex rounded-full px-2 py-1 text-[6.5px] font-bold "+methodTone(item.method)}>{item.method}</span></td><td className="min-w-[130px] px-4 py-4"><div className="flex items-center justify-between"><b className={"text-[9px] "+(item.coverage<80?"text-amber-700":"text-[#405049]")}>{item.coverage}%</b><span className="text-[6.5px] text-[#929d97]">eligible</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#edf1ef]"><div className={"h-full rounded-full "+(item.coverage<80?"bg-amber-500":"bg-[#5f8585]")} style={{width:item.coverage+"%"}}/></div></td><td className="px-4 py-4"><b className="block text-[8px] text-[#405049]">{money(item.revenue)}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">{item.orders} attributed orders</span></td><td className="px-4 py-4"><div className="flex items-center gap-1.5"><span className={"flex h-5 w-5 items-center justify-center rounded-full "+(item.stockSafe?"bg-emerald-50 text-emerald-700":"bg-rose-50 text-rose-700")}><Icon name={item.stockSafe?"check":"alert"} size={9}/></span><b className={"text-[7px] "+(item.margin<25?"text-rose-700":"text-[#52615a]")}>{item.margin}% margin</b></div><small className="mt-1.5 block text-[6.5px] text-[#929d97]">{item.stockSafe?"Stock protected":"Stock fallback needed"}</small></td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[7px] font-bold ring-1 ring-inset "+statusTone(item.status)}>{item.status}</span><small className="mt-1.5 block text-[6.5px] text-[#929d97]">{item.schedule}</small></td><td className="px-4 py-4"><button onClick={()=>setFocused(item)} aria-label={"Open "+item.name} className="flex h-8 w-8 items-center justify-center rounded-lg text-[#84908a] hover:bg-[#edf3f4] hover:text-[#3b646d]"><Icon name="chevron" size={13}/></button></td></tr>)}</tbody></table>{filtered.length===0&&<div className="flex flex-col items-center justify-center px-5 py-16 text-center"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#edf3f4] text-[#3b646d]"><Icon name="search" size={18}/></span><b className="mt-3 text-[10px] text-[#405049]">No recommendation sets match</b><p className="mt-1 text-[8px] text-[#929d97]">Clear filters or choose another view.</p><button onClick={()=>{setQuery("");setStrategy("All strategies");setMethod("All methods");setSurface("All surfaces");setView("All sets")}} className="mt-4 rounded-lg border border-[#dce4e0] px-3 py-2 text-[8px] font-bold text-[#3b646d]">Clear filters</button></div>}</div>
    </section>

    <section className="grid gap-3 lg:grid-cols-2"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Recommendation principle</p><b className="mt-1 block text-[12px] text-[#33423b]">Usefulness before revenue</b><p className="mt-3 text-[7.5px] leading-4 text-[#87928d]">A recommendation must make the routine clearer or provide a valid alternative. High-margin but irrelevant products should never win placement.</p></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5d7775]">Storefront boundary</p><b className="mt-1 block text-[12px] text-[#304d4d]">Mappings here. Visual layout in CMS and product templates.</b><p className="mt-3 text-[7.5px] leading-4 text-[#647b77]">Homepage CMS controls section position; product templates control presentation. This module owns candidates, order, fallback and publication state.</p><button onClick={()=>onNavigate("Homepage CMS")} className="mt-3 text-[7.5px] font-bold text-[#3b646d]">Open Homepage CMS →</button></article></section>

    {focused&&<div className="fixed inset-0 z-[80] bg-[#17231f]/25 backdrop-blur-[1px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-md overflow-y-auto bg-white shadow-[-24px_0_70px_rgba(18,37,31,.16)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Recommendation inspector</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">{focused.name}</h2><p className="mt-1 font-mono text-[7px] text-[#87928d]">{focused.id} · priority {focused.priority}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="flex flex-wrap gap-2"><span className={"inline-flex rounded-full px-2.5 py-1 text-[7.5px] font-bold ring-1 ring-inset "+statusTone(focused.status)}>{focused.status}</span><span className={"rounded-full px-2.5 py-1 text-[7.5px] font-bold "+methodTone(focused.method)}>{focused.method}</span><span className="rounded-full bg-[#f1f4f2] px-2.5 py-1 text-[7.5px] font-bold text-[#65736c]">{focused.strategy}</span></div><div className="rounded-xl border border-[#e2e8e5] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Source context</p><b className="mt-2 block text-[10px] text-[#405049]">{focused.source}</b><span className="mt-1 block text-[7px] text-[#929d97]">{focused.sourceScope}</span></div><div className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Ranked candidates</p><span className="text-[7px] font-bold text-[#3b646d]">{focused.targets.length} products</span></div><div className="mt-3 space-y-2">{focused.targets.map((target,index)=><div key={target} className="flex items-center gap-3 rounded-lg bg-[#fafbfa] p-3"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[#edf3f4] text-[7px] font-bold text-[#3b646d]">{index+1}</span><b className="min-w-0 flex-1 truncate text-[8px] text-[#52615a]">{target}</b><span className="text-[6.5px] text-[#929d97]">In stock</span></div>)}</div></div><div className="grid grid-cols-2 gap-3">{[["Coverage",focused.coverage+"%"],["Margin",focused.margin+"%"],["Orders",String(focused.orders)],["Revenue",money(focused.revenue)]].map(([label,value])=><div key={label} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6.5px] font-bold uppercase tracking-[.08em] text-[#929d97]">{label}</span><b className="mt-1 block text-[9px] text-[#405049]">{value}</b></div>)}</div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Fallback behavior</b><p className="mt-2 text-[7.5px] leading-4 text-[#70837f]">{focused.fallback}. Production must re-check stock and publication status at request time.</p></div>{focused.method==="AI suggestion"&&<div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><div className="flex items-center gap-2 text-amber-800"><Icon name="alert" size={12}/><b className="text-[8.5px]">AI suggestion—not an approved rule</b></div><p className="mt-2 text-[7.5px] leading-4 text-amber-700">Evidence, relevance, safety, margin and inventory must be reviewed by a person before publication.</p></div>}</div><footer className="sticky bottom-0 flex gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur"><button onClick={()=>openEditor("Edit",focused)} className="flex h-10 flex-1 items-center justify-center gap-2 rounded-xl border border-[#dce4e0] text-[8.5px] font-bold text-[#596962]"><Icon name="edit" size={12}/>Edit set</button><button onClick={()=>openImpact(focused.status==="Live"?"Pause":"Publish",[focused.id])} className="flex h-10 flex-1 items-center justify-center gap-2 rounded-xl bg-[#3b646d] text-[8.5px] font-bold text-white"><Icon name="check" size={12}/>{focused.status==="Live"?"Pause set":"Publish set"}</button></footer></aside></div>}

    {editorOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-3 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setEditorOpen(false)}}><section className="max-h-[94vh] w-full max-w-5xl overflow-y-auto rounded-2xl bg-white shadow-[0_30px_90px_rgba(17,35,30,.25)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Versioned recommendation builder</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">{editorMode} recommendation set</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Curate relevance, ranking and fallback first; publication remains a separate approval.</p></div><button onClick={()=>setEditorOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="grid gap-5 p-5 lg:grid-cols-[minmax(0,1fr)_290px]"><div className="space-y-4"><div className="rounded-2xl border border-[#e2e8e5] p-4"><div className="mb-4"><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Set identity</p><b className="mt-1 block text-[11px] text-[#405049]">Purpose and recommendation method</b></div><div className="grid gap-3 sm:grid-cols-2"><label className="block space-y-1.5 sm:col-span-2"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Internal set name *</span><input value={draft.name} onChange={event=>setDraft(current=>({...current,name:event.target.value}))} placeholder="e.g. Barrier Repair Routine" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Strategy *</span><select value={draft.strategy} onChange={event=>setDraft(current=>({...current,strategy:event.target.value as RecommendationStrategy}))} className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none">{["Complete the routine","Frequently bought together","Similar alternative","Upgrade","Best sellers","New arrivals"].map(item=><option key={item}>{item}</option>)}</select></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Method *</span><select value={draft.method} onChange={event=>setDraft(current=>({...current,method:event.target.value as RecommendationMethod}))} className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>Manual</option><option>Rule-assisted</option><option>AI suggestion</option></select></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Priority</span><input type="number" min="1" value={draft.priority} onChange={event=>setDraft(current=>({...current,priority:Number(event.target.value)}))} className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Schedule *</span><input value={draft.schedule} onChange={event=>setDraft(current=>({...current,schedule:event.target.value}))} placeholder="Always on or 25 Aug · 10:00 AM" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none"/></label></div></div><div className="rounded-2xl border border-[#e2e8e5] p-4"><div className="mb-4"><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Source context</p><b className="mt-1 block text-[11px] text-[#405049]">Where the recommendation begins</b></div><div className="grid gap-3 sm:grid-cols-2"><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Source product / rule *</span><input value={draft.source} onChange={event=>setDraft(current=>({...current,source:event.target.value}))} placeholder="Product, category or cart segment" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none"/></label><label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Source scope *</span><input value={draft.sourceScope} onChange={event=>setDraft(current=>({...current,sourceScope:event.target.value}))} placeholder="1 product or 12 eligible products" className="h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none"/></label></div></div><div className="rounded-2xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Ranked products *</p><b className="mt-1 block text-[11px] text-[#405049]">Position reflects recommendation order</b></div><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">{draft.targets.length} selected</span></div><div className="mt-4 space-y-2">{draft.targets.map((target,index)=><div key={target} className="flex items-center gap-3 rounded-xl border border-[#e8ecea] bg-[#fafbfa] p-3"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-white text-[7px] font-bold text-[#3b646d] ring-1 ring-[#e2e8e5]">{index+1}</span><b className="min-w-0 flex-1 truncate text-[8px] text-[#52615a]">{target}</b><button onClick={()=>setDraft(current=>({...current,targets:current.targets.filter(item=>item!==target)}))} className="flex h-7 w-7 items-center justify-center rounded-lg text-[#87928d] hover:bg-rose-50 hover:text-rose-700"><Icon name="close" size={10}/></button></div>)}</div><div className="mt-3 flex gap-2"><input value={targetInput} onChange={event=>setTargetInput(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"){event.preventDefault();addTarget()}}} placeholder="Search or enter a product name" className="h-10 min-w-0 flex-1 rounded-xl border border-[#dce4e0] px-3 text-[9px] outline-none focus:border-[#9eb7b4]"/><button onClick={addTarget} className="flex h-10 items-center gap-2 rounded-xl border border-[#cddbd7] px-3 text-[8px] font-bold text-[#3b646d]"><Icon name="plus" size={11}/>Add</button></div><small className="mt-2 block text-[6.5px] text-[#929d97]">Production uses the existing product selector and stores stable product IDs—not display names.</small></div><div className="rounded-2xl border border-[#e2e8e5] p-4"><div className="mb-4"><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Placement &amp; fallback</p><b className="mt-1 block text-[11px] text-[#405049]">Where it appears and what happens when stock changes</b></div><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Selling surfaces *</span><div className="mt-2 flex flex-wrap gap-2">{["Product page","Cart","Homepage","Search no-result"].map(item=><label key={item} className={"flex cursor-pointer items-center gap-2 rounded-lg border px-3 py-2 text-[7.5px] font-bold "+(draft.surfaces.includes(item)?"border-[#9fb8b5] bg-[#edf3f4] text-[#3b646d]":"border-[#dce4e0] text-[#718079]")}><input type="checkbox" checked={draft.surfaces.includes(item)} onChange={event=>setDraft(current=>({...current,surfaces:event.target.checked?[...current.surfaces,item]:current.surfaces.filter(place=>place!==item)}))} className="h-3.5 w-3.5 accent-[#3b646d]"/>{item}</label>)}</div><label className="mt-4 block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">Out-of-stock fallback *</span><select value={draft.fallback} onChange={event=>setDraft(current=>({...current,fallback:event.target.value}))} className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8.5px] font-bold text-[#58675f] outline-none"><option>Best in-stock match</option><option>Next ranked product</option><option>Hide unavailable item</option><option>Hide block</option><option>Keep current cart</option></select></label></div></div><aside className="space-y-3"><div className="rounded-2xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5d7775]">Safety guardrails</p><div className="mt-3 grid grid-cols-2 gap-2"><label className="block space-y-1.5"><span className="text-[6.5px] font-bold text-[#70837f]">Coverage %</span><input type="number" min="0" max="100" value={draft.coverage} onChange={event=>setDraft(current=>({...current,coverage:Number(event.target.value)}))} className="h-9 w-full rounded-lg border border-[#cfded9] bg-white px-3 text-[8.5px] font-bold outline-none"/></label><label className="block space-y-1.5"><span className="text-[6.5px] font-bold text-[#70837f]">Projected margin %</span><input type="number" min="0" max="100" value={draft.margin} onChange={event=>setDraft(current=>({...current,margin:Number(event.target.value)}))} className="h-9 w-full rounded-lg border border-[#cfded9] bg-white px-3 text-[8.5px] font-bold outline-none"/></label></div><label className="mt-3 flex cursor-pointer items-start justify-between gap-3 rounded-xl bg-white p-3"><span><b className="block text-[7.5px] text-[#405b58]">Stock-safe candidates</b><small className="mt-1 block text-[6.5px] text-[#87928d]">All products have a valid fallback.</small></span><input type="checkbox" checked={draft.stockSafe} onChange={event=>setDraft(current=>({...current,stockSafe:event.target.checked}))} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/></label><div className={"mt-3 rounded-xl p-3 "+(draft.coverage<80||draft.margin<25||!draft.stockSafe?"bg-rose-50 text-rose-800":"bg-white text-emerald-800")}><b className="block text-[8px]">{draft.coverage<80||draft.margin<25||!draft.stockSafe?"Publication review required":"Guardrails satisfied"}</b><p className="mt-1 text-[6.5px] leading-4">Minimums: 80% coverage, 25% projected margin and stock-safe fallback.</p></div><p className="mt-3 text-[6.5px] leading-4 text-[#70837f]">Requires backend: compute availability and contribution margin from live product, inventory and finance data.</p></div>{draft.method==="AI suggestion"&&<div className="rounded-2xl border border-amber-200 bg-amber-50 p-4"><div className="flex items-center gap-2 text-amber-800"><Icon name="alert" size={12}/><b className="text-[8px]">AI review boundary</b></div><p className="mt-2 text-[7px] leading-4 text-amber-700">AI may propose candidates, ranking and reasons. Convert the method to Manual or Rule-assisted after human review before publication.</p><small className="mt-2 block text-[6.5px] font-semibold text-amber-800">AI suggestions always save as draft</small></div>}<div className="rounded-2xl border border-[#e2e8e5] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Publication readiness</p><div className="mt-3 space-y-2">{[["Source defined",Boolean(draft.source.trim())],["Candidate selected",draft.targets.length>0],["Surface selected",draft.surfaces.length>0],["Coverage ≥ 80%",draft.coverage>=80],["Margin ≥ 25%",draft.margin>=25],["Stock fallback safe",draft.stockSafe],["Human-owned rule",draft.method!=="AI suggestion"]].map(([label,valid])=><div key={String(label)} className="flex items-center justify-between gap-3 text-[7.5px]"><span className="text-[#718079]">{label as string}</span><span className={"flex h-5 w-5 items-center justify-center rounded-full "+(valid?"bg-emerald-50 text-emerald-700":"bg-rose-50 text-rose-700")}><Icon name={valid?"check":"close"} size={9}/></span></div>)}</div></div><div className="rounded-2xl border border-[#e2e8e5] p-4 text-[7px] leading-4 text-[#718079]"><b className="block text-[8px] text-[#405049]">Versioned change</b><p className="mt-2">Saving creates a recoverable draft with source, targets, ranking, surfaces and fallback. No storefront changes occur yet.</p></div></aside></div><footer className="sticky bottom-0 flex flex-col-reverse gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur sm:flex-row sm:justify-end"><button onClick={()=>setEditorOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8.5px] font-bold text-[#65736c]">Cancel</button><button onClick={saveRecommendationDraft} disabled={!editorValid} className="flex h-10 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-5 text-[8.5px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40"><Icon name="check" size={12}/>Save recommendation draft</button></footer></section></div>}

    {impactOpen&&<div className="fixed inset-0 z-[95] flex items-center justify-center bg-[#17231f]/35 p-3 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setImpactOpen(false)}}><section className="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white shadow-[0_30px_90px_rgba(17,35,30,.25)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Human approval required</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Manage recommendation status</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Review relevance, inventory, margin and customer-facing impact.</p></div><button onClick={()=>setImpactOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid grid-cols-3 gap-2">{(["Publish","Pause","Archive"] as const).map(action=><button key={action} onClick={()=>setPendingAction(action)} className={"rounded-xl border px-2 py-2.5 text-[7.5px] font-bold "+(pendingAction===action?"border-[#3b646d] bg-[#edf3f4] text-[#3b646d]":"border-[#e2e8e5] text-[#718079]")}>{action}</button>)}</div><div className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between"><b className="text-[8.5px] text-[#405049]">Selected sets</b><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">{impactTargets.length}</span></div><div className="mt-3 divide-y divide-[#edf0ee]">{impactTargets.map(item=><div key={item.id} className="flex items-center justify-between gap-3 py-2.5"><div><b className="block text-[8px] text-[#405049]">{item.name}</b><span className="mt-0.5 block text-[6.5px] text-[#929d97]">{item.targets.length} products · {item.surfaces.join(", ")}</span></div><span className={"text-[7px] font-bold "+(needsReview(item)?"text-rose-700":"text-emerald-700")}>{item.coverage}% coverage</span></div>)}</div></div><div className={"rounded-xl border p-4 "+(pendingAction==="Publish"?"border-emerald-200 bg-emerald-50":pendingAction==="Pause"?"border-amber-200 bg-amber-50":"border-rose-200 bg-rose-50")}><b className="text-[8.5px] text-[#405049]">{pendingAction==="Publish"?"Valid sets become live now or scheduled for the configured start.":pendingAction==="Pause"?"Customer-facing placements stop; mappings and performance history remain.":"The set leaves active merchandising while historical attribution remains."}</b><p className="mt-2 text-[7.5px] leading-4 text-[#65736c]">This is never performed automatically by an AI suggestion or background workflow.</p></div>{publishBlockers.length>0&&<div className="rounded-xl border border-rose-200 bg-rose-50 p-4"><div className="flex items-center gap-2 text-rose-800"><Icon name="alert" size={12}/><b className="text-[8.5px]">Publication blocked</b></div><div className="mt-3 space-y-2">{publishBlockers.map(item=><p key={item.id} className="text-[7.5px] leading-4 text-rose-700"><b>{item.name}:</b> {item.method==="AI suggestion"?"requires human conversion to a manual or approved rule":!item.stockSafe?"requires a stock-safe fallback":item.margin<25?"projected margin is below 25%":item.coverage<80?"coverage is below 80%":"complete candidates and placement"}.</p>)}</div></div>}<label className="block space-y-1.5"><span className="text-[7px] font-bold uppercase tracking-[.1em] text-[#738079]">{pendingAction==="Publish"?"Release note (optional)":"Audit reason *"}</span><textarea rows={3} value={actionReason} onChange={event=>setActionReason(event.target.value)} placeholder={pendingAction==="Publish"?"What was reviewed before release?":"Required reason for the audit log"} className="w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[9px] leading-5 outline-none focus:border-[#9eb7b4]"/></label><label className="flex cursor-pointer items-start gap-3 rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><input type="checkbox" checked={actionConfirmed} onChange={event=>setActionConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 shrink-0 accent-[#3b646d]"/><span><b className="block text-[8.5px] text-[#405b58]">I reviewed relevance, ranking, stock, margin and placements</b><small className="mt-1 block text-[7px] leading-4 text-[#70837f]">The audit trail records actor, reason, source, candidates, order and before/after status. Previous versions remain recoverable.</small></span></label></div><footer className="flex flex-col-reverse gap-2 border-t border-[#e8ecea] p-4 sm:flex-row sm:justify-end"><button onClick={()=>setImpactOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8.5px] font-bold text-[#65736c]">Cancel</button><button onClick={applyRecommendationImpact} disabled={!actionConfirmed||publishBlockers.length>0||(pendingAction!=="Publish"&&!actionReason.trim())} className={"flex h-10 items-center justify-center gap-2 rounded-xl px-5 text-[8.5px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40 "+(pendingAction==="Archive"?"bg-rose-700":pendingAction==="Pause"?"bg-amber-600":"bg-[#3b646d]")}><Icon name="check" size={12}/>{publishBlockers.length?"Resolve blockers":pendingAction+" selected"}</button></footer></section></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

type InventoryHealth="Healthy"|"Low stock"|"Out of stock"|"Overstock"|"Expiry risk";
