function TrackingAttributionWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [range,setRange]=useState<"24H"|"7D"|"30D">("7D");
  const [environment,setEnvironment]=useState("Production");
  const [view,setView]=useState<TrackingView>("Events");
  const [query,setQuery]=useState("");
  const [status,setStatus]=useState("All statuses");
  const [attributionModel,setAttributionModel]=useState("Last non-direct");
  const [focused,setFocused]=useState<TrackingEventRow|null>(null);
  const [notice,setNotice]=useState("");
  const [testOpen,setTestOpen]=useState(false);
  const [testEvent,setTestEvent]=useState("purchase");
  const [testEnvironment,setTestEnvironment]=useState<"Staging"|"Production">("Staging");
  const [testDestination,setTestDestination]=useState("GA4 + Meta");
  const [testUrl,setTestUrl]=useState("https://staging.brandnbeauty.com/checkout/success");
  const [testReference,setTestReference]=useState("TEST-BNB-2048");
  const [testCode,setTestCode]=useState("");
  const [testConfirmed,setTestConfirmed]=useState(false);
  const [testStage,setTestStage]=useState<"Setup"|"Result">("Setup");
  const [remediationOpen,setRemediationOpen]=useState(false);
  const [remediationEvent,setRemediationEvent]=useState("purchase");
  const [remediationOwner,setRemediationOwner]=useState("Engineering · Tracking");
  const [remediationSeverity,setRemediationSeverity]=useState("High");
  const [remediationDue,setRemediationDue]=useState("2026-08-25");
  const [remediationNote,setRemediationNote]=useState("");
  const [remediationConfirmed,setRemediationConfirmed]=useState(false);
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const openTestSession=(item?:TrackingEventRow)=>{setTestEvent(item?.name||"purchase");setTestEnvironment("Staging");setTestDestination("GA4 + Meta");setTestUrl("https://staging.brandnbeauty.com/checkout/success");setTestReference("TEST-BNB-2048");setTestCode("");setTestConfirmed(false);setTestStage("Setup");setTestOpen(true)};
  const openRemediation=(item?:TrackingEventRow)=>{setRemediationEvent(item?.name||"purchase");setRemediationSeverity(item?.status==="Warning"?"High":"Medium");setRemediationNote(item?.issue||"");setRemediationConfirmed(false);setRemediationOpen(true)};
  const handleTrackingActionCapture=(event:React.MouseEvent<HTMLDivElement>)=>{const button=(event.target as HTMLElement).closest("button");const label=button?.textContent?.trim();if(!button||!label)return;if(label==="Test events"){event.stopPropagation();openTestSession();}else if(label==="Open test session"){event.stopPropagation();openTestSession(focused||undefined);}else if(label==="Create remediation task"){event.stopPropagation();setTestOpen(false);openRemediation(focused||trackingEvents.find(item=>item.name===testEvent)||trackingEvents.find(item=>item.status==="Warning"));}else if(label.startsWith("Review mapping")){event.stopPropagation();openRemediation(trackingEvents.find(item=>item.name==="qualified_message"));}};
  const money=(value:number)=>"৳"+new Intl.NumberFormat("en-BD",{maximumFractionDigits:0}).format(value);
  const visibleEvents=trackingEvents.filter(item=>(status==="All statuses"||item.status===status)&&(item.name+" "+item.businessStep+" "+item.issue).toLowerCase().includes(query.toLowerCase()));
  const connectorCards=[
    {name:"Google Tag Manager",id:"GTM-BNB2026",status:"Healthy" as TrackingStatus,meta:"Web container · published 18 Aug",detail:"31 tags · 12 triggers · no unpublished workspace changes",score:100},
    {name:"Google Analytics 4",id:"G-BNB8K2",status:"Healthy" as TrackingStatus,meta:"Web stream · BrandnBeauty",detail:"Realtime active · ecommerce schema coverage 98.7%",score:99},
    {name:"Meta Pixel",id:"PX-728441",status:"Warning" as TrackingStatus,meta:"Browser events · active",detail:"Purchase deduplication needs review · match quality 72–92%",score:92},
    {name:"Conversions API",id:"CAPI-BNB-PROD",status:"Warning" as TrackingStatus,meta:"Server gateway · active",detail:"Purchase + delivery feedback · 4.8% duplicate risk",score:95},
  ];
  const statusTone=(value:TrackingStatus)=>value==="Healthy"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Warning"?"bg-amber-50 text-amber-700 ring-amber-200":value==="Error"?"bg-rose-50 text-rose-700 ring-rose-200":"bg-slate-100 text-slate-600 ring-slate-200";
  const journey=[{name:"page_view",coverage:99.9,count:18420},{name:"view_item",coverage:99.7,count:6480},{name:"add_to_cart",coverage:99.2,count:1420},{name:"begin_checkout",coverage:99.1,count:826},{name:"purchase",coverage:95.2,count:538},{name:"order_delivered",coverage:98.2,count:455}];
  const browserSeries=[34,42,38,51,47,58,54,63,61,69,74,82],serverSeries=[8,11,10,14,13,16,15,19,18,21,23,26],maxSeries=82;
  const views:TrackingView[]=["Events","Sources & channels","UTM coverage"];
  const totalAttributed=attributionRows.filter(item=>item.source!=="Unattributed").reduce((sum,item)=>sum+item.delivered,0),totalDelivered=attributionRows.reduce((sum,item)=>sum+item.delivered,0),unattributed=attributionRows.find(item=>item.source==="Unattributed")?.delivered||0;

  return <div className="space-y-5" onClickCapture={handleTrackingActionCapture}>
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Measurement integrity</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Tracking &amp; Attribution</h1><p className="mt-1.5 max-w-2xl text-[12.5px] leading-5 text-[#66736d]">Verify every ecommerce signal from browser to backend, prevent duplicates and connect marketing credit to real delivered orders.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>onNavigate("Settings")} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="settings" size={13}/>Connections</button><button onClick={()=>showNotice("Diagnostic event tester opens from the final safe control layer.")} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="refresh" size={13}/>Test events</button></div></section>

    <section className="rounded-2xl border border-[#dfe7e4] bg-white p-3"><div className="flex flex-col gap-3 xl:flex-row xl:items-center"><div className="flex gap-1">{(["24H","7D","30D"] as const).map(item=><button key={item} onClick={()=>setRange(item)} className={"h-8 min-w-12 rounded-lg px-3 text-[8px] font-bold "+(range===item?"bg-[#3b646d] text-white":"text-[#7a8881] hover:bg-[#f2f5f3]")}>{item}</button>)}</div><select value={environment} onChange={event=>setEnvironment(event.target.value)} className="h-9 rounded-lg border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f] outline-none"><option>Production</option><option>Staging</option></select><div className="h-px flex-1 bg-[#edf0ee] xl:h-6 xl:w-px xl:flex-none"/><select value={attributionModel} onChange={event=>setAttributionModel(event.target.value)} className="h-9 rounded-lg border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f] outline-none"><option>Last non-direct</option><option>First touch</option><option>Last touch</option><option>Platform reported</option></select><div className="ml-auto flex items-center gap-2 rounded-lg bg-[#f6f8f7] px-3 py-2 text-[7px] text-[#718079]"><span className="h-2 w-2 rounded-full bg-emerald-500"/><span>Last event 12 sec ago</span><b className="text-amber-700">2 warnings</b></div></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{connectorCards.map(item=><article key={item.name} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-start justify-between"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#edf3f4] text-[10px] font-black text-[#3b646d]">{item.name.split(" ").map(word=>word[0]).join("").slice(0,3)}</span><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+statusTone(item.status)}>{item.status}</span></div><b className="mt-4 block text-[9px] text-[#405049]">{item.name}</b><span className="mt-1 block font-mono text-[6.5px] text-[#929d97]">{item.id}</span><p className="mt-3 text-[7px] text-[#65736c]">{item.meta}</p><p className="mt-1 text-[6.5px] leading-3.5 text-[#929d97]">{item.detail}</p><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[#edf1ef]"><div className={"h-full rounded-full "+(item.status==="Healthy"?"bg-emerald-500":"bg-amber-400")} style={{width:item.score+"%"}}/></div></article>)}</section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{[
      ["Tracked sessions","18,420","+14.6%","GA4 production sessions","text-[#405049]"],
      ["Ecommerce coverage","98.7%","+0.8 pts","Required schema fields present","text-emerald-700"],
      ["Purchase deduplication","95.2%","Review","Browser ↔ server event_id match","text-amber-700"],
      ["Delivered attribution",(totalAttributed/totalDelivered*100).toFixed(1)+"%","+2.1 pts",totalAttributed+" delivered orders attributed","text-[#3b646d]"],
      ["Unattributed delivered",String(unattributed),"−9",money(attributionRows.find(item=>item.source==="Unattributed")?.revenue||0)+" delivered revenue","text-amber-700"],
    ].map(([label,value,change,meta,tone])=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between"><span className="text-[6.5px] font-bold uppercase tracking-[.1em] text-[#89948f]">{label}</span><span className="text-[6px] font-bold text-emerald-700">{change}</span></div><b className={"mt-3 block text-[18px] tracking-[-.03em] "+tone}>{value}</b><p className="mt-2 text-[6.5px] leading-3.5 text-[#929d97]">{meta}</p></article>)}</section>

    <section className="grid gap-4 xl:grid-cols-[minmax(0,1.25fr)_minmax(380px,.75fr)]"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Event traffic</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Browser vs server event volume</h2><p className="mt-1 text-[7px] text-[#929d97]">{range} · {environment}</p></div><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">No outage</span></div><div className="mt-6 flex h-52 items-end gap-2 border-b border-[#dfe6e3] px-1 sm:gap-3">{browserSeries.map((value,index)=><div key={index} className="group flex h-full min-w-0 flex-1 items-end gap-[2px]"><div className="relative w-2/3 rounded-t bg-[#5f8585]" style={{height:Math.max(8,value/maxSeries*94)+"%"}}><span className="absolute -top-7 left-1/2 hidden -translate-x-1/2 rounded-md bg-[#223c3f] px-2 py-1 text-[6px] font-bold text-white group-hover:block">{value}k browser</span></div><div className="w-1/3 rounded-t bg-[#c6d4d1]" style={{height:Math.max(6,serverSeries[index]/maxSeries*94)+"%"}}/></div>)}</div><div className="mt-3 flex items-center justify-between text-[6.5px] font-bold text-[#718079]"><div className="flex gap-4"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-sm bg-[#5f8585]"/>Browser</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-sm bg-[#c6d4d1]"/>Server</span></div><span className="text-[#929d97]">No unexplained volume spike</span></div></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Commerce journey</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Required event coverage</h2></div><span className="rounded-full bg-emerald-50 px-2 py-1 text-[7px] font-bold text-emerald-700">98.7%</span></div><div className="mt-5 space-y-3">{journey.map((item,index)=><button key={item.name} onClick={()=>setFocused(trackingEvents.find(event=>event.name===item.name)||null)} className="grid w-full grid-cols-[22px_minmax(0,1fr)_60px] items-center gap-3 text-left"><span className={"flex h-6 w-6 items-center justify-center rounded-lg text-[6.5px] font-bold "+(item.coverage<97?"bg-amber-50 text-amber-700":"bg-[#edf3f4] text-[#3b646d]")}>{index+1}</span><div><div className="flex items-center justify-between"><b className="text-[7.5px] text-[#52615a]">{item.name}</b><span className="text-[6.5px] text-[#929d97]">{item.count}</span></div><div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[#edf1ef]"><div className={"h-full rounded-full "+(item.coverage<97?"bg-amber-400":"bg-[#5f8585]")} style={{width:item.coverage+"%"}}/></div></div><b className={"text-right text-[7.5px] "+(item.coverage<97?"text-amber-700":"text-emerald-700")}>{item.coverage}%</b></button>)}</div></article></section>

    <section className="grid gap-4 xl:grid-cols-[minmax(0,1.15fr)_minmax(360px,.85fr)]"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Integrity diagnostics</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Prioritized tracking issues</h2></div><span className="rounded-full bg-amber-50 px-2 py-1 text-[7px] font-bold text-amber-700">2 open</span></div><div className="mt-4 space-y-2">{[
      {event:"purchase",title:"Meta Purchase deduplication below guardrail",meta:"4.8% duplicate risk · inconsistent event_id reuse on server retry",tone:"border-rose-200 bg-rose-50"},
      {event:"qualified_message",title:"Messenger campaign identity missing",meta:"7 qualified leads cannot be connected to campaign/ad click identity",tone:"border-amber-200 bg-amber-50"},
      {event:"view_item",title:"Catalog item ID mapping healthy",meta:"Storefront SKU, GA4 item_id and Meta content_id agree",tone:"border-emerald-200 bg-emerald-50"},
      {event:"order_delivered",title:"Delivered feedback operating normally",meta:"Courier-delivered event reached GA4 and Meta server destinations",tone:"border-emerald-200 bg-emerald-50"},
    ].map(item=><button key={item.title} onClick={()=>setFocused(trackingEvents.find(event=>event.name===item.event)||null)} className={"w-full rounded-xl border p-3 text-left "+item.tone}><b className="block text-[8px] text-[#405049]">{item.title}</b><span className="mt-1 block text-[6.5px] leading-3.5 text-[#7b8982]">{item.meta}</span></button>)}</div></article><article className="rounded-2xl border border-[#d7e3e0] bg-[#edf3f4] p-4 sm:p-5"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5e7875]">Attribution confidence</p><h2 className="mt-1 text-[14px] font-bold text-[#304d4d]">Credit is useful only when identity is reliable</h2><div className="mt-4 space-y-3">{[["UTM coverage","94.6%"],["Click ID capture","91.8%"],["Order source mapping","97.1%"],["Delivered-order match","96.4%"]].map(item=><div key={item[0]}><div className="flex justify-between text-[7.5px]"><span className="text-[#647b77]">{item[0]}</span><b className="text-[#304d4d]">{item[1]}</b></div><div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-white"><div className="h-full rounded-full bg-[#5f8585]" style={{width:item[1]}}/></div></div>)}</div><p className="mt-4 border-t border-[#d5e1de] pt-4 text-[7px] leading-4 text-[#647b77]">Platform attribution remains diagnostic. Internal order, courier and finance records determine delivered revenue and profit.</p></article></section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{views.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d]")}>{item}</button>)}</div></div><div className="space-y-3 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:p-5"><div className="flex flex-col gap-2 xl:flex-row"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder={view==="Events"?"Search event, journey step or issue...":"Search source, campaign or UTM issue..."} className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label>{view==="Events"&&<select value={status} onChange={event=>setStatus(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f] outline-none"><option>All statuses</option><option>Healthy</option><option>Warning</option><option>Error</option></select>}</div></div><div className="p-0">{view==="Events"?<div className="overflow-x-auto"><table className="w-full min-w-[1250px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Event / business step</th><th className="px-4 py-3.5">Browser</th><th className="px-4 py-3.5">Server</th><th className="px-4 py-3.5">GA4</th><th className="px-4 py-3.5">Meta</th><th className="px-4 py-3.5">Deduplication</th><th className="px-4 py-3.5">Match quality</th><th className="px-4 py-3.5">Last seen</th><th className="px-4 py-3.5">Status</th><th className="w-12 px-4 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{visibleEvents.map(item=><tr key={item.name} onClick={()=>setFocused(item)} className="cursor-pointer text-[8px] text-[#5f6e67] hover:bg-[#fafcfb]"><td className="px-5 py-4"><b className="block font-mono text-[8.5px] text-[#33423b]">{item.name}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">{item.businessStep}</span></td><td className="px-4 py-4 font-bold text-[#52615a]">{item.browser.toLocaleString()}</td><td className="px-4 py-4 font-bold text-[#52615a]">{item.server?item.server.toLocaleString():"—"}</td><td className="px-4 py-4 text-[#65736c]">{item.ga4.toLocaleString()}</td><td className="px-4 py-4 text-[#65736c]">{item.meta.toLocaleString()}</td><td className={"px-4 py-4 font-bold "+(item.dedup<98?"text-amber-700":"text-emerald-700")}>{item.dedup}%</td><td className="px-4 py-4"><b className="text-[#405049]">{item.match}%</b><div className="mt-1.5 h-1 w-20 overflow-hidden rounded-full bg-[#edf1ef]"><div className="h-full rounded-full bg-[#5f8585]" style={{width:item.match+"%"}}/></div></td><td className="px-4 py-4 text-[#65736c]">{item.lastSeen}</td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+statusTone(item.status)}>{item.status}</span></td><td className="px-4 py-4"><Icon name="chevron" size={12}/></td></tr>)}</tbody></table></div>:view==="Sources & channels"?<div className="overflow-x-auto"><table className="w-full min-w-[1150px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Source / channel</th><th className="px-4 py-3.5">Sessions</th><th className="px-4 py-3.5">Orders</th><th className="px-4 py-3.5">Delivered</th><th className="px-4 py-3.5">Delivered revenue</th><th className="px-4 py-3.5">Contribution</th><th className="px-4 py-3.5">AOV</th><th className="px-4 py-3.5">Return rate</th><th className="px-4 py-3.5">UTM coverage</th><th className="px-4 py-3.5">Quality</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{attributionRows.filter(item=>item.source.toLowerCase().includes(query.toLowerCase())).map(item=><tr key={item.source} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4 font-bold text-[#405049]">{item.source}</td><td className="px-4 py-4">{item.sessions?item.sessions.toLocaleString():"—"}</td><td className="px-4 py-4">{item.orders}</td><td className="px-4 py-4 font-bold text-[#52615a]">{item.delivered}</td><td className="px-4 py-4 font-bold text-[#3b646d]">{money(item.revenue)}</td><td className="px-4 py-4 font-bold text-emerald-700">{money(item.contribution)}</td><td className="px-4 py-4">{money(item.aov)}</td><td className={"px-4 py-4 "+(item.returnRate>12?"font-bold text-rose-700":"text-[#65736c]")}>{item.returnRate}%</td><td className={"px-4 py-4 font-bold "+(item.utm<90?"text-amber-700":"text-emerald-700")}>{item.utm}%</td><td className="px-4 py-4"><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold "+(item.quality==="Review"?"bg-amber-50 text-amber-700":"bg-emerald-50 text-emerald-700")}>{item.quality}</span></td></tr>)}</tbody></table></div>:<div className="grid gap-4 p-4 sm:grid-cols-2 xl:grid-cols-4">{[
      ["Meta campaigns","96.4%","21 links missing utm_content","Warning"],["Google campaigns","98.8%","3 links missing campaign_id","Healthy"],["Influencer / partner","84.6%","5 partners using inconsistent source names","Warning"],["Messenger manual","72.2%","35 orders missing click/campaign identity","Warning"],
    ].filter(item=>item[0].toLowerCase().includes(query.toLowerCase())).map(item=><article key={item[0]} className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-start justify-between"><b className="text-[8.5px] text-[#405049]">{item[0]}</b><span className={"rounded-full px-2 py-1 text-[6px] font-bold "+(item[3]==="Healthy"?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700")}>{item[3]}</span></div><strong className="mt-4 block text-[18px] text-[#3b646d]">{item[1]}</strong><p className="mt-2 text-[7px] leading-4 text-[#87928d]">{item[2]}</p><button onClick={()=>showNotice("UTM mapping diagnostic opened for "+item[0]+".")} className="mt-3 text-[7px] font-bold text-[#3b646d]">Review mapping →</button></article>)}</div>}</div></section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Identity &amp; privacy</p><b className="mt-1.5 block text-[10px] text-[#405049]">No raw customer PII in analytics events</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">Only approved normalized and hashed user data may be sent server-side; access tokens and secrets never appear in the browser.</p></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Attribution boundary</p><b className="mt-1.5 block text-[10px] text-[#405049]">Credit model ≠ accounting truth</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">Attribution supports decisions; orders, courier delivery and Finance determine actual delivered revenue and profit.</p></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5e7875]">Change control</p><b className="mt-1.5 block text-[10px] text-[#304d4d]">Test → review diff → approve → deploy → verify</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">Tracking changes use staging validation, versioned configuration and production read-back. AI cannot publish GTM or change live tracking automatically.</p></article></section>

    {focused&&<div className="fixed inset-0 z-[80] bg-[#17231f]/25 backdrop-blur-[1px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-xl overflow-y-auto bg-white shadow-[-24px_0_70px_rgba(18,37,31,.16)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Event inspector</p><h2 className="mt-1.5 font-mono text-[17px] font-bold text-[#23322b]">{focused.name}</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused.businessStep} · last seen {focused.lastSeen}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="flex gap-2"><span className={"inline-flex rounded-full px-2.5 py-1 text-[7px] font-bold ring-1 ring-inset "+statusTone(focused.status)}>{focused.status}</span><span className="rounded-full bg-[#edf3f4] px-2.5 py-1 text-[7px] font-bold text-[#3b646d]">{focused.dedup}% dedup</span><span className="rounded-full bg-[#f2f4f3] px-2.5 py-1 text-[7px] font-bold text-[#65736c]">{focused.match}% match</span></div><div className="grid grid-cols-4 overflow-hidden rounded-xl border border-[#e2e8e5] text-center"><div className="p-3"><span className="text-[6px] text-[#929d97]">Browser</span><b className="mt-1 block text-[10px] text-[#405049]">{focused.browser||"—"}</b></div><div className="border-l border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">Server</span><b className="mt-1 block text-[10px] text-[#405049]">{focused.server||"—"}</b></div><div className="border-l border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">GA4</span><b className="mt-1 block text-[10px] text-[#3b646d]">{focused.ga4}</b></div><div className="border-l border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">Meta</span><b className="mt-1 block text-[10px] text-[#405049]">{focused.meta}</b></div></div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Diagnostic</b><p className="mt-2 text-[7.5px] leading-4 text-[#70837f]">{focused.issue}</p></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Required event contract</b><p className="mt-2 font-mono text-[7px] leading-4 text-[#718079]">{focused.required}</p><p className="mt-3 text-[6.5px] leading-3.5 text-[#929d97]">Validation checks required keys, data type, currency/value consistency, item identity, consent state and disallowed raw PII.</p></div>{focused.name==="purchase"&&<div className="rounded-xl border border-rose-200 bg-rose-50 p-4"><b className="text-[8px] text-rose-700">Deduplication remediation</b><p className="mt-2 text-[7px] leading-4 text-rose-700">Generate one stable event_id per order and reuse that same ID for both browser Pixel and server CAPI. Server retries must not generate a new event_id.</p></div>}<div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-800">Production safety</b><p className="mt-2 text-[7px] leading-4 text-amber-700">Use test-event code or staging. Never create a fake production purchase, alter a real order or expose customer data while diagnosing tracking.</p></div></div><footer className="sticky bottom-0 grid grid-cols-3 gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur"><button onClick={()=>showNotice("Event payload schema copied without customer values or secrets.")} className="h-10 rounded-xl border border-[#dce4e0] text-[8px] font-bold text-[#596962]">Copy safe schema</button><button className="h-10 rounded-xl border border-[#bfd0cc] bg-[#edf3f4] px-2 text-[8px] font-bold text-[#3b646d]">Create remediation task</button><button className="h-10 rounded-xl bg-[#3b646d] px-2 text-[8px] font-bold text-white">Open test session</button></footer></aside></div>}

    {testOpen&&<div className="fixed inset-0 z-[95] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setTestOpen(false)}}><section className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5 sm:p-6"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Safe diagnostic session</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Test an event without changing production</h2><p className="mt-1 text-[7.5px] leading-4 text-[#87928d]">Listen, validate and compare destinations. This session cannot publish GTM, create an order or alter live tracking.</p></div><button onClick={()=>setTestOpen(false)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="p-5 sm:p-6">{testStage==="Setup"?<div className="space-y-5"><div className="flex items-center gap-2"><span className="rounded-full bg-[#3b646d] px-3 py-1.5 text-[7px] font-bold text-white">1 · Configure</span><span className="rounded-full bg-[#f2f4f3] px-3 py-1.5 text-[7px] font-bold text-[#87928d]">2 · Listen</span><span className="rounded-full bg-[#f2f4f3] px-3 py-1.5 text-[7px] font-bold text-[#87928d]">3 · Validate</span></div><div className="grid gap-4 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Event<select value={testEvent} onChange={event=>setTestEvent(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 font-mono text-[8px] text-[#405049] outline-none focus:border-[#9eb7b4]">{trackingEvents.map(item=><option key={item.name}>{item.name}</option>)}</select></label><label className="text-[7px] font-bold text-[#65736c]">Environment<select value={testEnvironment} onChange={event=>{const value=event.target.value as "Staging"|"Production";setTestEnvironment(value);setTestUrl(value==="Staging"?"https://staging.brandnbeauty.com/checkout/success":"https://brandnbeauty.com/checkout/success")}} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none focus:border-[#9eb7b4]"><option>Staging</option><option>Production</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Destination<select value={testDestination} onChange={event=>setTestDestination(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none focus:border-[#9eb7b4]"><option>GA4 + Meta</option><option>GA4 only</option><option>Meta Pixel + CAPI</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Synthetic reference<input value={testReference} onChange={event=>setTestReference(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 font-mono text-[8px] text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><label className="text-[7px] font-bold text-[#65736c] sm:col-span-2">Test page URL<input value={testUrl} onChange={event=>setTestUrl(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] text-[#405049] outline-none focus:border-[#9eb7b4]"/></label>{testEnvironment==="Production"&&<label className="text-[7px] font-bold text-amber-800 sm:col-span-2">Production test-event code<input value={testCode} onChange={event=>setTestCode(event.target.value)} placeholder="Required—never paste an access token" className="mt-2 h-10 w-full rounded-xl border border-amber-200 bg-amber-50 px-3 font-mono text-[8px] text-amber-800 outline-none focus:border-amber-400"/></label>}</div><div className="grid gap-3 sm:grid-cols-2"><article className="rounded-xl border border-[#e2e8e5] bg-[#fafcfb] p-4"><b className="text-[8px] text-[#405049]">Required contract</b><p className="mt-2 font-mono text-[7px] leading-4 text-[#718079]">{trackingEvents.find(item=>item.name===testEvent)?.required}</p></article><article className="rounded-xl border border-[#d6e2df] bg-[#edf3f4] p-4"><b className="text-[8px] text-[#304d4d]">Session guardrails</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">Synthetic reference only · no raw PII · one stable event_id for browser/server · listener automatically expires after 15 minutes.</p></article></div><label className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4"><input type="checkbox" checked={testConfirmed} onChange={event=>setTestConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/><span className="text-[7px] leading-4 text-amber-800">I confirm this is a diagnostic listener, the reference is synthetic, and no real customer/order data will be used.</span></label><div className="flex justify-end gap-2"><button onClick={()=>setTestOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!testConfirmed||!testReference||(testEnvironment==="Production"&&!testCode)} onClick={()=>setTestStage("Result")} className="h-10 rounded-xl bg-[#3b646d] px-5 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Start safe test session</button></div></div>:<div className="space-y-5"><div className="flex items-center gap-2"><span className="rounded-full bg-emerald-600 px-3 py-1.5 text-[7px] font-bold text-white">Validated</span><b className="font-mono text-[8px] text-[#405049]">{testEvent} · {testReference}</b><span className="ml-auto text-[7px] text-[#87928d]">{testEnvironment} · {testDestination}</span></div><div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-white text-emerald-700"><Icon name="check" size={16}/></span><div><b className="text-[11px] text-emerald-800">Diagnostic payload received</b><p className="mt-1 text-[7px] text-emerald-700">Schema, currency/value and approved identity fields passed validation.</p></div></div></div><div className="grid gap-3 sm:grid-cols-2">{[["Browser Pixel",trackingEvents.find(item=>item.name===testEvent)?.browser?"Received":"Not expected"],["Server CAPI",trackingEvents.find(item=>item.name===testEvent)?.server?"Received":"Not expected"],["GA4 validation","Passed"],["Meta deduplication",testEvent==="purchase"?"Review event_id":"Passed"]].map(item=><article key={item[0]} className="rounded-xl border border-[#e2e8e5] p-4"><span className="text-[6.5px] text-[#929d97]">{item[0]}</span><b className={"mt-1.5 block text-[9px] "+(item[1]==="Review event_id"?"text-amber-700":item[1]==="Not expected"?"text-[#87928d]":"text-emerald-700")}>{item[1]}</b></article>)}</div>{testEvent==="purchase"&&<div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-800">One warning remains</b><p className="mt-2 text-[7px] leading-4 text-amber-700">Browser and server payloads were both accepted, but production history still shows inconsistent event_id reuse on retries. Create a remediation task before publishing any change.</p></div>}<div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8px] text-[#405b58]">Evidence snapshot</b><p className="mt-2 font-mono text-[7px] leading-4 text-[#70837f]">event_id: {testReference}-evt · consent: granted · raw_pii: blocked · listener: diagnostic-only</p></div><div className="flex flex-wrap justify-end gap-2"><button onClick={()=>setTestStage("Setup")} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Run another test</button>{testEvent==="purchase"&&<button className="h-10 rounded-xl border border-[#bfd0cc] bg-[#edf3f4] px-4 text-[8px] font-bold text-[#3b646d]">Create remediation task</button>}<button onClick={()=>setTestOpen(false)} className="h-10 rounded-xl bg-[#3b646d] px-5 text-[8px] font-bold text-white">Close result</button></div></div>}</div></section></div>}

    {remediationOpen&&<div className="fixed inset-0 z-[96] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setRemediationOpen(false)}}><section className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5 sm:p-6"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Controlled remediation</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Create tracking issue task</h2><p className="mt-1 text-[7.5px] leading-4 text-[#87928d]">Captures evidence and ownership only. It does not edit code, GTM or a live connector.</p></div><button onClick={()=>setRemediationOpen(false)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-5 p-5 sm:p-6"><div className="grid gap-4 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Event<select value={remediationEvent} onChange={event=>setRemediationEvent(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 font-mono text-[8px] text-[#405049] outline-none">{trackingEvents.map(item=><option key={item.name}>{item.name}</option>)}</select></label><label className="text-[7px] font-bold text-[#65736c]">Owner<select value={remediationOwner} onChange={event=>setRemediationOwner(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none"><option>Engineering · Tracking</option><option>Growth · Analytics</option><option>Agency · Paid Media</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Severity<select value={remediationSeverity} onChange={event=>setRemediationSeverity(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none"><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Due date<input type="date" value={remediationDue} onChange={event=>setRemediationDue(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] text-[#405049] outline-none"/></label><label className="text-[7px] font-bold text-[#65736c] sm:col-span-2">Issue and evidence<textarea value={remediationNote} onChange={event=>setRemediationNote(event.target.value)} rows={4} className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4 text-[#405049] outline-none focus:border-[#9eb7b4]"/></label></div><article className="rounded-xl border border-[#d6e2df] bg-[#edf3f4] p-4"><b className="text-[8px] text-[#304d4d]">Required workflow</b><div className="mt-3 grid gap-2 sm:grid-cols-4">{["Fix in code / GTM staging","Attach before/after diff","Human approval","Deploy + production verify"].map((item,index)=><div key={item} className="rounded-lg bg-white p-3"><span className="text-[6px] font-bold text-[#3b646d]">0{index+1}</span><b className="mt-1.5 block text-[7px] leading-3.5 text-[#52615a]">{item}</b></div>)}</div></article><label className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4"><input type="checkbox" checked={remediationConfirmed} onChange={event=>setRemediationConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/><span className="text-[7px] leading-4 text-amber-800">I understand that this creates a reviewable task only; production tracking remains unchanged until an authorized human approves and deploys the fix.</span></label><div className="flex justify-end gap-2"><button onClick={()=>setRemediationOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!remediationConfirmed||!remediationNote.trim()} onClick={()=>{setRemediationOpen(false);setFocused(null);showNotice("Remediation task created with evidence, owner and approval boundary.")}} className="h-10 rounded-xl bg-[#3b646d] px-5 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Save remediation task</button></div></div></section></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

type RetentionSegment={
  id:string;name:string;definition:string;customers:number;deliveredOrders:number;aov:number;clv:number;repeatRate:number;daysSince:number;revenue:number;opportunity:number;priority:"High"|"Medium"|"Monitor";signal:string;
};

const retentionSegments:RetentionSegment[]=[
  {id:"SEG-101",name:"VIP loyalists",definition:"4+ delivered orders · high contribution",customers:84,deliveredOrders:512,aov:1680,clv:8420,repeatRate:78.6,daysSince:19,revenue:861400,opportunity:126000,priority:"High",signal:"Early access and replenishment reminders can protect loyalty without discounting."},
  {id:"SEG-102",name:"Second-order due",definition:"First delivered order · expected reorder window reached",customers:216,deliveredOrders:216,aov:1045,clv:1045,repeatRate:0,daysSince:41,revenue:225700,opportunity:188000,priority:"High",signal:"The largest near-term retention opportunity is converting first-time buyers into a second delivered order."},
  {id:"SEG-103",name:"Repeat growers",definition:"2–3 delivered orders · rising basket value",customers:173,deliveredOrders:438,aov:1325,clv:3354,repeatRate:64.2,daysSince:27,revenue:580400,opportunity:142000,priority:"High",signal:"Routine-based bundles could raise basket value while keeping product relevance high."},
  {id:"SEG-104",name:"Churn risk",definition:"Previously repeat · 75+ days inactive",customers:119,deliveredOrders:397,aov:1180,clv:3937,repeatRate:58.1,daysSince:96,revenue:468600,opportunity:98000,priority:"High",signal:"Prioritize service-led reactivation and replenish timing before offering a blanket discount."},
  {id:"SEG-105",name:"First-time high intent",definition:"One delivered order · high-value basket",customers:148,deliveredOrders:148,aov:1875,clv:1875,repeatRate:0,daysSince:18,revenue:277500,opportunity:87000,priority:"Medium",signal:"Education and complementary-product recommendations can shorten time to second order."},
  {id:"SEG-106",name:"Discount dependent",definition:"3+ delivered orders · 70%+ orders discounted",customers:76,deliveredOrders:284,aov:965,clv:3607,repeatRate:69.7,daysSince:32,revenue:274100,opportunity:38000,priority:"Monitor",signal:"Protect margin: test value-add bundles instead of increasing discount depth."},
  {id:"SEG-107",name:"COD friction",definition:"2+ failed/returned COD attempts",customers:63,deliveredOrders:74,aov:910,clv:1069,repeatRate:18.4,daysSince:54,revenue:67300,opportunity:21000,priority:"Monitor",signal:"Address verification and confirmation quality matter more than promotional outreach."},
];

function RetentionAovClvWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [range,setRange]=useState<"30D"|"90D"|"12M">("90D");
  const [cohortBasis,setCohortBasis]=useState("First delivered order");
  const [valueBasis,setValueBasis]=useState("Delivered revenue");
  const [view,setView]=useState<"Segments"|"Cohorts"|"Reorder windows">("Segments");
  const [query,setQuery]=useState("");
  const [priority,setPriority]=useState("All priorities");
  const [focused,setFocused]=useState<RetentionSegment|null>(null);
  const [notice,setNotice]=useState("");
  const [audienceOpen,setAudienceOpen]=useState(false);
  const [audienceSegment,setAudienceSegment]=useState("SEG-102");
  const [audienceName,setAudienceName]=useState("Second-order due · Aug 2026");
  const [audienceDestination,setAudienceDestination]=useState("Internal review queue");
  const [consentScope,setConsentScope]=useState("Contactable customers only");
  const [excludeCodRisk,setExcludeCodRisk]=useState(true);
  const [excludeRecentContact,setExcludeRecentContact]=useState(true);
  const [audienceConfirmed,setAudienceConfirmed]=useState(false);
  const [planOpen,setPlanOpen]=useState(false);
  const [planSegment,setPlanSegment]=useState("SEG-102");
  const [planObjective,setPlanObjective]=useState("Increase second delivered order");
  const [planChannel,setPlanChannel]=useState("Messenger · manual review");
  const [planOffer,setPlanOffer]=useState("Education + relevant routine");
  const [planMarginFloor,setPlanMarginFloor]=useState("28");
  const [planNote,setPlanNote]=useState("");
  const [planConfirmed,setPlanConfirmed]=useState(false);
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const openAudience=(item?:RetentionSegment)=>{const segment=item||retentionSegments[1];setAudienceSegment(segment.id);setAudienceName(segment.name+" · Aug 2026");setAudienceDestination("Internal review queue");setConsentScope("Contactable customers only");setExcludeCodRisk(true);setExcludeRecentContact(true);setAudienceConfirmed(false);setAudienceOpen(true)};
  const openPlan=(item?:RetentionSegment)=>{const segment=item||retentionSegments[1];setPlanSegment(segment.id);setPlanObjective(segment.id==="SEG-104"?"Reactivate previously loyal customers":segment.id==="SEG-101"?"Protect VIP loyalty":"Increase second delivered order");setPlanChannel("Messenger · manual review");setPlanOffer(segment.id==="SEG-101"?"Early access + service benefit":"Education + relevant routine");setPlanMarginFloor("28");setPlanNote(segment.signal);setPlanConfirmed(false);setPlanOpen(true)};
  const handleRetentionActionCapture=(event:React.MouseEvent<HTMLDivElement>)=>{const button=(event.target as HTMLElement).closest("button");const label=button?.textContent?.trim();if(!button||!label)return;if(label==="Build audience"){event.stopPropagation();openAudience(focused||undefined);}else if(label==="Create retention plan"){event.stopPropagation();openPlan(focused||undefined);}};
  const money=(value:number)=>"৳"+new Intl.NumberFormat("en-BD",{maximumFractionDigits:0}).format(value);
  const visibleSegments=retentionSegments.filter(item=>(priority==="All priorities"||item.priority===priority)&&(item.name+" "+item.definition+" "+item.signal).toLowerCase().includes(query.toLowerCase()));
  const priorityTone=(value:RetentionSegment["priority"])=>value==="High"?"bg-rose-50 text-rose-700 ring-rose-200":value==="Medium"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-slate-100 text-slate-600 ring-slate-200";
  const cohortRows=[
    {month:"Mar 2026",customers:364,retention:[100,28.4,20.1,15.7,12.9,10.8]},
    {month:"Apr 2026",customers:402,retention:[100,30.1,21.8,17.2,13.6,11.4]},
    {month:"May 2026",customers:438,retention:[100,31.7,23.4,18.9,15.2,0]},
    {month:"Jun 2026",customers:471,retention:[100,34.2,25.8,20.4,0,0]},
    {month:"Jul 2026",customers:516,retention:[100,36.8,27.1,0,0,0]},
    {month:"Aug 2026",customers:284,retention:[100,38.2,0,0,0,0]},
  ];
  const reorderRows=[
    {category:"Face wash",window:"35–48 days",due:176,coverage:91,attach:"Serum",potential:109000},
    {category:"Serum",window:"52–70 days",due:119,coverage:86,attach:"Face wash",potential:97000},
    {category:"Body wash",window:"28–42 days",due:94,coverage:94,attach:"Soap / body care",potential:68000},
    {category:"Routine bundle",window:"62–85 days",due:58,coverage:79,attach:"Refill item",potential:83000},
    {category:"Hair care",window:"40–60 days",due:41,coverage:82,attach:"Treatment pair",potential:36000},
  ];
  const views=["Segments","Cohorts","Reorder windows"] as const;

  return <div className="space-y-5" onClickCapture={handleRetentionActionCapture}>
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Customer growth intelligence</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Retention / AOV / CLV</h1><p className="mt-1.5 max-w-2xl text-[12.5px] leading-5 text-[#66736d]">Turn delivered-order history into repeat-purchase timing, profitable customer segments and clear lifetime-value opportunities.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>onNavigate("Customers")} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="customers" size={13}/>Customer CRM</button><button onClick={()=>showNotice("Audience builder opens from the final controlled action layer.")} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="plus" size={13}/>Build audience</button></div></section>

    <section className="rounded-2xl border border-[#dfe7e4] bg-white p-3"><div className="flex flex-col gap-3 xl:flex-row xl:items-center"><div className="flex gap-1">{(["30D","90D","12M"] as const).map(item=><button key={item} onClick={()=>setRange(item)} className={"h-8 min-w-12 rounded-lg px-3 text-[8px] font-bold "+(range===item?"bg-[#3b646d] text-white":"text-[#7a8881] hover:bg-[#f2f5f3]")}>{item}</button>)}</div><select value={cohortBasis} onChange={event=>setCohortBasis(event.target.value)} className="h-9 rounded-lg border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f] outline-none"><option>First delivered order</option><option>First placed order</option></select><select value={valueBasis} onChange={event=>setValueBasis(event.target.value)} className="h-9 rounded-lg border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f] outline-none"><option>Delivered revenue</option><option>Contribution profit</option></select><div className="ml-auto flex items-center gap-2 rounded-lg bg-[#f6f8f7] px-3 py-2 text-[7px] text-[#718079]"><span className="h-2 w-2 rounded-full bg-emerald-500"/>Customer identity match <b className="text-[#405049]">97.4%</b><span className="text-amber-700">31 unmatched</span></div></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[
      ["Repeat purchase rate","38.2%","+3.4 pts","Delivered customers who returned","text-emerald-700"],
      ["Active customers","1,846","+12.8%","Delivered in the last 90 days","text-[#405049]"],
      ["Delivered AOV",money(1186),"+৳74","After cancellation and return","text-[#3b646d]"],
      ["90D realized CLV",money(2640),"+9.6%","Delivered revenue per acquired customer","text-[#405049]"],
      ["Churn-risk customers","119","৳98k","Previously repeat, now inactive","text-rose-700"],
      ["Second-order opportunity",money(188000),"216 due","Expected delivered revenue","text-amber-700"],
    ].map(([label,value,change,meta,tone])=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between"><span className="text-[6.5px] font-bold uppercase tracking-[.1em] text-[#89948f]">{label}</span><span className="text-[6px] font-bold text-emerald-700">{change}</span></div><b className={"mt-3 block text-[17px] tracking-[-.03em] "+tone}>{value}</b><p className="mt-2 text-[6.5px] leading-3.5 text-[#929d97]">{meta}</p></article>)}</section>

    <section className="grid gap-4 xl:grid-cols-[minmax(0,1.2fr)_minmax(380px,.8fr)]"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Cohort retention</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Do customers return after their first delivery?</h2><p className="mt-1 text-[7px] text-[#929d97]">{cohortBasis} · delivered customer basis</p></div><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">Month 1 improving</span></div><div className="mt-5 overflow-x-auto"><div className="min-w-[650px]"><div className="grid grid-cols-[95px_62px_repeat(6,minmax(58px,1fr))] gap-1 text-center text-[6px] font-bold uppercase tracking-[.08em] text-[#929d97]"><span className="text-left">Cohort</span><span>Customers</span>{["M0","M1","M2","M3","M4","M5"].map(item=><span key={item}>{item}</span>)}</div><div className="mt-2 space-y-1">{cohortRows.map(row=><div key={row.month} className="grid grid-cols-[95px_62px_repeat(6,minmax(58px,1fr))] gap-1 text-center"><b className="flex items-center text-left text-[7px] text-[#52615a]">{row.month}</b><span className="flex items-center justify-center rounded-lg bg-[#f6f8f7] text-[7px] text-[#718079]">{row.customers}</span>{row.retention.map((value,index)=><span key={index} className={"flex h-9 items-center justify-center rounded-lg text-[7px] font-bold "+(value===0?"bg-[#fafbfa] text-[#c4cbc8]":value>60?"bg-[#3b646d] text-white":value>30?"bg-[#8eaaaa] text-white":value>20?"bg-[#c5d6d2] text-[#405b58]":"bg-[#edf3f4] text-[#607a76]")}>{value?value+"%":"—"}</span>)}</div>)}</div></div></div><div className="mt-4 flex items-center justify-between border-t border-[#edf0ee] pt-4 text-[6.5px] text-[#87928d]"><span>Later months are blank until the cohort matures.</span><b className="text-[#3b646d]">M1: 28.4% → 38.2%</b></div></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Lifecycle progression</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Where customer value compounds</h2></div><Icon name="customers" size={16} className="text-[#3b646d]"/></div><div className="mt-5 space-y-3">{[
      ["First delivered order",2840,"100%","bg-[#3b646d]"],["Second delivered order",1085,"38.2%","bg-[#537a7e]"],["Active repeat customer",592,"20.8%","bg-[#769696]"],["VIP · 4+ delivered",84,"3.0%","bg-[#9eb6b2]"],
    ].map(([label,count,rate,tone],index)=><button key={label} onClick={()=>index===3?setFocused(retentionSegments[0]):index===1?setFocused(retentionSegments[1]):showNotice(label+" cohort opened.")} className="w-full text-left"><div className="flex items-center justify-between"><b className="text-[7.5px] text-[#52615a]">{label}</b><span className="text-[6.5px] text-[#929d97]">{count} · {rate}</span></div><div className="mt-1.5 h-2 overflow-hidden rounded-full bg-[#edf1ef]"><div className={"h-full rounded-full "+tone} style={{width:rate}}/></div></button>)}</div><div className="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-800">Biggest value leak</b><p className="mt-2 text-[7px] leading-4 text-amber-700">61.8% of first-time delivered customers have not yet made a second delivered purchase.</p><button onClick={()=>setFocused(retentionSegments[1])} className="mt-3 text-[7px] font-bold text-amber-800">Inspect second-order segment →</button></div></article></section>

    <section className="grid gap-4 xl:grid-cols-[minmax(0,1.15fr)_minmax(360px,.85fr)]"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Growth opportunities</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">AOV and retention actions worth reviewing</h2></div><span className="rounded-full bg-amber-50 px-2 py-1 text-[7px] font-bold text-amber-700">4 decisions</span></div><div className="mt-4 space-y-2">{[
      ["Convert first order → second order","216 customers are inside their expected reorder window",money(188000),"SEG-102","border-rose-200 bg-rose-50"],
      ["Build routine bundles for repeat growers","High relevance can lift AOV without broad discounting",money(142000),"SEG-103","border-amber-200 bg-amber-50"],
      ["Protect VIP loyalty","Early access and service benefits outperform margin-heavy offers",money(126000),"SEG-101","border-[#d6e2df] bg-[#edf3f4]"],
      ["Reactivate previously loyal customers","Prioritize service and replenishment before incentives",money(98000),"SEG-104","border-amber-200 bg-amber-50"],
    ].map(item=><button key={item[0]} onClick={()=>setFocused(retentionSegments.find(segment=>segment.id===item[3])||null)} className={"grid w-full grid-cols-[minmax(0,1fr)_70px] items-center gap-3 rounded-xl border p-3 text-left "+item[4]}><div><b className="block text-[8px] text-[#405049]">{item[0]}</b><span className="mt-1 block text-[6.5px] leading-3.5 text-[#7b8982]">{item[1]}</span></div><b className="text-right text-[8px] text-[#3b646d]">{item[2]}</b></button>)}</div></article><article className="rounded-2xl border border-[#d7e3e0] bg-[#edf3f4] p-4 sm:p-5"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5e7875]">Value model</p><h2 className="mt-1 text-[14px] font-bold text-[#304d4d]">CLV grounded in delivered commerce</h2><div className="mt-4 space-y-3">{[["Delivered revenue","Order total after returns"],["Contribution value","− COGS, courier, packaging, payment fees"],["Customer identity","Normalized phone + customer ID"],["Observation window","90D realized · 12M modeled"]].map(item=><div key={item[0]} className="rounded-xl bg-white p-3"><b className="block text-[7.5px] text-[#405b58]">{item[0]}</b><span className="mt-1 block text-[6.5px] leading-3.5 text-[#70837f]">{item[1]}</span></div>)}</div><p className="mt-4 border-t border-[#d5e1de] pt-4 text-[7px] leading-4 text-[#647b77]">Forecast CLV is a decision aid, not booked revenue. Finance remains the source of truth for realized profit.</p></article></section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{views.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d]")}>{item}</button>)}</div></div>{view==="Segments"?<><div className="space-y-3 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:p-5"><div className="flex flex-col gap-2 xl:flex-row"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search segment, definition or signal..." className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><select value={priority} onChange={event=>setPriority(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f] outline-none"><option>All priorities</option><option>High</option><option>Medium</option><option>Monitor</option></select></div></div><div className="overflow-x-auto"><table className="w-full min-w-[1320px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Segment / rule</th><th className="px-4 py-3.5">Customers</th><th className="px-4 py-3.5">Delivered orders</th><th className="px-4 py-3.5">AOV</th><th className="px-4 py-3.5">Realized CLV</th><th className="px-4 py-3.5">Repeat rate</th><th className="px-4 py-3.5">Days since order</th><th className="px-4 py-3.5">Delivered value</th><th className="px-4 py-3.5">Opportunity</th><th className="px-4 py-3.5">Priority</th><th className="w-12 px-4 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{visibleSegments.map(item=><tr key={item.id} onClick={()=>setFocused(item)} className="cursor-pointer text-[8px] text-[#5f6e67] hover:bg-[#fafcfb]"><td className="px-5 py-4"><b className="block text-[8.5px] text-[#33423b]">{item.name}</b><span className="mt-1 block max-w-[250px] truncate text-[6.5px] text-[#929d97]">{item.definition} · {item.id}</span></td><td className="px-4 py-4 font-bold text-[#405049]">{item.customers}</td><td className="px-4 py-4">{item.deliveredOrders}</td><td className="px-4 py-4 font-bold text-[#52615a]">{money(item.aov)}</td><td className="px-4 py-4 font-bold text-[#3b646d]">{money(item.clv)}</td><td className="px-4 py-4">{item.repeatRate}%</td><td className={"px-4 py-4 "+(item.daysSince>75?"font-bold text-rose-700":"text-[#65736c]")}>{item.daysSince}</td><td className="px-4 py-4">{money(item.revenue)}</td><td className="px-4 py-4 font-bold text-emerald-700">{money(item.opportunity)}</td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+priorityTone(item.priority)}>{item.priority}</span></td><td className="px-4 py-4"><Icon name="chevron" size={12}/></td></tr>)}</tbody></table>{visibleSegments.length===0&&<div className="flex flex-col items-center justify-center px-5 py-14 text-center"><Icon name="search" size={18} className="text-[#83958e]"/><b className="mt-3 text-[9px] text-[#405049]">No segment matches</b><button onClick={()=>{setQuery("");setPriority("All priorities")}} className="mt-3 text-[7.5px] font-bold text-[#3b646d]">Clear filters</button></div>}</div></>:view==="Cohorts"?<div className="grid gap-4 p-4 sm:grid-cols-2 xl:grid-cols-3">{cohortRows.map(row=><button key={row.month} onClick={()=>showNotice(row.month+" cohort detail opened.")} className="rounded-xl border border-[#e2e8e5] p-4 text-left"><div className="flex items-start justify-between"><div><b className="text-[9px] text-[#405049]">{row.month}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">{row.customers} acquired customers</span></div><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[6.5px] font-bold text-[#3b646d]">M1 {row.retention[1]}%</span></div><div className="mt-4 flex h-20 items-end gap-1">{row.retention.map((value,index)=><div key={index} className="min-h-1 flex-1 rounded-t bg-[#6d8f8f]" style={{height:Math.max(5,value)+"%"}}/>)}</div><div className="mt-2 flex justify-between text-[6px] font-bold text-[#9aa49f]"><span>M0</span><span>M5</span></div></button>)}</div>:<div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Category</th><th className="px-4 py-3.5">Observed reorder window</th><th className="px-4 py-3.5">Customers due</th><th className="px-4 py-3.5">Data confidence</th><th className="px-4 py-3.5">Relevant attach</th><th className="px-4 py-3.5">Potential value</th><th className="w-12 px-4 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{reorderRows.map(item=><tr key={item.category} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4 font-bold text-[#405049]">{item.category}</td><td className="px-4 py-4">{item.window}</td><td className="px-4 py-4 font-bold text-[#52615a]">{item.due}</td><td className="px-4 py-4"><div className="flex items-center gap-2"><div className="h-1.5 w-20 overflow-hidden rounded-full bg-[#edf1ef]"><div className="h-full rounded-full bg-[#5f8585]" style={{width:item.coverage+"%"}}/></div><b>{item.coverage}%</b></div></td><td className="px-4 py-4">{item.attach}</td><td className="px-4 py-4 font-bold text-emerald-700">{money(item.potential)}</td><td className="px-4 py-4"><button onClick={()=>showNotice(item.category+" reorder audience opened.")}><Icon name="chevron" size={12}/></button></td></tr>)}</tbody></table></div>}</section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Existing data</p><b className="mt-1.5 block text-[10px] text-[#405049]">Orders, delivery, returns and customer identity</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">V1 derives realized AOV, repeat behavior and segments from current operational records.</p></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Backend expansion</p><b className="mt-1.5 block text-[10px] text-[#405049]">Scheduled scoring and consent-aware activation</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">Live CLV forecasts, automated audience sync and message delivery require new backend jobs and integrations.</p></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5e7875]">Activation boundary</p><b className="mt-1.5 block text-[10px] text-[#304d4d]">Insight → audience draft → approve → send elsewhere</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">AI may rank opportunities, but cannot send messages, publish audiences or create discounts automatically.</p></article></section>

    {focused&&<div className="fixed inset-0 z-[80] bg-[#17231f]/25 backdrop-blur-[1px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-xl overflow-y-auto bg-white shadow-[-24px_0_70px_rgba(18,37,31,.16)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Retention segment inspector</p><h2 className="mt-1.5 text-[17px] font-bold text-[#23322b]">{focused.name}</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused.definition} · {focused.id}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="flex flex-wrap gap-2"><span className={"inline-flex rounded-full px-2.5 py-1 text-[7px] font-bold ring-1 ring-inset "+priorityTone(focused.priority)}>{focused.priority} priority</span><span className="rounded-full bg-[#edf3f4] px-2.5 py-1 text-[7px] font-bold text-[#3b646d]">{focused.customers} customers</span><span className="rounded-full bg-[#f2f4f3] px-2.5 py-1 text-[7px] font-bold text-[#65736c]">{focused.daysSince} days since order</span></div><div className="grid grid-cols-3 gap-3">{[["Delivered AOV",money(focused.aov)],["Realized CLV",money(focused.clv)],["Repeat rate",focused.repeatRate+"%"],["Delivered orders",String(focused.deliveredOrders)],["Delivered value",money(focused.revenue)],["Opportunity",money(focused.opportunity)]].map(item=><div key={item[0]} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1.5 block text-[9px] text-[#405049]">{item[1]}</b></div>)}</div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Recommended decision</b><p className="mt-2 text-[7.5px] leading-4 text-[#70837f]">{focused.signal}</p></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Segment membership rule</b><p className="mt-2 text-[7px] leading-4 text-[#718079]">{focused.definition}. Membership is recomputed from delivered orders, cancellations, returns and normalized customer identity.</p></div><div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-800">Activation safety</b><p className="mt-2 text-[7px] leading-4 text-amber-700">Review consent, suppression rules, contact frequency, margin and exclusions before any audience is exported or contacted.</p></div></div><footer className="sticky bottom-0 grid grid-cols-2 gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur"><button onClick={()=>showNotice("Customer list preview opened with masked contact fields.")} className="h-10 rounded-xl border border-[#dce4e0] text-[8px] font-bold text-[#596962]">Preview customers</button><button onClick={()=>showNotice("Retention plan builder opens from the final controlled action layer.")} className="h-10 rounded-xl bg-[#3b646d] text-[8px] font-bold text-white">Create retention plan</button></footer></aside></div>}

    {audienceOpen&&<div className="fixed inset-0 z-[95] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setAudienceOpen(false)}}><section className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5 sm:p-6"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Controlled audience builder</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Create an audience draft</h2><p className="mt-1 text-[7.5px] leading-4 text-[#87928d]">Define eligibility, consent and exclusions. Saving creates an internal draft only—it does not contact or upload customers.</p></div><button onClick={()=>setAudienceOpen(false)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-5 p-5 sm:p-6"><div className="grid gap-4 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Audience name<input value={audienceName} onChange={event=>setAudienceName(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><label className="text-[7px] font-bold text-[#65736c]">Source segment<select value={audienceSegment} onChange={event=>{setAudienceSegment(event.target.value);const segment=retentionSegments.find(item=>item.id===event.target.value);if(segment)setAudienceName(segment.name+" · Aug 2026")}} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none">{retentionSegments.map(item=><option key={item.id} value={item.id}>{item.name} · {item.customers}</option>)}</select></label><label className="text-[7px] font-bold text-[#65736c]">Destination<select value={audienceDestination} onChange={event=>setAudienceDestination(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none"><option>Internal review queue</option><option>CSV export draft</option><option>Meta custom audience draft</option><option>Messenger manual queue</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Consent scope<select value={consentScope} onChange={event=>setConsentScope(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none"><option>Contactable customers only</option><option>Marketing opt-in only</option><option>Analysis only · no contact</option></select></label></div><div className="grid gap-3 sm:grid-cols-[minmax(0,1fr)_230px]"><div className="space-y-2 rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Mandatory exclusions</b><label className="mt-3 flex items-start gap-3"><input type="checkbox" checked={excludeCodRisk} onChange={event=>setExcludeCodRisk(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/><span><b className="block text-[7.5px] text-[#52615a]">Exclude unresolved COD risk</b><small className="mt-1 block text-[6.5px] leading-3.5 text-[#929d97]">Returned, unreachable or disputed delivery patterns</small></span></label><label className="flex items-start gap-3"><input type="checkbox" checked={excludeRecentContact} onChange={event=>setExcludeRecentContact(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/><span><b className="block text-[7.5px] text-[#52615a]">Exclude contacted in last 7 days</b><small className="mt-1 block text-[6.5px] leading-3.5 text-[#929d97]">Protect contact frequency and customer experience</small></span></label></div><article className="rounded-xl border border-[#d6e2df] bg-[#edf3f4] p-4"><span className="text-[6.5px] font-bold uppercase tracking-[.1em] text-[#5e7875]">Eligible preview</span><strong className="mt-2 block text-[24px] tracking-[-.04em] text-[#304d4d]">{Math.max(0,(retentionSegments.find(item=>item.id===audienceSegment)?.customers||0)-(excludeCodRisk?9:0)-(excludeRecentContact?24:0))}</strong><p className="mt-1 text-[6.5px] text-[#70837f]">of {retentionSegments.find(item=>item.id===audienceSegment)?.customers||0} segment customers</p><div className="mt-4 border-t border-[#d5e1de] pt-3 text-[6.5px] leading-3.5 text-[#647b77]">Contact fields remain masked until an authorized export or channel approval.</div></article></div><div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-800">Activation boundary</b><p className="mt-2 text-[7px] leading-4 text-amber-700">This draft contains rules and customer IDs only. A separate human review must confirm consent, suppression, destination and purpose before any export, platform upload or message send.</p></div><label className="flex items-start gap-3 rounded-xl border border-[#dce5e1] p-4"><input type="checkbox" checked={audienceConfirmed} onChange={event=>setAudienceConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/><span className="text-[7px] leading-4 text-[#596861]">I reviewed the segment basis, consent scope and exclusions. Save this as an internal audience draft without activating it.</span></label><div className="flex justify-end gap-2"><button onClick={()=>setAudienceOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!audienceConfirmed||!audienceName.trim()} onClick={()=>{setAudienceOpen(false);showNotice("Audience draft saved with consent and exclusion rules. No customers contacted.")}} className="h-10 rounded-xl bg-[#3b646d] px-5 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Save audience draft</button></div></div></section></div>}

    {planOpen&&<div className="fixed inset-0 z-[96] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setPlanOpen(false)}}><section className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl border border-white/50 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5 sm:p-6"><div><p className="text-[8px] font-bold uppercase tracking-[.14em] text-[#3b646d]">Retention decision plan</p><h2 className="mt-1.5 text-[18px] font-bold text-[#23322b]">Turn an insight into a reviewable plan</h2><p className="mt-1 text-[7.5px] leading-4 text-[#87928d]">Define the business objective, value proposition and margin guardrail before creating any audience or communication.</p></div><button onClick={()=>setPlanOpen(false)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-5 p-5 sm:p-6"><div className="grid gap-4 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#65736c]">Segment<select value={planSegment} onChange={event=>{setPlanSegment(event.target.value);const segment=retentionSegments.find(item=>item.id===event.target.value);if(segment)setPlanNote(segment.signal)}} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none">{retentionSegments.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="text-[7px] font-bold text-[#65736c]">Objective<select value={planObjective} onChange={event=>setPlanObjective(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none"><option>Increase second delivered order</option><option>Reactivate previously loyal customers</option><option>Protect VIP loyalty</option><option>Increase delivered AOV</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Review channel<select value={planChannel} onChange={event=>setPlanChannel(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none"><option>Messenger · manual review</option><option>Meta audience · draft only</option><option>Customer service call queue</option><option>Email/SMS · future integration</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Value proposition<select value={planOffer} onChange={event=>setPlanOffer(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#405049] outline-none"><option>Education + relevant routine</option><option>Early access + service benefit</option><option>Value-add bundle</option><option>Controlled offer · approval required</option></select></label><label className="text-[7px] font-bold text-[#65736c]">Minimum contribution margin<input type="number" min="0" max="100" value={planMarginFloor} onChange={event=>setPlanMarginFloor(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] text-[#405049] outline-none"/></label><label className="text-[7px] font-bold text-[#65736c]">Expected review window<input value="7 days · max 1 contact" readOnly className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-[#fafbfa] px-3 text-[8px] text-[#65736c] outline-none"/></label><label className="text-[7px] font-bold text-[#65736c] sm:col-span-2">Decision note<textarea value={planNote} onChange={event=>setPlanNote(event.target.value)} rows={3} className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4 text-[#405049] outline-none focus:border-[#9eb7b4]"/></label></div><div className="grid gap-3 sm:grid-cols-4">{[["Customers",String(retentionSegments.find(item=>item.id===planSegment)?.customers||0)],["Opportunity",money(retentionSegments.find(item=>item.id===planSegment)?.opportunity||0)],["Current AOV",money(retentionSegments.find(item=>item.id===planSegment)?.aov||0)],["Margin floor",planMarginFloor+"%"]].map(item=><article key={item[0]} className="rounded-xl border border-[#e2e8e5] p-4"><span className="text-[6.5px] text-[#929d97]">{item[0]}</span><b className="mt-1.5 block text-[10px] text-[#405049]">{item[1]}</b></article>)}</div><article className="rounded-xl border border-[#d6e2df] bg-[#edf3f4] p-4"><b className="text-[8px] text-[#304d4d]">Approval path</b><div className="mt-3 grid gap-2 sm:grid-cols-4">{["Review customer eligibility","Review content + offer","Approve audience/channel","Launch elsewhere + measure delivery"].map((item,index)=><div key={item} className="rounded-lg bg-white p-3"><span className="text-[6px] font-bold text-[#3b646d]">0{index+1}</span><b className="mt-1.5 block text-[7px] leading-3.5 text-[#52615a]">{item}</b></div>)}</div></article><div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-[8px] text-amber-800">No automatic promotion</b><p className="mt-2 text-[7px] leading-4 text-amber-700">This plan cannot create coupons, send messages, upload audiences or spend advertising budget. Each downstream action needs its own authorized approval.</p></div><label className="flex items-start gap-3 rounded-xl border border-[#dce5e1] p-4"><input type="checkbox" checked={planConfirmed} onChange={event=>setPlanConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/><span className="text-[7px] leading-4 text-[#596861]">I reviewed the objective, segment, contact frequency and contribution-margin floor. Save this as a planning record only.</span></label><div className="flex justify-end gap-2"><button onClick={()=>setPlanOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!planConfirmed||!planNote.trim()||Number(planMarginFloor)<1} onClick={()=>{setPlanOpen(false);setFocused(null);showNotice("Retention plan saved for human review. No audience or message activated.")}} className="h-10 rounded-xl bg-[#3b646d] px-5 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Save retention plan</button></div></div></section></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

type WorkflowStatus="Active"|"Draft"|"Paused"|"Review"|"Error";
type WorkflowRisk="Safe auto"|"Approval required"|"Restricted";
type AutomationView="Workflows"|"Runs"|"Approvals";
type WorkflowRow={
  id:string;name:string;domain:string;trigger:string;steps:string[];status:WorkflowStatus;risk:WorkflowRisk;runs:number;success:number;avg:string;lastRun:string;owner:string;failure:string;
};
type WorkflowRun={id:string;workflow:string;record:string;started:string;duration:string;status:"Succeeded"|"Waiting approval"|"Failed"|"Skipped";step:string;attempts:number};

