function LegacyExpensesCostWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [view,setView]=useState<"All expenses"|"Pending approval"|"Unpaid"|"Recurring"|"Missing evidence"|"Categories">("All expenses");
  const [query,setQuery]=useState("");
  const [category,setCategory]=useState("All categories");
  const [costCenter,setCostCenter]=useState("All cost centers");
  const [payment,setPayment]=useState("All payment states");
  const [focused,setFocused]=useState<ExpenseRow|null>(null);
  const [notice,setNotice]=useState("");
  const [entryOpen,setEntryOpen]=useState(false);
  const [entryPayee,setEntryPayee]=useState("");
  const [entryCategory,setEntryCategory]=useState("Packaging");
  const [entryCenter,setEntryCenter]=useState("Fulfilment");
  const [entryAmount,setEntryAmount]=useState("");
  const [entryTax,setEntryTax]=useState("0");
  const [entryDate,setEntryDate]=useState("2026-08-22");
  const [entryPayment,setEntryPayment]=useState("Unpaid");
  const [entryMethod,setEntryMethod]=useState("Bank transfer");
  const [entryReference,setEntryReference]=useState("");
  const [entryPurpose,setEntryPurpose]=useState("");
  const [entryAllocation,setEntryAllocation]=useState("Cost center only");
  const [entryRecurring,setEntryRecurring]=useState(false);
  const [entryConfirmed,setEntryConfirmed]=useState(false);
  const [approvalOpen,setApprovalOpen]=useState(false);
  const [approvalDecision,setApprovalDecision]=useState("Approve expense");
  const [approvalReason,setApprovalReason]=useState("");
  const [approvalConfirmed,setApprovalConfirmed]=useState(false);
  const [paymentOpen,setPaymentOpen]=useState(false);
  const [paymentAmount,setPaymentAmount]=useState("");
  const [paymentMethod,setPaymentMethod]=useState("Bank transfer");
  const [paymentDate,setPaymentDate]=useState("2026-08-22");
  const [paymentReference,setPaymentReference]=useState("");
  const [paymentConfirmed,setPaymentConfirmed]=useState(false);
  const [budgetOpen,setBudgetOpen]=useState(false);
  const [budgetCategory,setBudgetCategory]=useState("Advertising");
  const [budgetAmount,setBudgetAmount]=useState("200000");
  const [budgetAlert,setBudgetAlert]=useState("90%");
  const [budgetReason,setBudgetReason]=useState("");
  const [budgetConfirmed,setBudgetConfirmed]=useState(false);
  const [evidenceOpen,setEvidenceOpen]=useState(false);
  const [evidenceType,setEvidenceType]=useState("Supplier invoice");
  const [evidenceReference,setEvidenceReference]=useState("");
  const [evidenceFile,setEvidenceFile]=useState("");
  const [evidenceNote,setEvidenceNote]=useState("");
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const openEntry=()=>{setEntryPayee("");setEntryCategory("Packaging");setEntryCenter("Fulfilment");setEntryAmount("");setEntryTax("0");setEntryDate("2026-08-22");setEntryPayment("Unpaid");setEntryMethod("Bank transfer");setEntryReference("");setEntryPurpose("");setEntryAllocation("Cost center only");setEntryRecurring(false);setEntryConfirmed(false);setEntryOpen(true)};
  const openApproval=()=>{setApprovalDecision(focused?.status==="Pending"?"Approve expense":"Request changes");setApprovalReason("");setApprovalConfirmed(false);setApprovalOpen(true)};
  const openPayment=()=>{setPaymentAmount(String((focused?.amount||0)+(focused?.tax||0)));setPaymentMethod(focused?.method.includes("Card")?"Corporate card":focused?.method.includes("bKash")?"bKash business":"Bank transfer");setPaymentDate("2026-08-22");setPaymentReference("");setPaymentConfirmed(false);setPaymentOpen(true)};
  const openBudget=()=>{setBudgetCategory("Advertising");setBudgetAmount("200000");setBudgetAlert("90%");setBudgetReason("");setBudgetConfirmed(false);setBudgetOpen(true)};
  const openEvidence=()=>{setEvidenceType("Supplier invoice");setEvidenceReference(focused?.reference||"");setEvidenceFile("");setEvidenceNote("");setEvidenceOpen(true)};
  const money=(value:number)=>"৳"+value.toLocaleString("en-BD");
  const statusTone=(value:ExpenseStatus)=>value==="Approved"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Rejected"?"bg-rose-50 text-rose-700 ring-rose-200":"bg-amber-50 text-amber-700 ring-amber-200";
  const paymentTone=(value:ExpensePayment)=>value==="Paid"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Unpaid"?"bg-rose-50 text-rose-700 ring-rose-200":value==="Partial"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-sky-50 text-sky-700 ring-sky-200";
  const visible=expenseRows.filter(item=>(view==="All expenses"||(view==="Pending approval"&&item.status==="Pending")||(view==="Unpaid"&&(item.payment==="Unpaid"||item.payment==="Partial"||item.payment==="Scheduled"))||(view==="Recurring"&&item.recurring!=="One-time")||(view==="Missing evidence"&&(item.evidence.includes("missing")||item.evidence.includes("No receipt")))||view==="Categories")&&(category==="All categories"||item.category===category)&&(costCenter==="All cost centers"||item.costCenter===costCenter)&&(payment==="All payment states"||item.payment===payment)&&(item.id+" "+item.payee+" "+item.description+" "+item.reference+" "+item.linked).toLowerCase().includes(query.toLowerCase()));
  const views=["All expenses","Pending approval","Unpaid","Recurring","Missing evidence","Categories"] as const;
  const categoryMix=[["Advertising",31,184200,"bg-[#6f9692]"],["Salary",24,142000,"bg-[#9bb9b4]"],["Courier",17,98840,"bg-[#d6a69d]"],["Packaging",11,64820,"bg-[#dbc286]"],["Operations",9,52800,"bg-[#a8a5c8]"],["Other",8,47420,"bg-slate-300"]];
  const monthlyBudget=[["Advertising",200000,184200],["Salary",150000,142000],["Courier",110000,98840],["Packaging",70000,64820],["Operations",60000,52800]];
  const approvals=expenseRows.filter(item=>item.status==="Pending");
  return <div className="space-y-5">
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Cost truth ledger</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">Expenses &amp; Cost Management</h1><p className="mt-1.5 max-w-3xl text-[12.5px] leading-5 text-[#66736d]">Capture every operating cost once, preserve evidence and feed reliable contribution, operating and net-profit calculations.</p></div><div className="flex flex-wrap gap-2"><button onClick={openBudget} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="settings" size={13}/>Budgets &amp; categories</button><button onClick={openEntry} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="plus" size={13}/>Record expense</button></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[["Month-to-date cost","৳4.82L","↑ 6.8%","vs Jul 1–22","text-[#3b646d]"],["Paid","৳3.94L","81.7%","Cash left business","text-emerald-700"],["Payables","৳88,400","7 items","3 due this week","text-rose-700"],["Pending approval","৳56,190","3 requests","1 overdue","text-amber-700"],["Recurring due","6","Next 7 days","৳1.42L planned","text-purple-700"],["Cost coverage","94.3%","↑ 2.1 pp","Profit still provisional","text-sky-700"]].map(([label,value,change,meta,tone])=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between gap-2"><span className="text-[6.5px] font-bold uppercase tracking-[.1em] text-[#89948f]">{label}</span><span className="text-[6px] font-bold text-[#6d7b74]">{change}</span></div><b className={"mt-3 block text-[18px] tracking-[-.03em] "+tone}>{value}</b><p className="mt-2 text-[6.5px] leading-3.5 text-[#929d97]">{meta}</p></article>)}</section>

    <section className="grid gap-4 xl:grid-cols-[minmax(0,1.12fr)_minmax(410px,.88fr)]"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Cost composition</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Where operating money is going</h2><p className="mt-1 text-[7px] text-[#929d97]">Aug 1–22 · excludes product purchase / COGS</p></div><span className="rounded-full bg-[#edf3f4] px-2 py-1 text-[7px] font-bold text-[#3b646d]">৳5.90L forecast</span></div><div className="mt-5 h-4 overflow-hidden rounded-full bg-[#edf0ee]">{categoryMix.map(item=><span key={item[0]} className={"inline-block h-full "+item[3]} style={{width:item[1]+"%"}}/>)}</div><div className="mt-5 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{categoryMix.map(item=><button key={item[0]} onClick={()=>{setCategory(item[0] as string);setView("All expenses")}} className="flex items-center gap-3 rounded-xl border border-[#e7ebe9] p-3 text-left hover:border-[#bfd0cc]"><i className={"h-2.5 w-2.5 rounded-full "+item[3]}/><div className="min-w-0 flex-1"><b className="block text-[8px] text-[#405049]">{item[0]}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">{item[1]}% of cost</span></div><b className="text-[8px] text-[#52615a]">{money(item[2] as number)}</b></button>)}</div></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Approval inbox</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Expenses needing a decision</h2></div><span className="rounded-full bg-amber-50 px-2 py-1 text-[7px] font-bold text-amber-700">{approvals.length} pending</span></div><div className="mt-4 space-y-2">{approvals.map(item=><button key={item.id} onClick={()=>setFocused(item)} className="flex w-full items-center gap-3 rounded-xl border border-[#e7ebe9] p-3 text-left hover:border-[#bfd0cc]"><span className={"flex h-7 w-7 items-center justify-center rounded-lg "+(item.risk==="High"?"bg-rose-50 text-rose-700":"bg-amber-50 text-amber-700")}><Icon name="alert" size={12}/></span><div className="min-w-0 flex-1"><b className="block truncate text-[8px] text-[#405049]">{item.payee} · {money(item.amount+item.tax)}</b><span className="mt-0.5 block truncate text-[6.5px] text-[#929d97]">{item.category} · {item.evidence}</span></div><span className="text-[6px] font-bold text-[#65736c]">{item.due}</span></button>)}</div></article></section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{views.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d]")}>{item}<span className="ml-2 rounded-full bg-[#f1f4f2] px-1.5 py-0.5 text-[6.5px]">{item==="All expenses"?expenseRows.length:item==="Pending approval"?expenseRows.filter(row=>row.status==="Pending").length:item==="Unpaid"?expenseRows.filter(row=>row.payment!=="Paid").length:item==="Recurring"?expenseRows.filter(row=>row.recurring!=="One-time").length:item==="Missing evidence"?2:8}</span></button>)}</div></div>{view!=="Categories"&&<><div className="space-y-3 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:p-5"><div className="flex flex-col gap-2 xl:flex-row"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search expense, payee, description, invoice or linked record..." className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><select value={category} onChange={event=>setCategory(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f]"><option>All categories</option>{Array.from(new Set(expenseRows.map(item=>item.category))).map(item=><option key={item}>{item}</option>)}</select><select value={costCenter} onChange={event=>setCostCenter(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f]"><option>All cost centers</option>{Array.from(new Set(expenseRows.map(item=>item.costCenter))).map(item=><option key={item}>{item}</option>)}</select><select value={payment} onChange={event=>setPayment(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f]"><option>All payment states</option><option>Paid</option><option>Unpaid</option><option>Partial</option><option>Scheduled</option></select></div></div><div className="overflow-x-auto"><table className="w-full min-w-[1650px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Expense / date</th><th className="px-4 py-3.5">Payee</th><th className="px-4 py-3.5">Category / center</th><th className="px-4 py-3.5">Description</th><th className="px-4 py-3.5">Amount</th><th className="px-4 py-3.5">Approval</th><th className="px-4 py-3.5">Payment</th><th className="px-4 py-3.5">Evidence</th><th className="px-4 py-3.5">Source</th><th className="px-4 py-3.5">Linked record</th><th className="w-12 px-4 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{visible.map(item=><tr key={item.id} onClick={()=>setFocused(item)} className="cursor-pointer text-[8px] text-[#5f6e67] hover:bg-[#fafcfb]"><td className="px-5 py-4"><b className="block text-[8.5px] text-[#33423b]">{item.id}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">{item.date} · {item.owner}</span></td><td className="px-4 py-4"><b className="block min-w-[150px] text-[#52615a]">{item.payee}</b><span className="mt-1 block font-mono text-[6.5px] text-[#929d97]">{item.reference}</span></td><td className="px-4 py-4"><b className="block text-[#52615a]">{item.category}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">{item.costCenter}</span></td><td className="px-4 py-4"><span className="block min-w-[220px]">{item.description}</span><small className="mt-1 block text-[6.5px] text-[#929d97]">{item.allocation}</small></td><td className="px-4 py-4"><b className="text-[9px] text-[#405049]">{money(item.amount+item.tax)}</b>{item.tax>0&&<span className="mt-1 block text-[6.5px] text-[#929d97]">Tax {money(item.tax)}</span>}</td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+statusTone(item.status)}>{item.status}</span></td><td className="px-4 py-4"><span className={"inline-flex rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+paymentTone(item.payment)}>{item.payment}</span><span className="mt-1.5 block text-[6.5px] text-[#929d97]">{item.method}</span></td><td className="px-4 py-4">{item.evidence}</td><td className="px-4 py-4">{item.source}</td><td className="px-4 py-4">{item.linked}</td><td className="px-4 py-4"><Icon name="chevron" size={12}/></td></tr>)}</tbody></table>{visible.length===0&&<div className="flex flex-col items-center justify-center px-5 py-14 text-center"><Icon name="check" size={18} className="text-[#83958e]"/><b className="mt-3 text-[9px] text-[#405049]">No expenses match this view</b><button onClick={()=>{setQuery("");setCategory("All categories");setCostCenter("All cost centers");setPayment("All payment states");setView("All expenses")}} className="mt-3 text-[7.5px] font-bold text-[#3b646d]">Clear filters</button></div>}</div></>}{view==="Categories"&&<div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1.15fr)_minmax(340px,.85fr)]"><div className="space-y-3">{monthlyBudget.map(([name,budget,actual])=><div key={name as string} className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between"><div><b className="block text-[8.5px] text-[#405049]">{name as string}</b><span className="mt-1 block text-[6.5px] text-[#929d97]">Actual {money(actual as number)} · Budget {money(budget as number)}</span></div><b className="text-[8px] text-[#52615a]">{Math.round((actual as number)/(budget as number)*100)}%</b></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[#e8ecea]"><div className="h-full rounded-full bg-[#6f9692]" style={{width:Math.min(100,(actual as number)/(budget as number)*100)+"%"}}/></div></div>)}</div><aside className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Expense taxonomy</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">Every category maps to a financial statement line and a cost-allocation rule. Renaming labels must not break historical reporting.</p><div className="mt-4 space-y-2">{[["Direct fulfilment","Packaging · Courier"],["Growth","Advertising · Content"],["Operating expense","Salary · Rent · Software"],["Non-cash loss","Damage · Write-off"]].map(item=><div key={item[0]} className="rounded-lg bg-white p-3"><b className="block text-[7.5px] text-[#405049]">{item[0]}</b><span className="mt-1 block text-[6.5px] text-[#87928d]">{item[1]}</span></div>)}</div></aside></div>}</section>

    <section className="grid gap-4 xl:grid-cols-[minmax(0,1.1fr)_minmax(380px,.9fr)]"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Budget control</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Monthly budget vs actual</h2></div><button onClick={()=>setView("Categories")} className="text-[7px] font-bold text-[#3b646d]">Manage budgets →</button></div><div className="mt-4 space-y-3">{monthlyBudget.map(([name,budget,actual])=><div key={name as string} className="grid grid-cols-[95px_1fr_82px] items-center gap-3"><b className="truncate text-[7px] text-[#52615a]">{name as string}</b><div className="h-2 overflow-hidden rounded-full bg-[#edf0ee]"><div className={"h-full rounded-full "+((actual as number)/(budget as number)>.95?"bg-amber-500":"bg-[#6f9692]")} style={{width:Math.min(100,(actual as number)/(budget as number)*100)+"%"}}/></div><span className="text-right text-[6.5px] font-bold text-[#65736c]">{money(actual as number)} / {money(budget as number)}</span></div>)}</div></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4 sm:p-5"><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5e7875]">Profitability data quality</p><h2 className="mt-1 text-[14px] font-bold text-[#304d4d]">5.7% of operating cost is still estimated</h2><div className="mt-4 grid grid-cols-3 gap-2">{[["Courier","98%"],["Ad spend","100%"],["Packaging","82%"]].map(item=><div key={item[0]} className="rounded-xl bg-white p-3"><span className="text-[6px] text-[#82928c]">{item[0]}</span><b className="mt-1 block text-[10px] text-[#405b58]">{item[1]}</b></div>)}</div><p className="mt-4 text-[7px] leading-4 text-[#647b77]">Until evidence and allocation reach full coverage, operating and net profit must remain clearly marked provisional.</p><button onClick={()=>onNavigate("Reports & Insights")} className="mt-4 h-9 w-full rounded-xl bg-white text-[7.5px] font-bold text-[#3b646d] ring-1 ring-[#d1ddda]">Open profitability reporting</button></article></section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Single source</p><b className="mt-1.5 block text-[10px] text-[#405049]">Synced costs must not be entered twice</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">Use provider IDs, date, amount and fingerprints to stop duplicate courier, ad and subscription expenses.</p></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Approvals</p><b className="mt-1.5 block text-[10px] text-[#405049]">Entry, approval and payment stay separate</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">Financial release requires permission, supporting evidence and a reason—never only a status change.</p></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5e7875]">Implementation truth</p><b className="mt-1.5 block text-[10px] text-[#304d4d]">This workspace needs finance backend work</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">Connect provider sync, bills, evidence storage, approvals, payment reconciliation, allocation rules, budgets and audit logs.</p></article></section>

    {focused&&<div className="fixed inset-0 z-[80] bg-[#17231f]/25 backdrop-blur-[1px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-xl overflow-y-auto bg-white shadow-[-24px_0_70px_rgba(18,37,31,.16)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><div className="flex items-center gap-2"><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+statusTone(focused.status)}>{focused.status}</span><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+paymentTone(focused.payment)}>{focused.payment}</span></div><h2 className="mt-2 text-[17px] font-bold leading-6 text-[#23322b]">{focused.payee}</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused.id} · {focused.reference} · {focused.date}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid grid-cols-4 gap-2">{[["Amount",money(focused.amount)],["Tax",money(focused.tax)],["Category",focused.category],["Center",focused.costCenter]].map(item=><div key={item[0]} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1.5 block truncate text-[8px] text-[#405049]">{item[1]}</b></div>)}</div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Business purpose</b><p className="mt-2 text-[7.5px] leading-4 text-[#647b77]">{focused.description}</p></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Accounting and payment context</b><div className="mt-3 divide-y divide-[#edf0ee]">{[["Source",focused.source],["Payment method",focused.method],["Due / paid",focused.due],["Recurring",focused.recurring],["Cost allocation",focused.allocation]].map(item=><div key={item[0]} className="grid grid-cols-[120px_1fr] gap-3 py-2.5 text-[7px]"><span className="text-[#929d97]">{item[0]}</span><b className="text-[#52615a]">{item[1]}</b></div>)}</div></div><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4"><b className="text-[8px] text-emerald-800">Evidence</b><p className="mt-2 text-[7px] leading-4 text-emerald-700">{focused.evidence}</p></div><div className="rounded-xl border border-sky-200 bg-sky-50 p-4"><b className="text-[8px] text-sky-800">Profitability link</b><p className="mt-2 text-[7px] leading-4 text-sky-700">{focused.linked}</p></div></div><div className="rounded-xl border border-[#e2e8e5] p-4"><div className="flex items-center justify-between"><b className="text-[8px] text-[#405049]">Audit timeline</b><span className="text-[6.5px] font-bold text-[#3b646d]">Append-only</span></div><div className="mt-3 space-y-3">{focused.audit.map((item,index)=><div key={item} className="flex gap-3"><span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#edf3f4] text-[6px] font-bold text-[#3b646d]">{index+1}</span><p className="text-[7px] leading-5 text-[#65736c]">{item}</p></div>)}</div></div><div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-[7px] leading-4 text-amber-800"><b>Guardrail:</b> approving an expense does not release payment. Payment posting must match a bank, cash, card or provider reference.</div></div><footer className="sticky bottom-0 grid grid-cols-3 gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur"><button onClick={openEvidence} className="h-10 rounded-xl border border-[#dce4e0] text-[8px] font-bold text-[#596962]">Add evidence</button><button onClick={openApproval} className="h-10 rounded-xl border border-[#bfd0cc] bg-[#edf3f4] text-[8px] font-bold text-[#3b646d]">Review</button><button onClick={openPayment} className="h-10 rounded-xl bg-[#3b646d] text-[8px] font-bold text-white">Record payment</button></footer></aside></div>}
    {entryOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setEntryOpen(false)}}><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Evidence-backed finance entry</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Record operating expense</h2><p className="mt-1 text-[7.5px] leading-4 text-[#87928d]">Capture the business purpose, accounting category, allocation and payment state once.</p></div><button onClick={()=>setEntryOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="grid gap-4 p-5 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#596962]">Vendor / payee<input value={entryPayee} onChange={event=>setEntryPayee(event.target.value)} placeholder="Company or person paid" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Expense date<input type="date" value={entryDate} onChange={event=>setEntryDate(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Category<select value={entryCategory} onChange={event=>setEntryCategory(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Packaging</option><option>Courier</option><option>Advertising</option><option>Salary</option><option>Rent &amp; utilities</option><option>Software</option><option>Content production</option><option>Transport</option><option>Damage &amp; write-off</option><option>Other</option></select></label><label className="text-[7px] font-bold text-[#596962]">Cost center<select value={entryCenter} onChange={event=>setEntryCenter(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Fulfilment</option><option>Growth</option><option>Operations</option><option>Administration</option><option>Inventory</option><option>Purchasing</option></select></label><label className="text-[7px] font-bold text-[#596962]">Amount (before tax)<input type="number" value={entryAmount} onChange={event=>setEntryAmount(event.target.value)} placeholder="0" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Tax / VAT<input type="number" value={entryTax} onChange={event=>setEntryTax(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Payment state<select value={entryPayment} onChange={event=>setEntryPayment(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Unpaid</option><option>Paid</option><option>Partial</option><option>Scheduled</option></select></label><label className="text-[7px] font-bold text-[#596962]">Expected payment method<select value={entryMethod} onChange={event=>setEntryMethod(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Bank transfer</option><option>bKash business</option><option>Corporate card</option><option>Cash</option><option>Courier settlement</option><option>Non-cash write-off</option></select></label><label className="text-[7px] font-bold text-[#596962]">Invoice / claim reference<input value={entryReference} onChange={event=>setEntryReference(event.target.value)} placeholder="Supplier invoice or provider ID" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Cost allocation<select value={entryAllocation} onChange={event=>setEntryAllocation(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Cost center only</option><option>Allocate to orders</option><option>Allocate to products</option><option>Allocate to campaigns</option><option>Split across centers</option></select></label><label className="sm:col-span-2 text-[7px] font-bold text-[#596962]">Business purpose<textarea value={entryPurpose} onChange={event=>setEntryPurpose(event.target.value)} placeholder="What was purchased, why it was needed and what business activity it supports..." className="mt-2 min-h-20 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4"/></label><label className="sm:col-span-2 flex items-center justify-between rounded-xl border border-[#e2e8e5] p-3"><span><b className="block text-[7.5px] text-[#405049]">Create recurring schedule</b><small className="mt-1 block text-[6.5px] text-[#929d97]">Future drafts still require matching evidence and applicable approval.</small></span><input type="checkbox" checked={entryRecurring} onChange={event=>setEntryRecurring(event.target.checked)} className="h-4 w-4 accent-[#3b646d]"/></label><div className="sm:col-span-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-[7px] leading-4 text-amber-800"><b>Duplicate guard:</b> production checks payee, date, amount, provider ID and invoice reference before saving. Synced Meta or courier costs should never be entered manually again.</div><label className="sm:col-span-2 flex items-start gap-2 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={entryConfirmed} onChange={event=>setEntryConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/>I verified the payee, amount, category and business purpose. This creates an expense record, not an automatic payment.</label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setEntryOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!entryPayee.trim()||!entryAmount||Number(entryAmount)<=0||!entryReference.trim()||!entryPurpose.trim()||!entryConfirmed} onClick={()=>{setEntryOpen(false);showNotice("Expense draft recorded for evidence and approval checks.")}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Record expense draft</button></footer></div></div>}

    {approvalOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setApprovalOpen(false)}}><div className="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Independent review</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Review {focused?.id||"expense"}</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Approval confirms validity and accounting treatment—not payment release.</p></div><button onClick={()=>setApprovalOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid grid-cols-3 gap-2">{[["Payee",focused?.payee||"—"],["Total",money((focused?.amount||0)+(focused?.tax||0))],["Budget line",focused?.category||"—"]].map(item=><div key={item[0]} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1 block truncate text-[8px] text-[#405049]">{item[1]}</b></div>)}</div><div className="grid gap-2 sm:grid-cols-3">{[["Evidence",focused?.evidence||"Pending","text-emerald-700"],["Duplicate check","No exact match","text-emerald-700"],["Budget impact","Within current limit","text-amber-700"]].map(item=><div key={item[0]} className="rounded-xl bg-[#fafbfa] p-3"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className={"mt-1 block text-[7.5px] "+item[2]}>{item[1]}</b></div>)}</div><label className="text-[7px] font-bold text-[#596962]">Decision<select value={approvalDecision} onChange={event=>{setApprovalDecision(event.target.value);setApprovalConfirmed(false)}} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Approve expense</option><option>Request changes</option><option>Reject expense</option></select></label><label className="block text-[7px] font-bold text-[#596962]">Decision reason<textarea value={approvalReason} onChange={event=>setApprovalReason(event.target.value)} placeholder="Why is this decision appropriate?" className="mt-2 min-h-24 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4"/></label><div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-[7px] leading-4 text-amber-800"><b>Separation of duties:</b> an approver should not approve their own high-value entry. Approving does not mark the expense paid or move money.</div><label className="flex items-start gap-2 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={approvalConfirmed} onChange={event=>setApprovalConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/>I reviewed the evidence, accounting category, duplicate signal and budget impact.</label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setApprovalOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!approvalReason.trim()||!approvalConfirmed} onClick={()=>{setApprovalOpen(false);showNotice(`${approvalDecision} recorded with reviewer evidence.`)}} className={"h-10 rounded-xl px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40 "+(approvalDecision==="Reject expense"?"bg-rose-700":"bg-[#3b646d]")}>Record decision</button></footer></div></div>}

    {paymentOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setPaymentOpen(false)}}><div className="w-full max-w-xl overflow-hidden rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Reconciled payment posting</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Record expense payment</h2><p className="mt-1 text-[7.5px] text-[#87928d]">A payment reference is required so Finance can match the actual cash movement.</p></div><button onClick={()=>setPaymentOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="grid gap-4 p-5 sm:grid-cols-2"><div className="sm:col-span-2 grid grid-cols-3 gap-2 rounded-xl border border-[#e2e8e5] p-3">{[["Expense",focused?.id||"—"],["Payee",focused?.payee||"—"],["Outstanding",money((focused?.amount||0)+(focused?.tax||0))]].map(item=><div key={item[0]}><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1 block truncate text-[8px] text-[#405049]">{item[1]}</b></div>)}</div><label className="text-[7px] font-bold text-[#596962]">Amount paid<input type="number" value={paymentAmount} onChange={event=>setPaymentAmount(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Payment date<input type="date" value={paymentDate} onChange={event=>setPaymentDate(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Payment method<select value={paymentMethod} onChange={event=>setPaymentMethod(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Bank transfer</option><option>bKash business</option><option>Corporate card</option><option>Cash</option><option>Courier settlement</option><option>Non-cash write-off</option></select></label><label className="text-[7px] font-bold text-[#596962]">Transaction / statement reference<input value={paymentReference} onChange={event=>setPaymentReference(event.target.value)} placeholder="Required immutable reference" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><div className="sm:col-span-2 rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-3 text-[7px] leading-4 text-[#647b77]"><b>Reconciliation rule:</b> production matches amount, date, method, payee and transaction reference against bank/card/wallet/provider statements. A manual record remains unverified until matched.</div><label className="sm:col-span-2 flex items-start gap-2 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={paymentConfirmed} onChange={event=>setPaymentConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/>I verified the actual payment reference and understand this changes cash reporting.</label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setPaymentOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!paymentAmount||Number(paymentAmount)<=0||!paymentReference.trim()||!paymentConfirmed} onClick={()=>{setPaymentOpen(false);showNotice(`${money(Number(paymentAmount))} payment posted for reconciliation.`)}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Post payment record</button></footer></div></div>}

    {budgetOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setBudgetOpen(false)}}><div className="w-full max-w-xl overflow-hidden rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Versioned finance control</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Update category budget</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Budgets guide decisions; they never rewrite historical expenses.</p></div><button onClick={()=>setBudgetOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="grid gap-4 p-5 sm:grid-cols-2"><label className="text-[7px] font-bold text-[#596962]">Category<select value={budgetCategory} onChange={event=>{setBudgetCategory(event.target.value);setBudgetAmount(event.target.value==="Advertising"?"200000":event.target.value==="Salary"?"150000":"100000")}} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Advertising</option><option>Salary</option><option>Courier</option><option>Packaging</option><option>Operations</option></select></label><label className="text-[7px] font-bold text-[#596962]">Monthly budget<input type="number" value={budgetAmount} onChange={event=>setBudgetAmount(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="text-[7px] font-bold text-[#596962]">Warning threshold<select value={budgetAlert} onChange={event=>setBudgetAlert(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>75%</option><option>80%</option><option>90%</option><option>100%</option></select></label><div className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">Effective period</span><b className="mt-1 block text-[8px] text-[#405049]">September 2026 forward</b><small className="mt-1 block text-[6.5px] text-[#929d97]">August remains unchanged</small></div><label className="sm:col-span-2 text-[7px] font-bold text-[#596962]">Reason for change<textarea value={budgetReason} onChange={event=>setBudgetReason(event.target.value)} placeholder="Forecast, operating plan or approved business reason..." className="mt-2 min-h-20 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4"/></label><div className="sm:col-span-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-[7px] leading-4 text-amber-800"><b>Boundary:</b> a budget breach creates alerts and approval escalation; it must not silently block legally due or safety-critical payments.</div><label className="sm:col-span-2 flex items-start gap-2 text-[7px] leading-4 text-[#65736c]"><input type="checkbox" checked={budgetConfirmed} onChange={event=>setBudgetConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/>Submit this as a future budget version with the current budget preserved until approval.</label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setBudgetOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!budgetAmount||Number(budgetAmount)<=0||!budgetReason.trim()||!budgetConfirmed} onClick={()=>{setBudgetOpen(false);showNotice(`${budgetCategory} budget request submitted for approval.`)}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Submit budget request</button></footer></div></div>}

    {evidenceOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setEvidenceOpen(false)}}><div className="w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Document evidence</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Attach expense evidence</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused?.id} · original file, actor and timestamp are preserved.</p></div><button onClick={()=>setEvidenceOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><label className="block text-[7px] font-bold text-[#596962]">Document type<select value={evidenceType} onChange={event=>setEvidenceType(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Supplier invoice</option><option>Payment receipt</option><option>Provider statement</option><option>Delivery / receiving proof</option><option>Approval document</option><option>Other evidence</option></select></label><label className="block text-[7px] font-bold text-[#596962]">Document reference<input value={evidenceReference} onChange={event=>setEvidenceReference(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px]"/></label><label className="flex cursor-pointer flex-col items-center rounded-xl border border-dashed border-[#bfcfca] bg-[#fafcfb] p-6 text-center"><Icon name="upload" size={18} className="text-[#3b646d]"/><b className="mt-2 text-[8px] text-[#405049]">{evidenceFile||"Choose PDF, JPG or PNG"}</b><span className="mt-1 text-[6.5px] text-[#929d97]">Original file retained · virus scan required in production</span><input type="file" accept=".pdf,.jpg,.jpeg,.png" className="hidden" onChange={event=>setEvidenceFile(event.target.files?.[0]?.name||"")}/></label><label className="block text-[7px] font-bold text-[#596962]">Evidence note<textarea value={evidenceNote} onChange={event=>setEvidenceNote(event.target.value)} placeholder="What does this document prove?" className="mt-2 min-h-20 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4"/></label><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-3 text-[7px] leading-4 text-[#647b77]">Production storage needs access control, encryption, retention policy, file hash and an append-only audit event.</div></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setEvidenceOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!evidenceReference.trim()||!evidenceFile||!evidenceNote.trim()} onClick={()=>{setEvidenceOpen(false);showNotice(`${evidenceType} attached to the expense evidence set.`)}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Attach evidence</button></footer></div></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

type AISignalSeverity="Critical"|"High"|"Medium"|"Low";
type AIActionStatus="New"|"In review"|"Accepted"|"Done";
type AIActionRow={id:string;title:string;domain:string;question:string;why:string;signal:string;impact:string;owner:string;due:string;confidence:number;severity:AISignalSeverity;status:AIActionStatus;recommendation:string;evidence:string[];steps:string[];guardrail:string;sourcePage:string;updated:string};

const aiActions:AIActionRow[]=[
  {id:"AI-PRI-2208-01",title:"Resolve ৳18,420 COD mismatch",domain:"Finance",question:"Is expected COD missing or only delayed?",why:"Steadfast settlement is below expected receivables and two remittances are not matched.",signal:"Expected ৳142,680 · received ৳124,260 · gap ৳18,420",impact:"Protect cash visibility and prevent an incorrect settlement close.",owner:"Nadia · Finance",due:"38m SLA",confidence:98,severity:"Critical",status:"New",recommendation:"Review the two unmatched consignments and courier statement before approving any adjustment.",evidence:["Settlement SET-STD-2208","160 consignments matched","Two delayed remittance references","Courier statement imported 09:12"],steps:["Open COD exceptions","Match delayed remittances","Request courier clarification if still unmatched","Owner approves only verified adjustment"],guardrail:"AI cannot approve a settlement adjustment or change receivables.",sourcePage:"Finance Reconciliation",updated:"8 min ago"},
  {id:"AI-PRI-2208-02",title:"Review loss-making Vitamin C campaign",domain:"Growth",question:"Should budget continue at the current level?",why:"Delivered profit is negative although platform engagement remains acceptable.",signal:"Delivered net profit −৳10,525 · margin −33.4%",impact:"Avoid roughly ৳660/day of continuing delivered-profit loss.",owner:"Growth",due:"Today · 2 PM",confidence:95,severity:"Critical",status:"New",recommendation:"Inspect creative, delivered conversion and refusal rate; prepare a budget reduction decision for human approval.",evidence:["Campaign CMP-VC-AWR","42 delivered orders","Meta spend ৳19,840","Delivered economics coverage 95%"],steps:["Open campaign economics","Compare ordered vs delivered ROAS","Inspect refusal and return cohort","Owner decides budget action"],guardrail:"AI cannot pause, edit or increase campaign budgets automatically.",sourcePage:"Meta Ads",updated:"11 min ago"},
  {id:"AI-PRI-2208-03",title:"Reorder Kojic Body Wash before stockout",domain:"Inventory",question:"How much stock is needed for the next purchase cycle?",why:"Current sell-through leaves only eight days of cover while supplier lead time is eleven days.",signal:"34 available · 4.2/day velocity · 11-day lead time",impact:"Prevent an estimated ৳38,000–৳54,000 in lost delivered revenue.",owner:"Rafi · Inventory",due:"Today · 4 PM",confidence:93,severity:"High",status:"In review",recommendation:"Prepare a purchase recommendation for 96 units, then confirm cash and supplier availability.",evidence:["SKU BW-KOJ-300","30D delivered sales 126 units","Supplier lead time 11 days","Open PO quantity 0"],steps:["Validate demand forecast","Confirm supplier availability","Review cash requirement","Human creates and approves PO"],guardrail:"AI cannot create or approve a purchase order or commit supplier payment.",sourcePage:"Inventory",updated:"18 min ago"},
  {id:"AI-PRI-2208-04",title:"Verify six high-return-risk orders",domain:"Orders",question:"Which orders need a confirmation call before packing?",why:"Customer history and address signals indicate a higher refusal probability.",signal:"6 orders · ৳5,940 COD value · expected loss exposure ৳760",impact:"Reduce avoidable courier return loss without blocking good customers.",owner:"Maliha · Operations",due:"56m SLA",confidence:88,severity:"High",status:"New",recommendation:"Call the six customers using the approved verification script; do not cancel solely on the risk score.",evidence:["Repeat refusal history","Unverified address tokens","Duplicate phone/address cluster","Order risk model v2"],steps:["Open verification queue","Call customer","Record confirmation evidence","Human decides hold, confirm or cancel"],guardrail:"Risk signals cannot auto-cancel, discriminate or permanently label a customer.",sourcePage:"Orders",updated:"23 min ago"},
  {id:"AI-PRI-2208-05",title:"Fix packaging cost evidence gap",domain:"Finance",question:"Is operating profit understated or overstated?",why:"Packaging allocation has only 82% evidence coverage because receiving confirmation is missing.",signal:"৳24,680 bill · invoice present · receiving evidence missing",impact:"Raise profitability coverage from 94.3% to approximately 97.8%.",owner:"Rafi + Nadia",due:"Today",confidence:96,severity:"High",status:"Accepted",recommendation:"Verify receiving against PO-2608-034 and attach evidence before approving the bill.",evidence:["Expense EXP-260822-116","Invoice PPB-INV-8841","PO-2608-034","Receiving record not found"],steps:["Check warehouse receiving","Match quantity and condition","Attach receiving proof","Finance reviews expense"],guardrail:"AI cannot approve the supplier bill or infer missing receiving evidence as complete.",sourcePage:"Expenses & Cost Management",updated:"31 min ago"},
  {id:"AI-PRI-2208-06",title:"Investigate packing mismatch trend",domain:"Fulfilment",question:"Why did wrong or missing item cases increase?",why:"Three cases in two days share the same packing shift and station.",signal:"Packing error rate 2.8% vs 1.1% baseline",impact:"Reduce exchange courier cost and protect customer trust.",owner:"Maliha",due:"Tomorrow",confidence:84,severity:"Medium",status:"New",recommendation:"Review scan evidence and station logs; retrain only if the operational cause is confirmed.",evidence:["Return cases RET-260821-037 and related","Packing station P-02","Shift 2 concentration","Baseline last 30 days"],steps:["Review pack-scan sequence","Check station/device issues","Speak with shift lead","Create corrective action if confirmed"],guardrail:"AI cannot assign blame or discipline staff from an anomaly alone.",sourcePage:"Packing Desk",updated:"42 min ago"},
  {id:"AI-PRI-2208-07",title:"Recover high-LTV customers due to reorder",domain:"Customers",question:"Who is most likely to reorder this week?",why:"Twenty-three repeat customers are inside their normal replenishment window.",signal:"23 customers · estimated ৳18,700 revenue opportunity",impact:"Grow repeat revenue with lower acquisition cost.",owner:"CRM",due:"This week",confidence:81,severity:"Medium",status:"In review",recommendation:"Prepare a consent-aware reminder segment; review message and offer before sending.",evidence:["Purchase interval history","Last delivered product","Consent and contactability state","No unresolved complaint"],steps:["Review customer segment","Exclude open complaint cases","Approve message and offer","Human schedules campaign"],guardrail:"AI cannot send marketing messages or expose personal data without permission and review.",sourcePage:"Retention / AOV / CLV",updated:"1h ago"},
  {id:"AI-PRI-2208-08",title:"Validate Salicylic Serum cost fallback",domain:"Catalog",question:"Is the SKU truly unprofitable?",why:"Seven percent of fulfilment cost is estimated and current net margin is −0.8%.",signal:"Net profit −৳570 · cost coverage 93%",impact:"Prevent a pricing or campaign decision based on incomplete cost data.",owner:"Catalog + Finance",due:"2 days",confidence:79,severity:"Low",status:"New",recommendation:"Confirm packaging and courier allocation before changing price or promotion.",evidence:["Product PRD-SER-SAL","COGS confirmed","Fulfilment allocation partially estimated","Profit definition v4"],steps:["Verify missing cost pool","Recalculate open-period margin","Compare with price floor","Human reviews action"],guardrail:"AI cannot change price, promotion or product visibility.",sourcePage:"Profitability Control",updated:"2h ago"},
];

function AIBusinessAssistantWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [view,setView]=useState<"Daily brief"|"Priorities"|"Anomalies"|"Ask AI"|"Decisions"|"Data confidence">("Daily brief");
  const [severity,setSeverity]=useState("All severity");
  const [domain,setDomain]=useState("All domains");
  const [query,setQuery]=useState("");
  const [focused,setFocused]=useState<AIActionRow|null>(null);
  const [ask,setAsk]=useState("");
  const [answer,setAnswer]=useState("");
  const [notice,setNotice]=useState("");
  const [configureOpen,setConfigureOpen]=useState(false);
  const [briefTime,setBriefTime]=useState("08:30");
  const [briefDays,setBriefDays]=useState(["Sun","Mon","Tue","Wed","Thu","Sat"]);
  const [briefChannel,setBriefChannel]=useState("In-admin + email");
  const [briefRecipients,setBriefRecipients]=useState("Owner");
  const [briefReason,setBriefReason]=useState("");
  const [briefConfirmed,setBriefConfirmed]=useState(false);
  const [taskOpen,setTaskOpen]=useState(false);
  const [taskTitle,setTaskTitle]=useState("");
  const [taskOwner,setTaskOwner]=useState("Owner");
  const [taskDue,setTaskDue]=useState("Today · 4 PM");
  const [taskPriority,setTaskPriority]=useState("High");
  const [taskNote,setTaskNote]=useState("");
  const [taskConfirmed,setTaskConfirmed]=useState(false);
  const [reviewOpen,setReviewOpen]=useState(false);
  const [reviewDecision,setReviewDecision]=useState("Accept for review");
  const [reviewReason,setReviewReason]=useState("");
  const [reviewConfirmed,setReviewConfirmed]=useState(false);
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const openConfigure=()=>{setBriefReason("");setBriefConfirmed(false);setConfigureOpen(true)};
  const openTask=()=>{setTaskTitle(focused?.title||"AI recommendation review");setTaskOwner(focused?.owner||"Owner");setTaskNote("");setTaskConfirmed(false);setTaskOpen(true)};
  const openReview=()=>{setReviewDecision("Accept for review");setReviewReason("");setReviewConfirmed(false);setReviewOpen(true)};
  const severityTone=(value:AISignalSeverity)=>value==="Critical"?"bg-rose-100 text-rose-800 ring-rose-300":value==="High"?"bg-orange-50 text-orange-700 ring-orange-200":value==="Medium"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-slate-100 text-slate-600 ring-slate-200";
  const statusTone=(value:AIActionStatus)=>value==="Done"?"bg-emerald-50 text-emerald-700 ring-emerald-200":value==="Accepted"?"bg-sky-50 text-sky-700 ring-sky-200":value==="In review"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-[#edf3f4] text-[#3b646d] ring-[#cbdcda]";
  const visible=aiActions.filter(item=>(severity==="All severity"||item.severity===severity)&&(domain==="All domains"||item.domain===domain)&&(item.id+" "+item.title+" "+item.question+" "+item.signal+" "+item.owner).toLowerCase().includes(query.toLowerCase()));
  const views=["Daily brief","Priorities","Anomalies","Ask AI","Decisions","Data confidence"] as const;
  const askAI=(prompt?:string)=>{const value=(prompt||ask).trim();if(!value)return;setAsk(value);const lower=value.toLowerCase();setAnswer(lower.includes("profit")||lower.includes("লাভ")?"Delivered revenue is up 11.6%, but operating margin is only 6.5%. The biggest drags are Messenger return loss, the Vitamin C awareness campaign and incomplete packaging-cost evidence. I would review those three items before scaling spend.":lower.includes("stock")||lower.includes("reorder")?"Kojic Body Wash is the clearest stock risk: 34 units available, roughly 8 days of cover, versus an 11-day supplier lead time. The current recommendation is to review a 96-unit purchase plan; cash and supplier availability still need human confirmation.":lower.includes("cod")||lower.includes("cash")?"COD receivables show a ৳18,420 Steadfast mismatch. Two delayed remittance references explain most of the gap, but Finance should match them before any settlement adjustment is approved.":"Today I would prioritize: resolve the COD mismatch, review the loss-making Vitamin C campaign, verify six high-return-risk orders, and complete packaging receiving evidence. These recommendations are based on the current demo evidence set and require human review.")};
  const anomalyRows=[["COD settlement gap","Finance","৳18,420 above normal tolerance","Critical","8 min"],["Messenger profit turned negative","Growth","−2.0% delivered net margin","Critical","11 min"],["Body Wash stock cover","Inventory","8 days cover vs 11-day lead time","High","18 min"],["Packing mismatch rate","Fulfilment","2.8% vs 1.1% baseline","Medium","42 min"],["Vitamin C return rate","Product","8.0% vs 4.6% store baseline","High","1h"],["Packaging cost coverage","Finance","82% evidence coverage","Medium","2h"]];
  const decisions=[["DEC-2208-14","COD adjustment held","Farhan Rahman","Awaiting courier evidence","Today 10:18"],["DEC-2208-13","Acne retargeting budget review accepted","Farhan Rahman","Task assigned to Growth","Today 09:42"],["DEC-2208-12","Stock reorder recommendation accepted","Rafi Hasan","PO draft requested · not approved","Today 09:18"],["DEC-2108-29","VIP reminder segment dismissed","Farhan Rahman","Message offer needs revision","Yesterday 18:36"]];
  const confidenceRows=[["Orders & delivery","99%","Fresh 4m","Healthy"],["Finance & COD","97%","Fresh 8m","2 exceptions"],["Inventory","96%","Fresh 12m","3 count gaps"],["Marketing spend","100%","Fresh 3h","Healthy"],["Attribution","91%","Fresh 15m","CAPI match gap"],["Expenses / OPEX","94%","Fresh 31m","6% estimated"],["Customer intelligence","88%","Fresh 1h","Consent coverage"]];
  return <div className="space-y-5">
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">AI chief of staff</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">AI Business Assistant</h1><p className="mt-1.5 max-w-3xl text-[12.5px] leading-5 text-[#66736d]">Turn connected business data into a calm daily brief, evidence-backed priorities and human-owned decisions.</p></div><div className="flex flex-wrap gap-2"><button onClick={openConfigure} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="settings" size={13}/>Configure brief</button><button onClick={()=>{setView("Ask AI");setTimeout(()=>setAsk("What needs my attention today?"),0)}} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white"><Icon name="message" size={13}/>Ask the assistant</button></div></section>

    <section className="rounded-2xl border border-[#cfdedb] bg-[linear-gradient(135deg,#edf3f4_0%,#f8faf9_62%,#fff_100%)] p-5 sm:p-6"><div className="grid gap-5 xl:grid-cols-[minmax(0,1.35fr)_minmax(330px,.65fr)]"><div><div className="flex items-center gap-2"><span className="rounded-full bg-white px-2.5 py-1 text-[7px] font-bold text-[#3b646d] ring-1 ring-[#d6e2df]">Saturday · 22 Aug · 10:46 AM</span><span className="rounded-full bg-amber-50 px-2.5 py-1 text-[7px] font-bold text-amber-700 ring-1 ring-amber-200">4 urgent decisions</span></div><h2 className="mt-4 text-[19px] font-bold tracking-[-.025em] text-[#29423f]">Good morning. Sales are growing, but profit needs attention.</h2><p className="mt-2 max-w-3xl text-[9px] leading-5 text-[#627873]">Delivered revenue is <b className="text-emerald-700">11.6% ahead</b> of the previous period. Operating margin remains <b className="text-amber-700">6.5%</b> because Messenger returns, one loss-making campaign and incomplete packaging costs are absorbing the gain. COD has an unresolved <b className="text-rose-700">৳18,420 mismatch</b>.</p><div className="mt-4 flex flex-wrap gap-2">{[["Best signal","Website margin 19.8%","text-emerald-700"],["Biggest risk","Messenger margin −2.0%","text-rose-700"],["Fastest win","Packaging evidence gap","text-amber-700"]].map(item=><div key={item[0]} className="rounded-xl bg-white px-3 py-2 ring-1 ring-[#dfe7e4]"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className={"ml-2 text-[7px] "+item[2]}>{item[1]}</b></div>)}</div></div><aside className="rounded-2xl border border-white/80 bg-white/85 p-4 shadow-sm"><div className="flex items-center justify-between"><div><span className="text-[7px] font-bold uppercase tracking-[.12em] text-[#84908a]">Business readiness</span><b className="mt-1 block text-[24px] text-[#304d4d]">78<span className="text-[12px] text-[#82928c]">/100</span></b></div><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#edf3f4] text-[#3b646d]"><Icon name="command" size={18}/></span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-[#e8ecea]"><div className="h-full w-[78%] rounded-full bg-[#5f8585]"/></div><div className="mt-4 grid grid-cols-3 gap-2 text-center">{[["Data","94%"],["SLA","81%"],["Risk","4 open"]].map(item=><div key={item[0]} className="rounded-xl bg-[#fafbfa] p-2.5"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1 block text-[8px] text-[#405049]">{item[1]}</b></div>)}</div></aside></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[["Delivered revenue","৳12.48L","↑ 11.6%","30D matured orders","text-[#3b646d]"],["Operating profit","৳81,000","6.5% margin","94.3% cost coverage","text-emerald-700"],["Orders needing action","11","6 verification","5 fulfilment","text-amber-700"],["COD attention","৳18,420","2 references","Settlement gap","text-rose-700"],["Stock at risk","3 SKUs","1 urgent reorder","8 days cover","text-purple-700"],["AI recommendations","8","4 high priority","0 auto-executed","text-sky-700"]].map(([label,value,change,meta,tone])=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between gap-2"><span className="text-[6.5px] font-bold uppercase tracking-[.1em] text-[#89948f]">{label}</span><span className="text-[6px] font-bold text-[#6d7b74]">{change}</span></div><b className={"mt-3 block text-[18px] tracking-[-.03em] "+tone}>{value}</b><p className="mt-2 text-[6.5px] leading-3.5 text-[#929d97]">{meta}</p></article>)}</section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="border-b border-[#e8ecea] px-4 pt-4 sm:px-5"><div className="flex gap-1 overflow-x-auto">{views.map(item=><button key={item} onClick={()=>setView(item)} className={"whitespace-nowrap border-b-2 px-3 pb-3 text-[8.5px] font-bold "+(view===item?"border-[#3b646d] text-[#3b646d]":"border-transparent text-[#87928d]")}>{item}<span className="ml-2 rounded-full bg-[#f1f4f2] px-1.5 py-0.5 text-[6.5px]">{item==="Daily brief"?4:item==="Priorities"?aiActions.length:item==="Anomalies"?anomalyRows.length:item==="Ask AI"?"AI":item==="Decisions"?decisions.length:7}</span></button>)}</div></div>{(view==="Daily brief"||view==="Priorities")&&<><div className="flex flex-col gap-2 border-b border-[#e8ecea] bg-[#fbfcfb] p-4 sm:flex-row sm:p-5"><label className="relative min-w-0 flex-1"><Icon name="search" size={14} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search priority, signal, owner or business question..." className="h-10 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[9px] font-medium text-[#405049] outline-none focus:border-[#9eb7b4]"/></label><select value={severity} onChange={event=>setSeverity(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f]"><option>All severity</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select><select value={domain} onChange={event=>setDomain(event.target.value)} className="h-10 rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] font-bold text-[#58675f]"><option>All domains</option>{Array.from(new Set(aiActions.map(item=>item.domain))).map(item=><option key={item}>{item}</option>)}</select></div><div className="grid gap-3 p-4 sm:p-5 lg:grid-cols-2">{visible.map(item=><button key={item.id} onClick={()=>setFocused(item)} className="rounded-2xl border border-[#e2e8e5] p-4 text-left hover:border-[#9eb7b4] hover:shadow-sm"><div className="flex items-start gap-3"><span className={"flex h-9 w-9 shrink-0 items-center justify-center rounded-xl "+(item.severity==="Critical"?"bg-rose-50 text-rose-700":item.severity==="High"?"bg-orange-50 text-orange-700":"bg-[#edf3f4] text-[#3b646d]")}><Icon name={item.domain==="Finance"?"finance":item.domain==="Inventory"?"inventory":item.domain==="Growth"?"reports":item.domain==="Orders"?"orders":"command"} size={15}/></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-1.5"><span className={"rounded-full px-2 py-1 text-[6px] font-bold ring-1 ring-inset "+severityTone(item.severity)}>{item.severity}</span><span className={"rounded-full px-2 py-1 text-[6px] font-bold ring-1 ring-inset "+statusTone(item.status)}>{item.status}</span><span className="text-[6px] font-bold text-[#87928d]">{item.confidence}% confidence</span></div><h3 className="mt-2 text-[10px] font-bold text-[#34433d]">{item.title}</h3><p className="mt-1.5 text-[7px] leading-4 text-[#87928d]">{item.why}</p></div></div><div className="mt-4 grid grid-cols-[minmax(0,1fr)_100px] gap-3 rounded-xl bg-[#fafbfa] p-3"><div><span className="text-[6px] text-[#929d97]">Signal</span><b className="mt-1 block text-[7.5px] text-[#52615a]">{item.signal}</b></div><div><span className="text-[6px] text-[#929d97]">Owner / due</span><b className="mt-1 block text-[7px] text-[#52615a]">{item.owner}</b><small className="mt-1 block text-[6px] text-[#929d97]">{item.due}</small></div></div></button>)}</div></>}{view==="Anomalies"&&<div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Anomaly</th><th className="px-4 py-3.5">Domain</th><th className="px-4 py-3.5">Observed signal</th><th className="px-4 py-3.5">Severity</th><th className="px-4 py-3.5">Detected</th><th className="px-4 py-3.5">Boundary</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{anomalyRows.map(item=><tr key={item[0]} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4 font-bold text-[#405049]">{item[0]}</td><td className="px-4 py-4">{item[1]}</td><td className="px-4 py-4">{item[2]}</td><td className="px-4 py-4"><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+severityTone(item[3] as AISignalSeverity)}>{item[3]}</span></td><td className="px-4 py-4">{item[4]} ago</td><td className="px-4 py-4 text-[#87928d]">Detection only · human review required</td></tr>)}</tbody></table></div>}{view==="Ask AI"&&<div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1.15fr)_minmax(340px,.85fr)]"><div className="rounded-2xl border border-[#d8e4e1] bg-[#edf3f4] p-5"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-[#3b646d]"><Icon name="command" size={17}/></span><div><b className="text-[10px] text-[#304d4d]">Ask about your business</b><p className="mt-1 text-[7px] text-[#70837f]">Answers cite current connected evidence and show uncertainty.</p></div></div><div className="mt-5 flex gap-2"><textarea value={ask} onChange={event=>setAsk(event.target.value)} placeholder="Example: Why is profit not growing as fast as sales?" className="min-h-24 min-w-0 flex-1 rounded-xl border border-[#d6e2df] bg-white p-3 text-[8.5px] leading-4 outline-none focus:border-[#9eb7b4]"/><button onClick={()=>askAI()} className="flex w-24 items-center justify-center rounded-xl bg-[#3b646d] text-[8px] font-bold text-white">Ask AI</button></div>{answer&&<div className="mt-4 rounded-xl bg-white p-4 ring-1 ring-[#d6e2df]"><div className="flex items-center justify-between"><b className="text-[8px] text-[#405b58]">Grounded answer</b><span className="rounded-full bg-emerald-50 px-2 py-1 text-[6px] font-bold text-emerald-700">Evidence confidence 92%</span></div><p className="mt-3 text-[8px] leading-5 text-[#65736c]">{answer}</p><div className="mt-3 flex flex-wrap gap-1.5">{["Profitability Control","Finance Reconciliation","Inventory","Meta Ads"].map(item=><button key={item} onClick={()=>onNavigate(item)} className="rounded-lg bg-[#edf3f4] px-2 py-1 text-[6px] font-bold text-[#3b646d]">{item}</button>)}</div></div>}</div><aside className="space-y-2"><b className="block text-[8px] text-[#405049]">Suggested questions</b>{["What needs my attention today?","Why is profit not growing with sales?","Which stock should I reorder first?","What is causing the COD gap?","Which campaign is losing delivered profit?"].map(item=><button key={item} onClick={()=>askAI(item)} className="flex w-full items-center justify-between rounded-xl border border-[#e2e8e5] p-3 text-left text-[7.5px] font-bold text-[#52615a] hover:border-[#9eb7b4]">{item}<Icon name="arrow" size={11}/></button>)}<div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-[7px] leading-4 text-amber-800"><b>AI can be wrong.</b> Verify important figures and approvals in their source modules before acting.</div></aside></div>}{view==="Decisions"&&<div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Decision</th><th className="px-4 py-3.5">Owner</th><th className="px-4 py-3.5">Outcome</th><th className="px-4 py-3.5">Time</th><th className="px-4 py-3.5">AI boundary</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{decisions.map(item=><tr key={item[0]} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4"><b className="block text-[#405049]">{item[1]}</b><span className="mt-1 block font-mono text-[6.5px] text-[#929d97]">{item[0]}</span></td><td className="px-4 py-4">{item[2]}</td><td className="px-4 py-4">{item[3]}</td><td className="px-4 py-4">{item[4]}</td><td className="px-4 py-4 text-[#87928d]">Recommendation recorded · human decision preserved</td></tr>)}</tbody></table></div>}{view==="Data confidence"&&<div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1.15fr)_minmax(340px,.85fr)]"><div className="divide-y divide-[#edf0ee] rounded-xl border border-[#e2e8e5]">{confidenceRows.map(item=><div key={item[0]} className="grid grid-cols-[minmax(0,1fr)_65px_90px_110px] items-center gap-3 p-4 text-[7px]"><b className="text-[8px] text-[#405049]">{item[0]}</b><b className="text-[#3b646d]">{item[1]}</b><span className="text-[#65736c]">{item[2]}</span><span className="text-right font-bold text-[#87928d]">{item[3]}</span></div>)}</div><aside className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Confidence is part of the answer</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">The assistant must distinguish verified, estimated, incomplete and stale data. Missing evidence never becomes zero or a confident fact.</p><button onClick={()=>onNavigate("Integrations")} className="mt-4 h-9 w-full rounded-xl bg-white text-[7.5px] font-bold text-[#3b646d] ring-1 ring-[#d1ddda]">Review data connections</button></aside></div>}</section>

    <section className="grid gap-3 lg:grid-cols-3"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Evidence first</p><b className="mt-1.5 block text-[10px] text-[#405049]">Every recommendation links to source facts</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">Owner can inspect figures, freshness, definition version and uncertainty before deciding.</p></article><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#84908a]">Human authority</p><b className="mt-1.5 block text-[10px] text-[#405049]">AI recommends—people approve and execute</b><p className="mt-2 text-[7px] leading-4 text-[#87928d]">No payment, refund, price, campaign, stock, supplier or customer action happens silently.</p></article><article className="rounded-2xl border border-[#d6e2df] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5e7875]">Implementation truth</p><b className="mt-1.5 block text-[10px] text-[#304d4d]">This module requires AI and data backend work</b><p className="mt-2 text-[7px] leading-4 text-[#647b77]">Production needs governed data access, retrieval, model orchestration, evaluation, cost controls, approvals and audit logs.</p></article></section>

    {focused&&<div className="fixed inset-0 z-[80] bg-[#17231f]/25 backdrop-blur-[1px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="absolute inset-y-0 right-0 w-full max-w-xl overflow-y-auto bg-white shadow-[-24px_0_70px_rgba(18,37,31,.16)]"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-[#e8ecea] bg-white/95 p-5 backdrop-blur"><div><div className="flex items-center gap-2"><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+severityTone(focused.severity)}>{focused.severity}</span><span className={"rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset "+statusTone(focused.status)}>{focused.status}</span><span className="text-[6.5px] font-bold text-[#65736c]">{focused.confidence}% confidence</span></div><h2 className="mt-2 text-[17px] font-bold leading-6 text-[#23322b]">{focused.title}</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused.id} · {focused.domain} · updated {focused.updated}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid grid-cols-3 gap-2">{[["Owner",focused.owner],["Due",focused.due],["Confidence",focused.confidence+"%"]].map(item=><div key={item[0]} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] text-[#929d97]">{item[0]}</span><b className="mt-1 block truncate text-[8px] text-[#405049]">{item[1]}</b></div>)}</div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><b className="text-[8.5px] text-[#405b58]">Business question</b><p className="mt-2 text-[7.5px] leading-4 text-[#647b77]">{focused.question}</p></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Recommendation</b><p className="mt-2 text-[7.5px] leading-4 text-[#65736c]">{focused.recommendation}</p><div className="mt-3 rounded-lg bg-[#fafbfa] p-3"><span className="text-[6px] text-[#929d97]">Expected impact</span><b className="mt-1 block text-[7.5px] text-[#405049]">{focused.impact}</b></div></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Evidence used</b><div className="mt-3 space-y-2">{focused.evidence.map(item=><div key={item} className="flex items-center gap-2 text-[7px] text-[#65736c]"><Icon name="check" size={11} className="text-emerald-700"/>{item}</div>)}</div></div><div className="rounded-xl border border-[#e2e8e5] p-4"><b className="text-[8px] text-[#405049]">Recommended review steps</b><div className="mt-3 space-y-2">{focused.steps.map((item,index)=><div key={item} className="flex gap-3"><span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#edf3f4] text-[6px] font-bold text-[#3b646d]">{index+1}</span><p className="text-[7px] leading-5 text-[#65736c]">{item}</p></div>)}</div></div><div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-[7px] leading-4 text-amber-800"><b>AI boundary:</b> {focused.guardrail}</div></div><footer className="sticky bottom-0 grid grid-cols-3 gap-2 border-t border-[#e8ecea] bg-white/95 p-4 backdrop-blur"><button onClick={openTask} className="h-10 rounded-xl border border-[#dce4e0] text-[8px] font-bold text-[#596962]">Create task</button><button onClick={openReview} className="h-10 rounded-xl border border-[#bfd0cc] bg-[#edf3f4] text-[8px] font-bold text-[#3b646d]">Review</button><button onClick={()=>onNavigate(focused.sourcePage)} className="h-10 rounded-xl bg-[#3b646d] text-[8px] font-bold text-white">Open evidence</button></footer></aside></div>}
    {configureOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4" onMouseDown={event=>{if(event.currentTarget===event.target)setConfigureOpen(false)}}><div className="w-full max-w-2xl overflow-hidden rounded-2xl bg-white shadow-2xl"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Owner control</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Configure daily brief</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Choose when and where the governed business summary should be prepared.</p></div><button onClick={()=>setConfigureOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="grid gap-3 sm:grid-cols-3"><label className="text-[7px] font-bold text-[#52615a]">Delivery time<input type="time" value={briefTime} onChange={event=>setBriefTime(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] outline-none focus:border-[#9eb7b4]"/></label><label className="text-[7px] font-bold text-[#52615a]">Channel<select value={briefChannel} onChange={event=>setBriefChannel(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] outline-none"><option>In-admin + email</option><option>In-admin only</option><option>Email only</option></select></label><label className="text-[7px] font-bold text-[#52615a]">Recipients<select value={briefRecipients} onChange={event=>setBriefRecipients(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px] outline-none"><option>Owner</option><option>Owner + Finance</option><option>Owner + Operations</option></select></label></div><div><span className="text-[7px] font-bold text-[#52615a]">Delivery days</span><div className="mt-2 flex flex-wrap gap-2">{["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(day=><button key={day} onClick={()=>setBriefDays(current=>current.includes(day)?current.filter(item=>item!==day):[...current,day])} className={"h-8 min-w-11 rounded-lg px-2 text-[7px] font-bold ring-1 ring-inset "+(briefDays.includes(day)?"bg-[#3b646d] text-white ring-[#3b646d]":"bg-white text-[#65736c] ring-[#dce4e0]")}>{day}</button>)}</div></div><div><span className="text-[7px] font-bold text-[#52615a]">Brief sections</span><div className="mt-2 grid gap-2 sm:grid-cols-2">{["Profit & cash","Orders & delivery","Inventory risk","Marketing performance","Customers & retention","Data confidence"].map((item,index)=><label key={item} className="flex items-center gap-2 rounded-xl border border-[#e2e8e5] p-3 text-[7.5px] font-semibold text-[#52615a]"><input type="checkbox" defaultChecked={index!==4} className="accent-[#3b646d]"/>{item}</label>)}</div></div><label className="block text-[7px] font-bold text-[#52615a]">Why are you changing this?<textarea value={briefReason} onChange={event=>setBriefReason(event.target.value)} placeholder="Optional audit note..." className="mt-1.5 min-h-16 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] outline-none focus:border-[#9eb7b4]"/></label><label className="flex items-start gap-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-[7px] leading-4 text-amber-800"><input type="checkbox" checked={briefConfirmed} onChange={event=>setBriefConfirmed(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>I understand this saves a delivery configuration request. Production scheduling, retries, failure alerts and recipient verification require backend automation.</span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setConfigureOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#65736c]">Cancel</button><button disabled={!briefConfirmed||briefDays.length===0} onClick={()=>{setConfigureOpen(false);showNotice("Daily brief configuration saved for implementation review.")}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Save configuration</button></footer></div></div>}

    {taskOpen&&focused&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4" onMouseDown={event=>{if(event.currentTarget===event.target)setTaskOpen(false)}}><div className="w-full max-w-xl overflow-hidden rounded-2xl bg-white shadow-2xl"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Human-owned workflow</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Create review task</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused.id} · evidence bundle will remain attached</p></div><button onClick={()=>setTaskOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><label className="block text-[7px] font-bold text-[#52615a]">Task title<input value={taskTitle} onChange={event=>setTaskTitle(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] outline-none focus:border-[#9eb7b4]"/></label><div className="grid gap-3 sm:grid-cols-3"><label className="text-[7px] font-bold text-[#52615a]">Owner<input value={taskOwner} onChange={event=>setTaskOwner(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] outline-none"/></label><label className="text-[7px] font-bold text-[#52615a]">Due<select value={taskDue} onChange={event=>setTaskDue(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Today · 4 PM</option><option>Tomorrow · 10 AM</option><option>Within 2 days</option></select></label><label className="text-[7px] font-bold text-[#52615a]">Priority<select value={taskPriority} onChange={event=>setTaskPriority(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label></div><label className="block text-[7px] font-bold text-[#52615a]">Instruction<textarea value={taskNote} onChange={event=>setTaskNote(event.target.value)} placeholder="What should the owner verify?" className="mt-1.5 min-h-20 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] outline-none"/></label><div className="grid grid-cols-3 gap-2 rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-3 text-[7px]"><div><span className="text-[#82928c]">Confidence</span><b className="mt-1 block text-[#405b58]">{focused.confidence}%</b></div><div><span className="text-[#82928c]">Sources</span><b className="mt-1 block text-[#405b58]">{focused.evidence.length} attached</b></div><div><span className="text-[#82928c]">Guardrail</span><b className="mt-1 block text-[#405b58]">Human action</b></div></div><label className="flex items-start gap-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-[7px] leading-4 text-amber-800"><input type="checkbox" checked={taskConfirmed} onChange={event=>setTaskConfirmed(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>This creates an accountable review task only. It does not execute the underlying payment, campaign, price, stock or customer action.</span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setTaskOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#65736c]">Cancel</button><button disabled={!taskConfirmed||!taskTitle.trim()||!taskOwner.trim()} onClick={()=>{setTaskOpen(false);showNotice("Human-owned task prepared with evidence and audit context.")}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Create task</button></footer></div></div>}

    {reviewOpen&&focused&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4" onMouseDown={event=>{if(event.currentTarget===event.target)setReviewOpen(false)}}><div className="w-full max-w-xl overflow-hidden rounded-2xl bg-white shadow-2xl"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Decision control</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Review recommendation</h2><p className="mt-1 text-[7.5px] text-[#87928d]">{focused.title}</p></div><button onClick={()=>setReviewOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><div className="flex items-center justify-between gap-3"><b className="text-[8.5px] text-[#405b58]">Recommendation</b><span className="rounded-full bg-white px-2 py-1 text-[6px] font-bold text-[#3b646d] ring-1 ring-[#d6e2df]">{focused.confidence}% confidence</span></div><p className="mt-2 text-[7.5px] leading-4 text-[#647b77]">{focused.recommendation}</p></div><label className="block text-[7px] font-bold text-[#52615a]">Decision<select value={reviewDecision} onChange={event=>setReviewDecision(event.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Accept for review</option><option>Need more evidence</option><option>Dismiss</option></select></label><label className="block text-[7px] font-bold text-[#52615a]">Decision reason<textarea value={reviewReason} onChange={event=>setReviewReason(event.target.value)} placeholder="Required for the audit trail..." className="mt-1.5 min-h-20 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] outline-none focus:border-[#9eb7b4]"/></label><div className="rounded-xl border border-[#e2e8e5] p-3 text-[7px] leading-4 text-[#65736c]"><b className="text-[#405049]">Evidence snapshot:</b> {focused.signal} · {focused.evidence.length} sources · updated {focused.updated}</div><label className="flex items-start gap-2 rounded-xl border border-rose-200 bg-rose-50 p-3 text-[7px] leading-4 text-rose-800"><input type="checkbox" checked={reviewConfirmed} onChange={event=>setReviewConfirmed(event.target.checked)} className="mt-0.5 accent-[#3b646d]"/><span>I understand “Accept for review” records a human decision to investigate. It is not approval and does not execute any business action.</span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setReviewOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#65736c]">Cancel</button><button disabled={!reviewConfirmed||!reviewReason.trim()} onClick={()=>{setReviewOpen(false);showNotice(reviewDecision+" recorded with human ownership.")}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Record decision</button></footer></div></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

