function SeoStorefrontHealthWorkspace({onNavigate}:{onNavigate:(page:string)=>void}) {
  const [view,setView]=useState<SeoHealthView>("Priority issues");
  const [query,setQuery]=useState("");
  const [severity,setSeverity]=useState("All severity");
  const [focused,setFocused]=useState<(typeof seoHealthIssues)[number]|null>(null);
  const [templatesOpen,setTemplatesOpen]=useState(false);
  const [redirectOpen,setRedirectOpen]=useState(false);
  const [auditRunning,setAuditRunning]=useState(false);
  const [notice,setNotice]=useState("");
  const [templateType,setTemplateType]=useState("Product");
  const [titleTemplate,setTitleTemplate]=useState("{product_name} | Authentic Beauty at BrandnBeauty");
  const [descriptionTemplate,setDescriptionTemplate]=useState("Shop {product_name} in Bangladesh. See ingredients, suitability, authentic sourcing and delivery information.");
  const [redirectFrom,setRedirectFrom]=useState("");
  const [redirectTo,setRedirectTo]=useState("");
  const [redirectReason,setRedirectReason]=useState("");
  const [redirectConfirmed,setRedirectConfirmed]=useState(false);
  const showNotice=(message:string)=>{setNotice(message);setTimeout(()=>setNotice(""),2600)};
  const startAudit=()=>{setAuditRunning(true);setTimeout(()=>{setAuditRunning(false);showNotice("Storefront audit refreshed. 7 launch blockers still need attention.")},1000)};
  const filteredIssues=seoHealthIssues.filter(item=>(severity==="All severity"||item.severity===severity)&&(item.title+" "+item.scope+" "+item.owner).toLowerCase().includes(query.toLowerCase()));
  const tone=(status:SeoHealthStatus)=>status==="Critical"?"bg-rose-50 text-rose-700 ring-rose-200":status==="Warning"?"bg-amber-50 text-amber-700 ring-amber-200":"bg-emerald-50 text-emerald-700 ring-emerald-200";
  const scoreTone=(value:number)=>value>=95?"text-emerald-700":value>=85?"text-amber-700":"text-rose-700";
  const templatePreview=titleTemplate.replace("{product_name}","Kojic Acid Brightening Body Wash").replace("{brand_name}","BrandnBeauty");

  return <div className="space-y-5">
    <section className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-[#3b646d]"/><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#3b646d]">Launch readiness · mobile-first discovery</p></div><h1 className="mt-2 text-[28px] font-bold tracking-[-.035em] text-[#17231f] sm:text-[32px]">SEO &amp; Storefront Health</h1><p className="mt-1.5 max-w-3xl text-[12.5px] leading-5 text-[#66736d]">Protect search visibility, mobile shopping and campaign landing journeys—without changing BrandnBeauty&apos;s approved storefront design.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>setTemplatesOpen(true)} className="flex h-10 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3.5 text-[8.5px] font-bold text-[#596962]"><Icon name="edit" size={13}/>SEO templates</button><button onClick={startAudit} disabled={auditRunning} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-4 text-[8.5px] font-bold text-white disabled:opacity-60"><Icon name="refresh" size={13} className={auditRunning?"animate-spin":""}/>{auditRunning?"Auditing…":"Run storefront audit"}</button></div></section>

    <section className="overflow-hidden rounded-2xl border border-[#cdddda] bg-[#eaf2f1]"><div className="grid gap-4 p-4 sm:p-5 xl:grid-cols-[minmax(0,1fr)_auto]"><div className="flex gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white text-[#3b646d]"><Icon name="alert" size={17}/></span><div><div className="flex flex-wrap items-center gap-2"><h2 className="text-[13px] font-bold text-[#294745]">Launch SEO readiness is 82%</h2><span className="rounded-full bg-rose-50 px-2 py-1 text-[6.5px] font-bold text-rose-700 ring-1 ring-inset ring-rose-200">7 blockers</span></div><p className="mt-1 text-[7.5px] leading-4 text-[#637b77]">Fix canonical gaps and the 360 px checkout shift before public launch. Content warnings can continue immediately after launch.</p><div className="mt-3 h-1.5 max-w-xl overflow-hidden rounded-full bg-white"><div className="h-full w-[82%] rounded-full bg-[#5d8381]"/></div></div></div><div className="flex flex-wrap items-center gap-2 xl:justify-end"><button onClick={()=>{setView("Priority issues");setSeverity("Critical")}} className="h-9 rounded-xl border border-[#bfd2ce] bg-white px-3 text-[8px] font-bold text-[#486966]">View blockers</button><button onClick={()=>onNavigate("Tracking & Attribution")} className="flex h-9 items-center gap-2 rounded-xl px-3 text-[8px] font-bold text-[#486966]">Measurement health<Icon name="arrow" size={12}/></button></div></div></section>

    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[
      ["Indexable storefront pages","293 / 326","89.9%","33 excluded by policy","search" as IconName],
      ["Metadata coverage","91%","+4 pts","Titles + descriptions","edit" as IconName],
      ["Mobile good URLs","76%","Needs work","360–412 px priority","phone" as IconName],
      ["Broken customer paths","7","Launch blocker","404, canonical or redirect","alert" as IconName],
    ].map(([label,value,change,meta,icon],index)=><article key={label} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-start justify-between"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#edf3f4] text-[#3b646d]"><Icon name={icon as IconName} size={15}/></span><span className={(index===3||change==="Needs work"?"text-amber-700":"text-emerald-700")+" text-[6.5px] font-bold"}>{change}</span></div><b className="mt-4 block text-[18px] tracking-[-.03em] text-[#33423b]">{value}</b><p className="mt-1 text-[6.5px] font-bold uppercase tracking-[.1em] text-[#829089]">{label}</p><p className="mt-2 text-[6.5px] text-[#929d97]">{meta}</p></article>)}</section>

    <section className="grid gap-4 xl:grid-cols-[minmax(0,1.22fr)_minmax(340px,.78fr)]"><article className="rounded-2xl border border-[#e2e8e5] bg-white p-4 sm:p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#84908a]">Mobile commerce guardrail</p><h2 className="mt-1 text-[14px] font-bold text-[#33423b]">Customer journey health</h2><p className="mt-1 text-[7px] text-[#929d97]">Facebook in-app browser · Android-first test profile</p></div><span className="w-fit rounded-full bg-amber-50 px-2 py-1 text-[7px] font-bold text-amber-700">1 launch blocker</span></div><div className="mt-5 grid gap-3 sm:grid-cols-4">{[["360 px","Warning","Checkout shift"],["375 px","Pass","No overflow"],["390 px","Pass","Tap targets clear"],["412 px","Pass","Forms usable"]].map(([width,status,meta])=><div key={width} className="rounded-xl border border-[#e7ebe9] p-3"><div className="flex items-center justify-between"><b className="text-[8px] text-[#405049]">{width}</b><span className={(status==="Pass"?"bg-emerald-500":"bg-amber-400")+" h-2 w-2 rounded-full"}/></div><span className="mt-2 block text-[6.5px] text-[#929d97]">{meta}</span></div>)}</div><div className="mt-5 grid gap-4 sm:grid-cols-3">{[["LCP","2.3s",92],["INP","184ms",94],["CLS","0.08",96]].map(([label,value,score])=><div key={label as string}><div className="flex items-end justify-between"><span className="text-[7px] font-bold text-[#65736c]">{label}</span><b className={scoreTone(score as number)+" text-[9px]"}>{value}</b></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#edf1ef]"><div className="h-full rounded-full bg-[#5f8585]" style={{width:score+"%"}}/></div></div>)}</div><div className="mt-5 grid gap-2 sm:grid-cols-2">{[["Product → cart","Pass","Primary action stays visible"],["Cart → checkout","Pass","No horizontal overflow"],["Checkout form","Warning","Trust copy shifts CTA at 360 px"],["Order success","Pass","Purchase event + order ID ready"]].map(([step,status,meta])=><button key={step} onClick={()=>status==="Warning"&&setFocused(seoHealthIssues[1])} className="flex items-center gap-3 rounded-xl border border-[#e6ebe8] p-3 text-left hover:bg-[#fafcfb]"><span className={(status==="Pass"?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700")+" flex h-7 w-7 shrink-0 items-center justify-center rounded-lg"}><Icon name={status==="Pass"?"check":"alert"} size={12}/></span><span className="min-w-0"><b className="block text-[7.5px] text-[#405049]">{step}</b><small className="mt-1 block text-[6.5px] leading-3 text-[#929d97]">{meta}</small></span></button>)}</div></article>

      <aside className="rounded-2xl border border-[#d7e3e0] bg-[#edf3f4] p-4 sm:p-5"><div className="flex items-start justify-between"><div><p className="text-[8px] font-bold uppercase tracking-[.12em] text-[#5e7875]">Growth-critical funnel</p><h2 className="mt-1 text-[14px] font-bold text-[#304d4d]">AI Skin Test discovery path</h2></div><span className="rounded-full bg-white px-2 py-1 text-[7px] font-bold text-[#3b646d]">4 / 6 ready</span></div><p className="mt-2 text-[7px] leading-4 text-[#647b77]">The public landing page earns discovery; personal quiz results stay private and pass concern context safely into cart or Messenger.</p><div className="mt-4 space-y-2">{[
        ["Campaign landing","Ready","Indexable · unique metadata"],["Quiz experience","Ready","Mobile-first · consent captured"],["Concern result","Ready","Private URL · noindex"],["Catalog matching","Ready","Only BrandnBeauty products"],["Cart handoff","Backend","Routine + product IDs"],["Messenger lead context","Backend","Concern, source, campaign, consent"],
      ].map(([step,status,meta],index)=><div key={step} className="flex items-start gap-3 rounded-xl bg-white/80 p-3"><span className={(status==="Ready"?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700")+" flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-[6.5px] font-bold"}>{index+1}</span><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><b className="text-[7.5px] text-[#405049]">{step}</b><span className={(status==="Ready"?"text-emerald-700":"text-amber-700")+" text-[6px] font-bold"}>{status}</span></div><span className="mt-1 block text-[6.5px] leading-3 text-[#879690]">{meta}</span></div></div>)}</div><div className="mt-4 grid grid-cols-2 gap-2"><button onClick={()=>onNavigate("AI Skin Test & Consultation")} className="h-9 rounded-xl bg-[#3b646d] px-3 text-[7.5px] font-bold text-white">Open Skin Test</button><button onClick={()=>onNavigate("Conversational Commerce Hub")} className="h-9 rounded-xl border border-[#cbdad6] bg-white px-3 text-[7.5px] font-bold text-[#486966]">Open Commerce Hub</button></div></aside></section>

    <section className="overflow-hidden rounded-2xl border border-[#e2e8e5] bg-white"><div className="flex flex-col gap-3 border-b border-[#e8ecea] p-4 sm:p-5 xl:flex-row xl:items-center"><div className="flex gap-1 overflow-x-auto">{(["Priority issues","Page coverage","Redirects"] as SeoHealthView[]).map(item=><button key={item} onClick={()=>setView(item)} className={(view===item?"bg-[#3b646d] text-white":"text-[#77857e] hover:bg-[#f2f5f3]")+" h-9 whitespace-nowrap rounded-lg px-3 text-[8px] font-bold"}>{item}</button>)}</div><label className="relative min-w-0 flex-1 xl:ml-auto xl:max-w-sm"><Icon name="search" size={13} className="absolute left-3 top-3 text-[#8a9590]"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search issue, page type or owner..." className="h-9 w-full rounded-xl border border-[#dce4e0] bg-white pl-9 pr-3 text-[8px] outline-none"/></label>{view==="Priority issues"&&<select value={severity} onChange={event=>setSeverity(event.target.value)} className="h-9 rounded-xl border border-[#dce4e0] bg-white px-3 text-[7.5px] font-bold text-[#58675f]"><option>All severity</option><option>Critical</option><option>Warning</option><option>Healthy</option></select>}{view==="Redirects"&&<button onClick={()=>setRedirectOpen(true)} className="flex h-9 items-center justify-center gap-2 rounded-xl bg-[#3b646d] px-3 text-[7.5px] font-bold text-white"><Icon name="plus" size={12}/>Create redirect</button>}</div>
      {view==="Priority issues"?<div className="overflow-x-auto"><table className="w-full min-w-[980px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Issue</th><th className="px-4 py-3.5">Scope</th><th className="px-4 py-3.5">Affected</th><th className="px-4 py-3.5">Owner</th><th className="px-4 py-3.5">Priority</th><th className="px-4 py-3.5">Action</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{filteredIssues.map(item=><tr key={item.id} className="text-[8px] text-[#5f6e67] hover:bg-[#fafcfb]"><td className="px-5 py-4"><b className="block text-[8.5px] text-[#33423b]">{item.title}</b><span className="mt-1 block max-w-lg text-[6.5px] leading-3.5 text-[#929d97]">{item.detail}</span></td><td className="px-4 py-4 font-bold">{item.scope}</td><td className="px-4 py-4">{item.affected||"—"}</td><td className="px-4 py-4">{item.owner}</td><td className="px-4 py-4"><span className={tone(item.severity)+" inline-flex rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset"}>{item.severity}</span></td><td className="px-4 py-4"><button onClick={()=>setFocused(item)} className="flex items-center gap-1.5 font-bold text-[#3b646d]">{item.action}<Icon name="chevron" size={11}/></button></td></tr>)}</tbody></table></div>:view==="Page coverage"?<div className="overflow-x-auto"><table className="w-full min-w-[920px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Page type</th><th className="px-4 py-3.5">Pages</th><th className="px-4 py-3.5">Indexable</th><th className="px-4 py-3.5">Titles</th><th className="px-4 py-3.5">Descriptions</th><th className="px-4 py-3.5">Schema</th><th className="px-4 py-3.5">Mobile</th><th className="px-4 py-3.5">Status</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{seoCoverageRows.filter(item=>item.type.toLowerCase().includes(query.toLowerCase())).map(item=><tr key={item.type} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4 font-bold text-[#33423b]">{item.type}</td><td className="px-4 py-4">{item.pages}</td><td className="px-4 py-4 font-bold">{item.indexable}</td>{[item.title,item.description,item.schema,item.mobile].map((value,index)=><td key={index} className={scoreTone(value)+" px-4 py-4 font-bold"}>{value}%</td>)}<td className="px-4 py-4"><span className={tone(item.status)+" rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset"}>{item.status}</span></td></tr>)}</tbody></table></div>:<div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead className="bg-[#fafbfa] text-[6.5px] font-bold uppercase tracking-[.1em] text-[#8a9590]"><tr><th className="px-5 py-3.5">Old path</th><th className="px-4 py-3.5">Destination</th><th className="px-4 py-3.5">Type</th><th className="px-4 py-3.5">90D hits</th><th className="px-4 py-3.5">Status</th></tr></thead><tbody className="divide-y divide-[#edf0ee]">{seoRedirectRows.filter(item=>(item.from+item.to).toLowerCase().includes(query.toLowerCase())).map(item=><tr key={item.from} className="text-[8px] text-[#5f6e67]"><td className="px-5 py-4 font-mono text-[#33423b]">{item.from}</td><td className="px-4 py-4 font-mono">{item.to}</td><td className="px-4 py-4 font-bold">{item.type}</td><td className="px-4 py-4">{item.hits}</td><td className="px-4 py-4"><span className={(item.status==="Active"?"bg-emerald-50 text-emerald-700 ring-emerald-200":"bg-amber-50 text-amber-700 ring-amber-200")+" rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset"}>{item.status}</span></td></tr>)}</tbody></table></div>}
    </section>

    <section className="grid gap-4 lg:grid-cols-3">{[
      ["Crawl & index","Sitemap, robots, canonicals and index policy","Technical foundation","Healthy"],["Search appearance","Titles, descriptions, product and breadcrumb data","Catalog + CMS","Warning"],["Mobile conversion","Speed, layout stability and purchase journey","Storefront QA","Warning"],
    ].map(([title,body,owner,status])=><article key={title} className="rounded-2xl border border-[#e2e8e5] bg-white p-4"><div className="flex items-center justify-between"><span className="flex h-8 w-8 items-center justify-center rounded-xl bg-[#edf3f4] text-[#3b646d]"><Icon name={status==="Healthy"?"check":"alert"} size={13}/></span><span className={tone(status as SeoHealthStatus)+" rounded-full px-2 py-1 text-[6px] font-bold ring-1 ring-inset"}>{status}</span></div><h3 className="mt-4 text-[10px] font-bold text-[#33423b]">{title}</h3><p className="mt-1 text-[7px] leading-4 text-[#87928d]">{body}</p><p className="mt-3 border-t border-[#edf0ee] pt-3 text-[6.5px] font-bold text-[#65736c]">Owner · {owner}</p></article>)}</section>

    {focused&&<div className="fixed inset-0 z-[90] flex justify-end bg-[#17231f]/30 backdrop-blur-[2px]" onMouseDown={event=>{if(event.currentTarget===event.target)setFocused(null)}}><aside className="flex h-full w-full max-w-lg flex-col bg-white shadow-2xl"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><span className={tone(focused.severity)+" inline-flex rounded-full px-2 py-1 text-[6.5px] font-bold ring-1 ring-inset"}>{focused.severity}</span><h2 className="mt-3 text-[18px] font-bold text-[#23322b]">{focused.title}</h2><p className="mt-1 text-[7.5px] leading-4 text-[#87928d]">{focused.id} · {focused.scope} · {focused.affected||"No"} affected page{focused.affected===1?"":"s"}</p></div><button onClick={()=>setFocused(null)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="flex-1 space-y-4 overflow-y-auto p-5"><div className="rounded-xl border border-[#e2e8e5] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#87928d]">Why it matters</p><p className="mt-2 text-[8px] leading-4 text-[#52615a]">{focused.detail}</p></div><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><p className="text-[7px] font-bold uppercase tracking-[.1em] text-[#5d7775]">Recommended resolution</p><div className="mt-3 space-y-2">{["Confirm the intended customer-facing primary URL.","Apply the smallest storefront change without altering visual design.","Re-run the mobile and crawl checks before marking resolved."].map((item,index)=><div key={item} className="flex gap-2 text-[7.5px] leading-4 text-[#647b77]"><span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-white text-[6px] font-bold text-[#3b646d]">{index+1}</span>{item}</div>)}</div></div><div className="grid grid-cols-2 gap-3">{[["Owner",focused.owner],["Priority",focused.severity],["Scope",focused.scope],["Backend","Integration required"]].map(([label,value])=><div key={label} className="rounded-xl border border-[#e2e8e5] p-3"><span className="text-[6px] font-bold uppercase text-[#929d97]">{label}</span><b className="mt-1 block text-[7.5px] text-[#405049]">{value}</b></div>)}</div></div><footer className="flex flex-col-reverse gap-2 border-t border-[#e8ecea] p-4 sm:flex-row sm:justify-end"><button onClick={()=>setFocused(null)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Close</button><button onClick={()=>{setFocused(null);showNotice("Remediation task added to the launch queue.")}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white">Add to launch queue</button></footer></aside></div>}

    {templatesOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setTemplatesOpen(false)}}><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Reusable search appearance</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">SEO templates</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Fallbacks protect coverage; page-level editors can override them.</p></div><button onClick={()=>setTemplatesOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><label className="block text-[7px] font-bold text-[#596962]">Page type<select value={templateType} onChange={event=>setTemplateType(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] bg-white px-3 text-[8px]"><option>Product</option><option>Category</option><option>Concern</option><option>Brand</option><option>Collection</option></select></label><label className="block text-[7px] font-bold text-[#596962]">Title template · {titleTemplate.length}/60<input maxLength={60} value={titleTemplate} onChange={event=>setTitleTemplate(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 text-[8px] outline-none focus:border-[#9eb7b4]"/></label><label className="block text-[7px] font-bold text-[#596962]">Description template · {descriptionTemplate.length}/160<textarea maxLength={160} rows={3} value={descriptionTemplate} onChange={event=>setDescriptionTemplate(event.target.value)} className="mt-2 w-full resize-none rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4 outline-none focus:border-[#9eb7b4]"/></label><div className="rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><span className="text-[6.5px] font-bold text-[#3b646d]">brandnbeauty.com › products › kojic-body-wash</span><h3 className="mt-2 text-[13px] font-semibold text-[#244e8a]">{templatePreview}</h3><p className="mt-1 text-[7.5px] leading-4 text-[#5f6e67]">{descriptionTemplate.replace("{product_name}","Kojic Acid Brightening Body Wash")}</p></div><div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-[7px] leading-4 text-amber-800"><b>Safe publish:</b> changing a template requires an impact preview and never rewrites approved page overrides silently.</div></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setTemplatesOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button onClick={()=>{setTemplatesOpen(false);showNotice(`${templateType} SEO template saved as draft.`)}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white">Save draft</button></footer></div></div>}

    {redirectOpen&&<div className="fixed inset-0 z-[90] flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={event=>{if(event.currentTarget===event.target)setRedirectOpen(false)}}><div className="w-full max-w-xl rounded-2xl bg-white shadow-[0_28px_90px_rgba(18,37,31,.24)]"><header className="flex items-start justify-between border-b border-[#e8ecea] p-5"><div><p className="text-[7px] font-bold uppercase tracking-[.12em] text-[#3b646d]">Protect existing links</p><h2 className="mt-1 text-[17px] font-bold text-[#23322b]">Create 301 redirect</h2><p className="mt-1 text-[7.5px] text-[#87928d]">Route an old customer or campaign URL to one valid destination.</p></div><button onClick={()=>setRedirectOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f2f5f3] text-[#65736c]"><Icon name="close" size={14}/></button></header><div className="space-y-4 p-5"><label className="block text-[7px] font-bold text-[#596962]">Old path<input value={redirectFrom} onChange={event=>setRedirectFrom(event.target.value)} placeholder="/old-path" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 font-mono text-[8px]"/></label><label className="block text-[7px] font-bold text-[#596962]">Destination path<input value={redirectTo} onChange={event=>setRedirectTo(event.target.value)} placeholder="/current-path" className="mt-2 h-10 w-full rounded-xl border border-[#dce4e0] px-3 font-mono text-[8px]"/></label><label className="block text-[7px] font-bold text-[#596962]">Reason<textarea rows={3} value={redirectReason} onChange={event=>setRedirectReason(event.target.value)} placeholder="Why was this URL changed?" className="mt-2 w-full rounded-xl border border-[#dce4e0] p-3 text-[8px] leading-4"/></label><label className="flex items-start gap-3 rounded-xl border border-[#d8e4e1] bg-[#edf3f4] p-4"><input type="checkbox" checked={redirectConfirmed} onChange={event=>setRedirectConfirmed(event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#3b646d]"/><span><b className="block text-[7.5px] text-[#405b58]">I checked the destination and redirect chain</b><small className="mt-1 block text-[6.5px] leading-3.5 text-[#70837f]">Production validation must reject loops, chains and missing destinations.</small></span></label></div><footer className="flex justify-end gap-2 border-t border-[#e8ecea] p-4"><button onClick={()=>setRedirectOpen(false)} className="h-10 rounded-xl border border-[#dce4e0] px-4 text-[8px] font-bold text-[#596962]">Cancel</button><button disabled={!redirectFrom.startsWith("/")||!redirectTo.startsWith("/")||!redirectReason.trim()||!redirectConfirmed} onClick={()=>{setRedirectOpen(false);showNotice("Redirect saved as draft for validation.");setRedirectFrom("");setRedirectTo("");setRedirectReason("");setRedirectConfirmed(false)}} className="h-10 rounded-xl bg-[#3b646d] px-4 text-[8px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Save redirect draft</button></footer></div></div>}

    {notice&&<div className="fixed bottom-5 right-5 z-[100] max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[9px] font-semibold leading-5 text-white shadow-xl">{notice}</div>}
  </div>;
}

function ModulePage({ page }: { page: string }) {
  const copy = getModuleCopy(page);
  const isProducts = page === "Products" || page === "Inventory";
  return <div className="space-y-5">
    <section className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[0.15em] text-[#74847d]">{copy.eyebrow}</p><h1 className="mt-2 text-[28px] font-bold tracking-[-0.035em] text-[#17231f] sm:text-[32px]">{copy.title}</h1><p className="mt-1.5 max-w-2xl text-[13px] leading-5 text-[#6e7b75]">{copy.subtitle}</p></div><button className="flex w-fit items-center gap-2 rounded-xl bg-[#52797b] px-4 py-2.5 text-xs font-bold text-white shadow-sm transition hover:bg-[#436a6c]"><Icon name="plus" size={15}/>{page === "Orders" ? "Add order" : page === "Products" ? "Add product" : page === "Inventory" ? "Stock entry" : "Create new"}</button></section>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{copy.stats.map((s,i)=><MetricCard key={s[0]} label={s[0]} value={s[1]} meta={s[2]} index={i}/>)}</section>
    {page === "Orders" ? <OrdersTable compact/> : isProducts ? <div className="overflow-hidden rounded-2xl border border-[#e3e8e6] bg-white"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#edf0ee] p-5"><div><p className="text-[11px] font-bold uppercase tracking-[0.16em] text-[#87928d]">Catalog health</p><h2 className="mt-1 text-[17px] font-bold">{page === "Inventory" ? "Stock overview" : "Product list"}</h2></div><div className="flex gap-2"><button className="rounded-lg border border-[#dde4e1] px-3 py-2 text-xs font-semibold">Filter</button><button className="rounded-lg border border-[#dde4e1] px-3 py-2 text-xs font-semibold">Export</button></div></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="bg-[#fafbfa] text-[10px] uppercase tracking-[0.11em] text-[#8a9590]"><tr><th className="px-6 py-3.5">Product</th><th className="px-4 py-3.5">SKU</th><th className="px-4 py-3.5">Stock</th><th className="px-4 py-3.5">30D sold</th><th className="px-4 py-3.5">Price</th><th className="px-4 py-3.5">Status</th><th className="px-5 py-3.5"/></tr></thead><tbody className="divide-y divide-[#edf0ee]">{products.map(p=><tr key={p.sku} className="text-[12px] text-[#5c6963] hover:bg-[#f9fbfa]"><td className="px-6 py-4 font-semibold text-[#293730]">{p.name}</td><td className="px-4 py-4 text-[10px] text-[#89948f]">{p.sku}</td><td className="px-4 py-4 font-bold">{p.stock}</td><td className="px-4 py-4">{p.sold}</td><td className="px-4 py-4 font-bold text-[#293730]">{p.price}</td><td className="px-4 py-4"><Status>{p.status}</Status></td><td className="px-5 py-4 text-right"><Icon name="more" size={16}/></td></tr>)}</tbody></table></div></div> : <section className="grid gap-5 xl:grid-cols-[minmax(0,1.4fr)_minmax(300px,.6fr)]"><article className="rounded-2xl border border-[#e3e8e6] bg-white p-6"><p className="text-[11px] font-bold uppercase tracking-[0.16em] text-[#87928d]">Recommended workspace</p><h2 className="mt-1 text-[18px] font-bold text-[#1b2823]">Designed to scale with your workflow</h2><div className="mt-5 grid gap-3 sm:grid-cols-2">{["Focused filters and saved views", "Clear table hierarchy", "Contextual side panels", "Role-based primary actions"].map((x,i)=><div key={x} className="flex items-center gap-3 rounded-xl border border-[#edf0ee] bg-[#fafbfa] p-4 text-[12px] font-semibold text-[#4f5d57]"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[#eaf1ef] text-[#557a7c]"><Icon name={i%2?"check":"command"} size={14}/></span>{x}</div>)}</div></article><article className="rounded-2xl border border-[#d6e2de] bg-[#edf4f2] p-6"><p className="text-[11px] font-bold uppercase tracking-[0.16em] text-[#557a7c]">UX principle</p><h2 className="mt-2 text-[18px] font-bold text-[#243631]">Summary first. Details on demand.</h2><p className="mt-3 text-[12px] leading-5 text-[#5d716a]">The interface stays quiet until a task needs attention. This keeps growing functionality usable instead of visually heavy.</p></article></section>}
  </div>;
}

function CommandPalette({ onClose, onNavigate }: { onClose: () => void; onNavigate: (page: string) => void }) {
  const [query, setQuery] = useState("");
  const actions = [...navGroups.flatMap(group=>group.items.map(item=>({label:item, icon:group.icon}))), {label:"Add Facebook order", icon:"plus" as IconName}, {label:"Create purchase entry", icon:"inventory" as IconName}];
  const filtered = actions.filter(a=>a.label.toLowerCase().includes(query.toLowerCase()));
  return <div className="fixed inset-0 z-50 flex items-start justify-center bg-[#17231f]/35 px-4 pt-[12vh] backdrop-blur-sm" onMouseDown={e=>{if(e.currentTarget===e.target)onClose()}}><div className="w-full max-w-xl overflow-hidden rounded-2xl border border-white/40 bg-white shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-center gap-3 border-b border-[#e8ecea] px-5"><Icon name="search" size={19} className="text-[#6b7b74]"/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search pages, orders or actions..." className="h-14 flex-1 bg-transparent text-[13px] outline-none placeholder:text-[#9ca6a1]"/><kbd className="rounded-md border border-[#dde3e0] bg-[#f6f8f7] px-2 py-1 text-[9px] font-bold text-[#7d8983]">ESC</kbd></div><div className="max-h-[340px] overflow-y-auto p-2"><p className="px-3 py-2 text-[9px] font-bold uppercase tracking-[.14em] text-[#9aa49f]">{navigationPageCount} pages · Quick navigation</p>{filtered.map(a=><button key={a.label} onClick={()=>{if(pageGroup(a.label)||a.label==="Dashboard")onNavigate(a.label);onClose()}} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-[12px] font-semibold text-[#485750] transition hover:bg-[#f2f6f4]"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#edf3f1] text-[#557a7c]"><Icon name={a.icon} size={15}/></span><span className="flex-1">{a.label}</span><Icon name="arrow" size={14} className="text-[#a0aaa5]"/></button>)}</div><div className="flex items-center gap-4 border-t border-[#e8ecea] bg-[#fafbfa] px-5 py-3 text-[9px] font-semibold text-[#8a9590]"><span>↑↓ Navigate</span><span>↵ Open</span><span>Esc Close</span></div></div></div>;
}

function QuickAdd({ onClose }: { onClose: () => void }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#17231f]/35 p-4 backdrop-blur-sm" onMouseDown={e=>{if(e.currentTarget===e.target)onClose()}}><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-[0_30px_90px_rgba(17,35,30,.24)]"><div className="flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#788781]">Quick add</p><h2 className="mt-1 text-xl font-bold text-[#1e2d27]">Start a workflow</h2><p className="mt-1 text-[12px] text-[#7b8781]">Choose what you want to create.</p></div><button aria-label="Close quick add" onClick={onClose} className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#f3f5f4] text-[#66736d]"><Icon name="close" size={16}/></button></div><div className="mt-5 grid grid-cols-2 gap-3">{[["orders","Manual order","Facebook / WhatsApp"],["products","New product","Catalog item"],["inventory","Stock entry","Purchase / adjustment"],["customers","Customer","Manual profile"]].map(([i,l,n])=><button key={l} onClick={onClose} className="rounded-xl border border-[#e3e8e6] p-4 text-left transition hover:border-[#bdd0cb] hover:bg-[#f6f9f8]"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#eaf1ef] text-[#557a7c]"><Icon name={i as IconName} size={17}/></span><span className="mt-3 block text-[12px] font-bold text-[#26352f]">{l}</span><span className="mt-1 block text-[10px] text-[#8a9590]">{n}</span></button>)}</div></div></div>;
}

function AdminWorkspace() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const requestedPage = searchParams.get("page") || "Dashboard";
  const routedPage = pageGroup(requestedPage) ? requestedPage : "Dashboard";
  const [active, setActive] = useState(routedPage);
  const [openGroup, setOpenGroup] = useState(pageGroup(routedPage)?.label || "Overview");
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [quickAddOpen, setQuickAddOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [toast, setToast] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<OperationalOrder>(operationalOrders[0]);
  const [selectedCustomer, setSelectedCustomer] = useState<CustomerRecord>(customerRecords[0]);

  useEffect(()=>{const handle=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();setPaletteOpen(true)}if(e.key==="Escape"){setPaletteOpen(false);setQuickAddOpen(false);setNotificationsOpen(false)}};window.addEventListener("keydown",handle);return()=>window.removeEventListener("keydown",handle);},[]);

  useEffect(()=>{setActive(routedPage);setOpenGroup(pageGroup(routedPage)?.label||"Overview");setMobileOpen(false)},[routedPage]);

  const setPage=(page:string)=>{const nextPage=pageGroup(page)?page:"Dashboard";setActive(nextPage);setOpenGroup(pageGroup(nextPage)?.label || "Overview");setMobileOpen(false);router.push(nextPage==="Dashboard"?"/":`/?page=${encodeURIComponent(nextPage)}`,{scroll:false});window.scrollTo({top:0,behavior:"smooth"})};
  const openOrderDetails=(order:OperationalOrder)=>{setSelectedOrder(order);setPage("Order Details")};
  const openCustomerProfile=(customer:CustomerRecord)=>{setSelectedCustomer(customer);setPage("Customer Profile")};
  const title = active === "Dashboard" ? "Overview" : active;
  const subtitle = active === "Dashboard" ? "Friday, 21 August 2026" : getModuleCopy(active).eyebrow;
  const shellWidth = collapsed ? "lg:pl-[82px]" : "lg:pl-[252px]";

  const Sidebar = ({ mobile=false }: { mobile?:boolean }) => <aside className={`${mobile ? "fixed inset-y-0 left-0 z-50 w-[276px] shadow-2xl" : `fixed inset-y-0 left-0 z-40 hidden border-r border-[#e1e7e4] lg:flex ${collapsed ? "w-[82px]" : "w-[252px]"}`} flex-col bg-[#fbfcfb] transition-all duration-300`}>
    <div className={`flex h-[70px] items-center border-b border-[#e6ebe8] ${collapsed && !mobile ? "justify-center px-3" : "justify-between px-5"}`}><button className="flex items-center gap-3" onClick={()=>setPage("Dashboard")} aria-label="BrandnBeauty dashboard"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#3b646d] text-sm font-black text-white shadow-sm">B</span>{(!collapsed||mobile)&&<span className="text-left"><span className="block text-[15px] font-extrabold tracking-[-.025em] text-[#21302a]">BrandnBeauty</span><span className="mt-0.5 block text-[9px] font-semibold uppercase tracking-[.14em] text-[#8d9893]">Admin workspace</span></span>}</button>{mobile&&<button aria-label="Close menu" onClick={()=>setMobileOpen(false)} className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#f1f4f2]"><Icon name="close" size={16}/></button>}</div>
    <div className="flex-1 overflow-y-auto px-3 py-4">
      {(!collapsed||mobile)&&<div className="mb-3 flex items-center justify-between px-3"><span className="text-[9px] font-bold uppercase tracking-[.17em] text-[#a0aaa5]">Navigation</span><span className="rounded-full bg-[#eef2f0] px-2 py-1 text-[8px] font-bold text-[#7a8781]">{navigationPageCount} pages</span></div>}
      <div className="space-y-1">{navGroups.map(group=>{const containsActive=group.items.includes(active);const expanded=openGroup===group.label&&(!collapsed||mobile);return <section key={group.label}>
        <button aria-expanded={expanded} title={collapsed&&!mobile?group.label:undefined} onClick={()=>{if(collapsed&&!mobile){setCollapsed(false);setOpenGroup(group.label)}else{setOpenGroup(openGroup===group.label?"":group.label)}}} className={`group relative flex min-h-10 w-full items-center rounded-xl text-[11px] font-bold transition ${collapsed&&!mobile?"justify-center":"gap-3 px-3"} ${containsActive?"bg-[#e8f0ee] text-[#345d60]":"text-[#56665e] hover:bg-[#f0f4f2] hover:text-[#2e3e37]"}`}>
          <Icon name={group.icon} size={17} className={containsActive?"text-[#4f7779]":"text-[#84908a] group-hover:text-[#5d7d79]"}/>
          {(!collapsed||mobile)&&<><span className="flex-1 text-left">{group.label}</span>{group.badge&&<span className={`min-w-5 rounded-full px-1.5 py-0.5 text-center text-[9px] font-bold ${containsActive?"bg-white/80 text-[#486e70]":"bg-[#edf0ee] text-[#7c8782]"}`}>{group.badge}</span>}<Icon name="chevron" size={13} className={`text-[#9aa49f] transition ${expanded?"rotate-90":""}`}/></>}
          {containsActive&&<span className="absolute left-0 h-5 w-[3px] rounded-r-full bg-[#3b646d]"/>}
        </button>
        {expanded&&<nav className="ml-[18px] mt-1 space-y-0.5 border-l border-[#dfe6e2] pl-3">{group.items.map(item=>{const isActive=active===item;return <button key={item} onClick={()=>setPage(item)} className={`relative flex min-h-8 w-full items-center rounded-lg px-3 py-2 text-left text-[10.5px] font-semibold leading-4 transition ${isActive?"bg-[#edf3f4] text-[#3b646d]":"text-[#74817b] hover:bg-[#f2f5f3] hover:text-[#34443d]"}`}>{item}{isActive&&<span className="absolute -left-[13px] h-4 w-[2px] rounded-full bg-[#3b646d]"/>}</button>})}</nav>}
      </section>})}</div>
    </div>
    <div className="border-t border-[#e6ebe8] p-3">{(!collapsed||mobile)?<><button className="flex w-full items-center gap-3 rounded-xl p-2 text-left transition hover:bg-[#f0f4f2]"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#dce8e4] text-[11px] font-bold text-[#486c6e]">IC</span><span className="min-w-0 flex-1"><span className="block truncate text-[11px] font-bold text-[#2a3933]">Ismail Chowdhury</span><span className="mt-0.5 block text-[9px] text-[#8d9893]">Super Admin</span></span><Icon name="more" size={16} className="text-[#929d97]"/></button><button className="mt-1 flex w-full items-center gap-2 rounded-lg px-3 py-2 text-[10px] font-semibold text-[#708079] transition hover:bg-[#f0f4f2]"><Icon name="store" size={15}/>View storefront<Icon name="arrow" size={12} className="ml-auto"/></button></>:<button className="mx-auto flex h-10 w-10 items-center justify-center rounded-xl bg-[#dce8e4] text-[11px] font-bold text-[#486c6e]">IC</button>}</div>
  </aside>;

  return <div className="min-h-screen bg-[#f5f7f5] text-[#223129]">
    <Sidebar/>{mobileOpen&&<><div onClick={()=>setMobileOpen(false)} className="fixed inset-0 z-40 bg-[#17231f]/30 backdrop-blur-sm lg:hidden"/><Sidebar mobile/></>}
    <div className={`min-h-screen transition-all duration-300 ${shellWidth}`}>
      <header className="sticky top-0 z-30 flex h-[70px] items-center gap-3 border-b border-[#e2e8e5] bg-[#f8faf8]/95 px-4 backdrop-blur-xl sm:px-6 lg:px-7"><button aria-label="Open menu" onClick={()=>setMobileOpen(true)} className="flex h-9 w-9 items-center justify-center rounded-lg border border-[#dde4e1] bg-white text-[#596962] lg:hidden"><Icon name="menu" size={18}/></button><button onClick={()=>setCollapsed(!collapsed)} className="hidden h-9 w-9 items-center justify-center rounded-lg border border-[#dde4e1] bg-white text-[#6e7b75] transition hover:border-[#c6d4cf] hover:text-[#456b6d] lg:flex" aria-label="Toggle sidebar"><Icon name="menu" size={17}/></button><div className="hidden sm:block"><h2 className="text-[13px] font-bold text-[#26352f]">{title}</h2><p className="mt-0.5 text-[9px] font-medium text-[#8e9994]">{subtitle}</p></div><button onClick={()=>setPaletteOpen(true)} className="ml-auto flex h-10 min-w-0 items-center gap-2 rounded-xl border border-[#dce4e0] bg-white px-3 text-[#819089] shadow-[0_1px_2px_rgba(20,45,38,.03)] transition hover:border-[#c3d2cd] sm:w-[280px]"><Icon name="search" size={16}/><span className="truncate text-[11px]">Search anything...</span><kbd className="ml-auto hidden rounded-md border border-[#dfe5e2] bg-[#f6f8f7] px-1.5 py-1 text-[8px] font-bold text-[#8b9691] sm:block">⌘ K</kbd></button>
        <div className="relative"><button aria-label="Open notifications" onClick={()=>setNotificationsOpen(!notificationsOpen)} className="relative flex h-10 w-10 items-center justify-center rounded-xl border border-[#dce4e0] bg-white text-[#64736c] transition hover:border-[#c3d2cd]"><Icon name="bell" size={17}/><span className="absolute right-2 top-2 h-2 w-2 rounded-full border-2 border-white bg-rose-500"/></button>{notificationsOpen&&<div className="absolute right-0 top-12 w-[310px] overflow-hidden rounded-2xl border border-[#dde4e1] bg-white shadow-[0_20px_55px_rgba(24,45,39,.14)]"><div className="flex items-center justify-between border-b border-[#edf0ee] px-4 py-3"><b className="text-[12px]">Notifications</b><span className="text-[9px] font-bold text-[#3b646d]">Mark all read</span></div><div className="divide-y divide-[#edf0ee]">{[["alert","7 COD mismatches need review","Finance · 8 min ago"],["inventory","Niacinamide Serum is low in stock","Inventory · 23 min ago"],["orders","12 new orders need confirmation","Orders · 31 min ago"]].map(([i,t,s])=><button key={t} className="flex w-full gap-3 p-4 text-left hover:bg-[#f9fbfa]"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#edf3f4] text-[#3b646d]"><Icon name={i as IconName} size={15}/></span><span><b className="block text-[10px] text-[#34433d]">{t}</b><small className="mt-1 block text-[9px] text-[#929d97]">{s}</small></span></button>)}</div></div>}</div><button onClick={()=>setQuickAddOpen(true)} className="flex h-10 items-center gap-2 rounded-xl bg-[#3b646d] px-3.5 text-[11px] font-bold text-white shadow-sm transition hover:bg-[#31545c]"><Icon name="plus" size={16}/><span className="hidden md:inline">Quick add</span></button>
      </header>
      <main className="mx-auto max-w-[1550px] p-4 sm:p-6 lg:p-7">{active==="Dashboard"?<Dashboard/>:active==="Business Analytics"?<BusinessAnalyticsWorkspace onNavigate={setPage}/>:active==="Launch Readiness"?<LaunchReadinessWorkspace onNavigate={setPage}/>:active==="Integration Execution"?<IntegrationExecutionWorkspace onNavigate={setPage}/>:active==="Fulfilment Execution"?<FulfilmentExecutionWorkspace onNavigate={setPage}/>:active==="Storefront Execution"?<StorefrontExecutionWorkspace onNavigate={setPage}/>:active==="Launch Verification"?<LaunchVerificationWorkspace onNavigate={setPage}/>:active==="AI Business Assistant"?<AIBusinessAssistantWorkspace onNavigate={setPage}/>:active==="Marketing Performance"?<LiveMarketingPerformanceWorkspace/>:active==="Meta Ads"?<LiveMetaAdsWorkspace/>:active==="Content & Creative Intelligence"?<LiveContentCreativeWorkspace/>:active==="Tracking & Attribution"?<LiveTrackingAttributionWorkspace/>:active==="Retention / AOV / CLV"?<LiveRetentionAovClvWorkspace/>:active==="Workflow Automation"?<LiveWorkflowAutomationWorkspace/>:active==="Alerts"?<LiveAutomationAlertsWorkspace/>:active==="Rules"?<LiveAutomationRulesWorkspace/>:active==="Integrations"?<LiveIntegrationsWorkspace onNavigate={setPage}/>:active==="Audit Logs"?<LiveAuditLogsWorkspace onNavigate={setPage}/>:active==="Backup & Restore"?<LiveBackupRestoreWorkspace onNavigate={setPage}/>:active==="Security Center"?<LiveSecurityCenterWorkspace onNavigate={setPage}/>:active==="Security Audit"?<LiveSecurityAuditWorkspace onNavigate={setPage}/>:active==="Privacy Center"?<LivePrivacyCenterWorkspace onNavigate={setPage}/>:active==="Support Center"?<LiveSupportCenterWorkspace onNavigate={setPage}/>:active==="Production Readiness"?<LiveProductionReadinessWorkspace onNavigate={setPage}/>:active==="Products"?<LiveProductsWorkspace onNavigate={setPage}/>:active==="Add/Edit Product"?<LiveProductEditorWorkspace onNavigate={setPage}/>:active==="Categories"?<CategoriesWorkspace onNavigate={setPage}/>:active==="Concerns"?<ConcernsWorkspace onNavigate={setPage}/>:active==="Brands"?<BrandsWorkspace onNavigate={setPage}/>:active==="Collections"?<CollectionsWorkspace onNavigate={setPage}/>:active==="Offers & Deals"?<LiveOffersDealsWorkspace onNavigate={setPage}/>:active==="Product Recommendations"?<LiveProductRecommendationsWorkspace onNavigate={setPage}/>:active==="Ingredient Intelligence"?<LiveIngredientIntelligenceWorkspace onNavigate={setPage}/>:active==="Inventory"?<InventoryWorkspace onNavigate={setPage}/>:active==="Inventory Intelligence"?<InventoryIntelligenceWorkspace onNavigate={setPage}/>:active==="Purchase Stock Entry"?<PurchaseStockWorkspace onNavigate={setPage}/>:active==="Orders"?<OrdersWorkspace onOpenDetails={openOrderDetails}/>:active==="Order Details"?<OrderDetailsWorkspace order={selectedOrder} onBack={()=>setPage("Orders")} onOpenPacking={()=>setPage("Packing Desk")}/>:active==="Order Risk & Fraud"?<OrderRiskFraudWorkspace onNavigate={setPage}/>:active==="Packing Desk"?<LivePackingDeskWorkspace initialOrderId={selectedOrder.id} onOpenCourier={()=>setPage("Courier & Payments")}/>:active==="Courier & Payments"?<LiveCourierPaymentsWorkspace/>:active==="Returns & Exchanges"?<ReturnsExchangesWorkspace onNavigate={setPage}/>:active==="Checkout & Shipping Rules"?<CheckoutShippingWorkspace/>:active==="Invoice & Thank You Settings"?<PostPurchaseWorkspace/>:active==="Customers"?<LiveCustomersWorkspace/>:active==="Customer Profile"?<LiveCustomersWorkspace initialProfileOpen/>:active==="Customer Intelligence"?<CustomerIntelligenceWorkspace onNavigate={setPage}/>:active==="AI Skin Test & Consultation"?<AISkinTestConsultationWorkspace onNavigate={setPage}/>:active==="Skin Profile / Beauty Passport"?<BeautyPassportWorkspace onNavigate={setPage}/>:active==="Advanced Routine Builder"?<AdvancedRoutineBuilderWorkspace onNavigate={setPage}/>:active==="Routine & Product Compatibility"?<LiveRoutineCompatibilityWorkspace onNavigate={setPage}/>:active==="Replenishment & Reorder Engine"?<ReplenishmentReorderWorkspace onNavigate={setPage}/>:active==="Skin Journey Tracking"?<SkinJourneyTrackingWorkspace onNavigate={setPage}/>:active==="Conversational Commerce Hub"?<ConversationalCommerceWorkspace onNavigate={setPage}/>:active==="Suppliers"?<LiveSuppliersWorkspace onNavigate={setPage}/>:active==="Supplier Analytics"?<SupplierAnalyticsWorkspace onNavigate={setPage}/>:active==="Finance Reconciliation"?<FinanceReconciliationWorkspace onNavigate={setPage}/>:active==="Expenses & Cost Management"?<ExpensesCostWorkspace onNavigate={setPage}/>:active==="Profitability Control"?<ProfitabilityControlWorkspace onNavigate={setPage}/>:active==="Reports & Insights"?<ReportsInsightsWorkspace onNavigate={setPage}/>:active==="Homepage CMS"?<LiveHomepageCmsWorkspace/>:active==="Banner CMS"?<LiveBannerCmsWorkspace/>:active==="Header & Navigation"?<LiveHeaderNavigationWorkspace/>:active==="Footer CMS"?<LiveFooterCmsWorkspace/>:active==="Reviews & Real Results"?<LiveReviewsResultsWorkspace/>:active==="SEO & Storefront Health"?<LiveSeoStorefrontWorkspace/>:active==="Roles & Permissions"?<LiveRolesPermissionsWorkspace/>:active==="Settings"?<LiveSettingsWorkspace/>:<ModulePage page={active}/>}<footer className="mt-7 flex flex-col gap-2 border-t border-[#e0e6e3] py-5 text-[9px] font-semibold text-[#98a29d] sm:flex-row sm:items-center sm:justify-between"><span>BrandnBeauty Admin UI Concept · 2026</span><button onClick={()=>{setToast(true);setTimeout(()=>setToast(false),2600)}} className="text-left text-[#637d77] hover:text-[#3f696b]">Why this design works →</button></footer></main>
    </div>
    {paletteOpen&&<CommandPalette onClose={()=>setPaletteOpen(false)} onNavigate={setPage}/>} {quickAddOpen&&<QuickAdd onClose={()=>setQuickAddOpen(false)}/>} {toast&&<div className="fixed bottom-5 right-5 z-50 max-w-sm rounded-xl bg-[#223c3f] px-4 py-3 text-[11px] font-semibold leading-5 text-white shadow-xl">Calmer hierarchy, smaller radii, focused actions and scalable navigation—while keeping BrandnBeauty’s teal identity.</div>}
  </div>;
}

function AdminWorkspaceLoading() {
  return <div className="flex min-h-screen items-center justify-center bg-[#f5f7f5] text-[12px] font-semibold text-[#66736d]">Opening BrandnBeauty admin…</div>;
}

export default function Home() {
  return <Suspense fallback={<AdminWorkspaceLoading/>}><AdminWorkspace/></Suspense>;
}
